{
  "name": "EduAmigo: Tutor Inteligente",
  "description": "Una aplicación educativa que utiliza IA para explicar cualquier tema de forma sencilla, adaptada a la edad y curso del estudiante, con ejemplos prácticos y divertidos.",
  "requestFramePermissions": ["microphone"]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type GradeLevel = 
  | '1º Primaria' | '2º Primaria' | '3º Primaria' | '4º Primaria' | '5º Primaria' | '6º Primaria'
  | '1º ESO' | '2º ESO' | '3º ESO' | '4º ESO'
  | '1º Bachillerato' | '2º Bachillerato';

export type Subject = 
  | 'Matemáticas' | 'Ciencias Naturales' | 'Historia' | 'Lengua y Literatura' 
  | 'Inglés' | 'Geografía' | 'Física y Química' | 'Arte';

export interface ExplanationResponse {
  explanation: string;
  examples: string[];
  funFact: string;
}

export interface HistoryItem {
  id: string;
  grade: GradeLevel;
  subject: Subject;
  question: string;
  answer: ExplanationResponse;
  timestamp: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { GradeLevel, Subject, ExplanationResponse } from "../types";

export const getExplanation = async (
  grade: GradeLevel,
  subject: Subject,
  question: string
): Promise<ExplanationResponse> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Responde a la siguiente pregunta: "${question}" para un estudiante de ${grade} en la materia de ${subject}.`,
    config: {
      systemInstruction: `Eres un tutor experto y amable. Tu misión es explicar conceptos complejos de la forma más sencilla posible, usando un lenguaje perfectamente adaptado a la edad del estudiante (${grade}). 

      Reglas de respuesta:
      1. Usa analogías que un niño/joven de esa edad entendería.
      2. Divide la explicación en pasos lógicos si es necesario.
      3. Proporciona exactamente 3 ejemplos prácticos y cotidianos.
      4. Incluye un "Dato Curioso" (funFact) relacionado con el tema.
      5. Responde siempre en español.
      6. Formatea la respuesta como JSON.`,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          explanation: {
            type: Type.STRING,
            description: "La explicación sencilla y adaptada al curso.",
          },
          examples: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            description: "Tres ejemplos prácticos.",
          },
          funFact: {
            type: Type.STRING,
            description: "Un dato curioso sobre el tema.",
          },
        },
        required: ["explanation", "examples", "funFact"],
      },
    },
  });

  try {
    const data = JSON.parse(response.text || '{}');
    return data as ExplanationResponse;
  } catch (error) {
    console.error("Error parsing Gemini response:", error);
    throw new Error("No se pudo procesar la explicación. ¡Inténtalo de nuevo!");
  }
};

import React, { useState, useEffect } from 'react';
import { GradeLevel, Subject, ExplanationResponse, HistoryItem } from './types';
import { getExplanation } from './services/geminiService';
import Header from './components/Header';
import StudyForm from './components/StudyForm';
import ResultDisplay from './components/ResultDisplay';
import HistorySidebar from './components/HistorySidebar';

const App: React.FC = () => {
  const [grade, setGrade] = useState<GradeLevel>('1º Primaria');
  const [subject, setSubject] = useState<Subject>('Matemáticas');
  const [question, setQuestion] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ExplanationResponse | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [error, setError] = useState<string | null>(null);

  // Load history from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('eduamigo_history');
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load history", e);
      }
    }
  }, []);

  // Save history to localStorage
  useEffect(() => {
    localStorage.setItem('eduamigo_history', JSON.stringify(history));
  }, [history]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!question.trim()) return;

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const data = await getExplanation(grade, subject, question);
      setResult(data);

      const newItem: HistoryItem = {
        id: crypto.randomUUID(),
        grade,
        subject,
        question,
        answer: data,
        timestamp: Date.now(),
      };

      setHistory(prev => [newItem, ...prev].slice(0, 20));
    } catch (err: any) {
      setError(err.message || 'Ocurrió un error inesperado.');
    } finally {
      setLoading(false);
    }
  };

  const handleHistorySelect = (item: HistoryItem) => {
    setGrade(item.grade);
    setSubject(item.subject);
    setQuestion(item.question);
    setResult(item.answer);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#f0f9ff]">
      {/* Sidebar for Desktop */}
      <aside className="hidden md:block w-80 bg-white border-r border-blue-100 p-6 overflow-y-auto h-screen sticky top-0">
        <HistorySidebar history={history} onSelect={handleHistorySelect} />
      </aside>

      <main className="flex-1 p-4 md:p-8 max-w-4xl mx-auto w-full pb-24 md:pb-8">
        <Header />

        <div className="mt-8 space-y-8">
          <StudyForm 
            grade={grade} 
            setGrade={setGrade}
            subject={subject}
            setSubject={setSubject}
            question={question}
            setQuestion={setQuestion}
            onSubmit={handleSubmit}
            loading={loading}
          />

          {error && (
            <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded shadow-sm text-red-700 animate-pulse">
              <p className="font-bold">¡Ups! Algo salió mal</p>
              <p>{error}</p>
            </div>
          )}

          <ResultDisplay 
            result={result} 
            loading={loading} 
            grade={grade}
            subject={subject}
          />
        </div>

        {/* Mobile History (Floating Button or Drawer could go here, keeping it simple with a section at bottom for mobile) */}
        <div className="md:hidden mt-12 pb-20">
           <HistorySidebar history={history} onSelect={handleHistorySelect} />
        </div>
      </main>
    </div>
  );
};

export default App;

