import React from 'react';
import { HistoryItem, Subject } from '../types';

interface ParentDashboardProps {
  history: HistoryItem[];
  onSelectItem: (item: HistoryItem) => void;
}

const ParentDashboard: React.FC<ParentDashboardProps> = ({ history, onSelectItem }) => {
  const totalQuestions = history.length;

  // Calculate subject stats
  const subjectStats = history.reduce((acc, curr) => {
    acc[curr.subject] = (acc[curr.subject] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  const sortedStats = Object.entries(subjectStats).sort((a, b) => b[1] - a[1]);

  const downloadReport = () => {
    const report = history.map(h => (
      `FECHA: ${new Date(h.timestamp).toLocaleString()}\n` +
      `MATERIA: ${h.subject} (${h.grade})\n` +
      `PREGUNTA: ${h.question}\n` +
      `RESPUESTA: ${h.answer.explanation}\n` +
      `-------------------------------------------\n`
    )).join('\n');

    const blob = new Blob([report], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `reporte-estudio-${new Date().toISOString().split('T')[0]}.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-8 pb-10">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Quick Stats */}
        <div className="bg-white p-6 rounded-3xl border border-blue-100 shadow-sm">
          <p className="text-blue-500 text-sm font-bold uppercase mb-1">Total Consultas</p>
          <p className="text-4xl font-bold text-blue-900">{totalQuestions}</p>
          <p className="text-xs text-blue-400 mt-2">Preguntas realizadas por el niño</p>
        </div>

        <div className="bg-white p-6 rounded-3xl border border-blue-100 shadow-sm col-span-1 md:col-span-2">
          <div className="flex justify-between items-center mb-4">
            <p className="text-blue-500 text-sm font-bold uppercase">Temas más estudiados</p>
            <button 
              onClick={downloadReport}
              className="text-xs bg-blue-600 text-white px-3 py-1.5 rounded-lg font-bold hover:bg-blue-700 transition-colors flex items-center gap-2"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
              </svg>
              Descargar Reporte
            </button>
          </div>
          <div className="space-y-3">
            {sortedStats.length > 0 ? sortedStats.slice(0, 3).map(([subject, count]) => (
              <div key={subject}>
                <div className="flex justify-between text-xs font-bold text-blue-800 mb-1">
                  <span>{subject}</span>
                  <span>{count}</span>
                </div>
                <div className="w-full bg-blue-50 h-2 rounded-full overflow-hidden">
                  <div 
                    className="bg-blue-500 h-full rounded-full transition-all duration-1000"
                    style={{ width: `${(count / totalQuestions) * 100}%` }}
                  ></div>
                </div>
              </div>
            )) : (
              <p className="text-blue-400 text-sm italic">Sin datos suficientes aún.</p>
            )}
          </div>
        </div>
      </div>

      {/* Detailed Log */}
      <div className="bg-white rounded-3xl border border-blue-100 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-blue-50 bg-blue-50/30">
          <h3 className="text-lg font-bold text-blue-900">Registro Detallado de Actividad</h3>
        </div>
        <div className="divide-y divide-blue-50">
          {history.length > 0 ? history.map((item) => (
            <div key={item.id} className="p-6 hover:bg-blue-50/50 transition-colors">
              <div className="flex flex-col md:flex-row justify-between gap-4">
                <div className="flex-1 space-y-2">
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] bg-blue-100 text-blue-600 px-2 py-0.5 rounded font-bold uppercase">{item.subject}</span>
                    <span className="text-[10px] bg-green-100 text-green-600 px-2 py-0.5 rounded font-bold uppercase">{item.grade}</span>
                    <span className="text-[10px] text-gray-400 ml-auto">{new Date(item.timestamp).toLocaleString()}</span>
                  </div>
                  <p className="text-blue-900 font-bold italic">"{item.question}"</p>
                  <p className="text-blue-700 text-sm line-clamp-3">{item.answer.explanation}</p>
                </div>
                <div className="flex md:flex-col justify-end gap-2">
                    <button 
                      onClick={() => onSelectItem(item)}
                      className="text-xs border border-blue-200 text-blue-600 px-4 py-2 rounded-xl font-bold hover:bg-white transition-all shadow-sm"
                    >
                      Ver Respuesta Completa
