import StudyForm from './components/StudyForm';
import ResultDisplay from './components/ResultDisplay';
import HistorySidebar from './components/HistorySidebar';
import ParentDashboard from './components/ParentDashboard';
import Login from './components/Login';
import AuthScreen from './components/AuthScreen';
import ParentAuthModal from './components/ParentAuthModal';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState<UserRole>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('student');
  const [isParentUnlocked, setIsParentUnlocked] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);

  const [grade, setGrade] = useState<GradeLevel>('1º Primaria');
  const [subject, setSubject] = useState<Subject>('Matemáticas');
  const [question, setQuestion] = useState('');
  const [loading, setLoading] = useState(false);
  const [isDictating, setIsDictating] = useState(false);
  const [result, setResult] = useState<ExplanationResponse | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isPlayingAudio, setIsPlayingAudio] = useState<string | null>(null);

  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    // Check if session exists (could be in sessionStorage for this browser instance)
    const sessionAuth = sessionStorage.getItem('eduamigo_auth');
    if (sessionAuth) {
      setIsAuthenticated(true);
    }
  }, []);

  useEffect(() => {
    if (userRole === 'demo') {
      const demoHistory: HistoryItem[] = [
        {
          id: '1',
          grade: '4º Primaria',
          subject: 'Ciencias Naturales',
          question: '¿Por qué llueve?',
          timestamp: Date.now() - 3600000,
          answer: {
            explanation: "La lluvia ocurre porque el agua de los ríos y mares se calienta con el sol y se convierte en vapor. Ese vapor sube al cielo, forma nubes y cuando se enfría, ¡vuelve a caer en forma de gotas!",
            examples: ["Como cuando sale vapor de una sopa caliente", "Como el vaho que dejas en un espejo al respirar", "Como las gotitas que se forman fuera de un vaso de agua muy fría"],
            funFact: "¡A veces las gotas de lluvia tardan mucho tiempo en caer desde la nube hasta el suelo!"
          }
        }
      ];
      setHistory(demoHistory);
    } else if (userRole) {
      const saved = localStorage.getItem('eduamigo_history');
      if (saved) {
        try {
          setHistory(JSON.parse(saved));
        } catch (e) {
          console.error("Failed to load history", e);
        }
      }
    }
  }, [userRole]);

  useEffect(() => {
    if (userRole && userRole !== 'demo') {
      localStorage.setItem('eduamigo_history', JSON.stringify(history));
    }
  }, [history, userRole]);

  const handleAuthenticated = (email: string) => {
    setIsAuthenticated(true);
    sessionStorage.setItem('eduamigo_auth', 'true');
  };

  const handleDemoMode = () => {
    setIsAuthenticated(true);
    setUserRole('demo');
    sessionStorage.setItem('eduamigo_auth', 'demo');
  };

  const handleRoleSelection = (role: UserRole) => {
    setUserRole(role);
    if (role === 'parent') {
      setShowAuthModal(true);
    }
  };

  const handleParentAccess = (success: boolean) => {
    if (success) {
      setIsParentUnlocked(true);
      setViewMode('parent');
      setShowAuthModal(false);
    } else {
      setViewMode('student');
      setShowAuthModal(false);
    }
  };

  const toggleViewMode = (mode: ViewMode) => {
    if (mode === 'parent' && !isParentUnlocked) {
      setShowAuthModal(true);
    } else {
      setViewMode(mode);
    }
  };

  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!question.trim()) return;
    if (userRole === 'demo') {
      alert("En modo DEMO las consultas reales están desactivadas. ¡Entra como Estudiante para preguntar lo que quieras!");
      return;
    }

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const data = await getExplanation(grade, subject, question);
      setResult(data);

      const newItem: HistoryItem = {
        id: crypto.randomUUID(),
        grade,
        subject,
        question,
        answer: data,
        timestamp: Date.now(),
      };

      setHistory(prev => [newItem, ...prev].slice(0, 50));
    } catch (err: any) {
      setError(err.message || 'Ocurrió un error inesperado.');
    } finally {
      setLoading(false);
    }
  };

  const handleHistorySelect = (item: HistoryItem) => {
    setViewMode('student');
    setGrade(item.grade);
    setSubject(item.subject);
    setQuestion(item.question);
    setResult(item.answer);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleSpeak = async (text: string, id: string) => {
    if (isPlayingAudio) return;
    setIsPlayingAudio(id);
    try {
      await generateSpeech(text);
    } catch (err) {
      console.error("Error playing audio:", err);
    } finally {
      setTimeout(() => setIsPlayingAudio(null), 1000);
    }
  };

  const toggleDictation = () => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Lo siento, tu navegador no soporta el dictado por voz.");
      return;
    }
    if (isDictating) {
      if (recognitionRef.current) recognitionRef.current.stop();
      return;
    }
    if (recognitionRef.current) recognitionRef.current.abort();

    const recognition = new SpeechRecognition();
    recognition.lang = 'es-ES';
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.onstart = () => { setIsDictating(true); setError(null); };
    recognition.onresult = (event: any) => { setQuestion(event.results[0][0].transcript); };
    recognition.onerror = (event: any) => {
      if (event.error !== 'aborted') {
        if (event.error === 'not-allowed') setError("Permiso de micrófono denegado.");
        else setError(`Error de dictado: ${event.error}`);
      }
      setIsDictating(false);
    };
    recognition.onend = () => { setIsDictating(false); };
    recognitionRef.current = recognition;
    try { recognition.start(); } catch (e) { setIsDictating(false); }
  };

  if (!isAuthenticated) {
    return <AuthScreen onAuthenticated={handleAuthenticated} onDemo={handleDemoMode} />;
  }

  if (!userRole) {
    return <Login onLogin={handleRoleSelection} onLogout={() => {setIsAuthenticated(false); sessionStorage.removeItem('eduamigo_auth');}} />;
  }

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#f0f9ff]">
      {showAuthModal && <ParentAuthModal onResult={handleParentAccess} onCancel={() => { setShowAuthModal(false); setViewMode('student'); }} />}

      <aside className="hidden md:block w-80 bg-white border-r border-blue-100 p-6 overflow-y-auto h-screen sticky top-0">
        <div className="mb-4">
            <button 
              onClick={() => { setUserRole(null); setViewMode('student'); setIsParentUnlocked(false); }}
              className="text-xs font-bold text-blue-400 hover:text-blue-600 flex items-center gap-1"
            >
              ← Cambiar Perfil
            </button>
        </div>
        <HistorySidebar history={history} onSelect={handleHistorySelect} />
      </aside>

      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8">
        <Header 
          viewMode={viewMode} 
          setViewMode={toggleViewMode} 
          userRole={userRole} 
        />

        {userRole === 'demo' && (
          <div className="mt-4 bg-yellow-100 border border-yellow-200 text-yellow-800 px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2">
            <span>✨ Estás en MODO DEMO.</span>
            <button onClick={() => {setUserRole(null); setViewMode('student');}} className="underline">Ver perfiles reales</button>
          </div>
        )}

        <div className="mt-8">
          {viewMode === 'student' ? (
            <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
              <StudyForm 
                grade={grade} 
                setGrade={setGrade}
                subject={subject}
                setSubject={setSubject}
                question={question}
                setQuestion={setQuestion}
                onSubmit={handleSubmit}
                loading={loading}
                isDictating={isDictating}
                onDictate={toggleDictation}
              />

              {error && (
                <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded shadow-sm text-red-700 animate-pulse">
                  <p className="font-bold">¡Atención!</p>
                  <p>{error}</p>
                </div>
              )}

              <ResultDisplay 
                result={result} 
                loading={loading} 
                grade={grade}
                subject={subject}
                onSpeak={handleSpeak}
                isPlayingId={isPlayingAudio}
              />
            </div>
          ) : (
            <div className="animate-in slide-in-from-bottom-4 duration-500">
              <ParentDashboard history={history} onSelectItem={handleHistorySelect} />
            </div>
          )}
        </div>

        <div className="md:hidden mt-12 pb-20">
           <HistorySidebar history={history} onSelect={handleHistorySelect} />
        </div>
      </main>
    </div>
  );
};

export default App;

export type GradeLevel = 
  | '1º Primaria' | '2º Primaria' | '3º Primaria' | '4º Primaria' | '5º Primaria' | '6º Primaria'
  | '1º ESO' | '2º ESO' | '3º ESO' | '4º ESO'
  | '1º Bachillerato' | '2º Bachillerato';

export type Subject = 
  | 'Matemáticas' | 'Ciencias Naturales' | 'Historia' | 'Lengua y Literatura' 
  | 'Inglés' | 'Geografía' | 'Física y Química' | 'Arte';

export type Region = 
  | 'Andalucía' | 'Aragón' | 'Asturias' | 'Baleares' | 'Canarias' | 'Cantabria' 
  | 'Castilla-La Mancha' | 'Castilla y León' | 'Cataluña' | 'Comunidad Valenciana' 
  | 'Extremadura' | 'Galicia' | 'Madrid' | 'Murcia' | 'Navarra' | 'País Vasco' | 'La Rioja';

export type ViewMode = 'student' | 'parent' | 'library';
export type UserRole = 'student' | 'parent' | 'demo' | null;

export interface ExplanationResponse {
  explanation: string;
  examples: string[];
  funFact: string;
}

export interface SyllabusTopic {
  id: string;
  title: string;
  description: string;
  subtopics: string[];
}

export interface TopicDetail {
  title: string;
  content: string;
  keyPoints: string[];
  examples: string[];
  summary: string;
}

export interface HistoryItem {
  id: string;
  grade: GradeLevel;
  subject: Subject;
  region: Region;
  question: string;
  answer: ExplanationResponse;
  timestamp: number;
}

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { GradeLevel, Subject, ExplanationResponse, Region, SyllabusTopic, TopicDetail } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getExplanation = async (
  grade: GradeLevel,
  subject: Subject,
  question: string,
  region: Region
): Promise<ExplanationResponse> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Explica: "${question}" para ${grade} en ${subject} siguiendo el currículo de ${region}.`,
    config: {
      systemInstruction: `Eres un tutor experto en el sistema educativo español (LOMLOE). 
      Adapta la respuesta a la normativa de ${region} para el nivel ${grade}.
      Usa lenguaje ameno, 3 ejemplos claros y un dato curioso. Formato JSON.`,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          explanation: { type: Type.STRING },
          examples: { type: Type.ARRAY, items: { type: Type.STRING } },
          funFact: { type: Type.STRING },
        },
        required: ["explanation", "examples", "funFact"],
      },
    },
  });
  return JSON.parse(response.text || '{}') as ExplanationResponse;
};

export const getSyllabus = async (
  region: Region,
  grade: GradeLevel,
  subject: Subject
): Promise<SyllabusTopic[]> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Genera el temario oficial (LOMLOE) para ${subject} en ${grade} de la comunidad de ${region}.`,
    config: {
      systemInstruction: `Genera una lista de 6 a 8 bloques temáticos principales. 
      Cada bloque debe tener un título, una descripción corta y una lista de subtemas específicos.
      Devuelve un array de objetos JSON.`,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            title: { type: Type.STRING },
            description: { type: Type.STRING },
            subtopics: { type: Type.ARRAY, items: { type: Type.STRING } },
          },
          required: ["id", "title", "description", "subtopics"],
        },
      },
    },
  });
  return JSON.parse(response.text || '[]') as SyllabusTopic[];
};

export const getTopicDetail = async (
  region: Region,
  grade: GradeLevel,
  subject: Subject,
  topic: string,
  subtopic: string
): Promise<TopicDetail> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Escribe un capítulo de libro de texto sobre "${subtopic}" dentro del bloque "${topic}" para ${grade} en ${region}.`,
    config: {
      systemInstruction: `Actúa como una editorial de libros de texto de prestigio. 
      El contenido debe ser riguroso pero adaptado a la edad. 
      Incluye: Desarrollo extenso (content), puntos clave (keyPoints), ejemplos resueltos (examples) y un resumen final (summary).`,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          content: { type: Type.STRING },
          keyPoints: { type: Type.ARRAY, items: { type: Type.STRING } },
          examples: { type: Type.ARRAY, items: { type: Type.STRING } },
          summary: { type: Type.STRING },
        },
        required: ["title", "content", "keyPoints", "examples", "summary"],
      },
    },
  });
  return JSON.parse(response.text || '{}') as TopicDetail;
};

export const generateSpeech = async (text: string): Promise<void> => {
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
    },
  });
  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) return;
  const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
  const buffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
  const source = ctx.createBufferSource();
  source.buffer = buffer;
  source.connect(ctx.destination);
  source.start();
};

function decode(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
}

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
  }
  return buffer;
}

import React, { useState, useEffect, useRef } from 'react';
import { GradeLevel, Subject, ExplanationResponse, HistoryItem, ViewMode, UserRole, Region } from './types';
import { getExplanation, generateSpeech } from './services/geminiService';
import Header from './components/Header';
import StudyForm from './components/StudyForm';
import ResultDisplay from './components/ResultDisplay';
import HistorySidebar from './components/HistorySidebar';
import ParentDashboard from './components/ParentDashboard';
import Login from './components/Login';
import AuthScreen from './components/AuthScreen';
import ParentAuthModal from './components/ParentAuthModal';
import LibraryBrowser from './components/LibraryBrowser';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState<UserRole>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('student');
  const [region, setRegion] = useState<Region>('Madrid');
  const [isParentUnlocked, setIsParentUnlocked] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);

  const [grade, setGrade] = useState<GradeLevel>('1º Primaria');
  const [subject, setSubject] = useState<Subject>('Matemáticas');
  const [question, setQuestion] = useState('');
  const [loading, setLoading] = useState(false);
  const [isDictating, setIsDictating] = useState(false);
  const [result, setResult] = useState<ExplanationResponse | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isPlayingAudio, setIsPlayingAudio] = useState<string | null>(null);

  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const sessionAuth = sessionStorage.getItem('eduamigo_auth');
    if (sessionAuth) setIsAuthenticated(true);
    const savedRegion = localStorage.getItem('eduamigo_region');
    if (savedRegion) setRegion(savedRegion as Region);
  }, []);

  useEffect(() => {
    if (userRole && userRole !== 'demo') {
      localStorage.setItem('eduamigo_history', JSON.stringify(history));
      localStorage.setItem('eduamigo_region', region);
    }
  }, [history, userRole, region]);

  const handleAuthenticated = (email: string) => {
    setIsAuthenticated(true);
    sessionStorage.setItem('eduamigo_auth', 'true');
  };

  const handleDemoMode = () => {
    setIsAuthenticated(true);
    setUserRole('demo');
    sessionStorage.setItem('eduamigo_auth', 'demo');
  };

  const handleRoleSelection = (role: UserRole) => {
    setUserRole(role);
    if (role === 'parent') setShowAuthModal(true);
  };

  const handleParentAccess = (success: boolean) => {
    if (success) {
      setIsParentUnlocked(true);
      setViewMode('parent');
      setShowAuthModal(false);
    } else {
      setViewMode('student');
      setShowAuthModal(false);
    }
  };

  const toggleViewMode = (mode: ViewMode) => {
    if (mode === 'parent' && !isParentUnlocked) {
      setShowAuthModal(true);
    } else {
      setViewMode(mode);
    }
  };

  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!question.trim()) return;
    setLoading(true);
    setError(null);
    try {
      const data = await getExplanation(grade, subject, question, region);
      setResult(data);
      const newItem: HistoryItem = {
        id: crypto.randomUUID(),
        grade, subject, region, question, answer: data,
        timestamp: Date.now(),
      };
      setHistory(prev => [newItem, ...prev].slice(0, 50));
    } catch (err: any) {
      setError('Error al conectar con el tutor inteligente.');
    } finally {
      setLoading(false);
    }
  };

  const handleSpeak = async (text: string, id: string) => {
    if (isPlayingAudio) return;
    setIsPlayingAudio(id);
    try {
      await generateSpeech(text);
    } catch (err) {
      console.error(err);
    } finally {
      setTimeout(() => setIsPlayingAudio(null), 1000);
    }
  };

  if (!isAuthenticated) return <AuthScreen onAuthenticated={handleAuthenticated} onDemo={handleDemoMode} />;
  if (!userRole) return <Login onLogin={handleRoleSelection} onLogout={() => {setIsAuthenticated(false); sessionStorage.removeItem('eduamigo_auth');}} />;

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#f0f9ff]">
      {showAuthModal && <ParentAuthModal onResult={handleParentAccess} onCancel={() => { setShowAuthModal(false); setViewMode('student'); }} />}

      <aside className="hidden md:block w-80 bg-white border-r border-blue-100 p-6 overflow-y-auto h-screen sticky top-0">
        <div className="mb-6">
            <button onClick={() => { setUserRole(null); setViewMode('student'); setIsParentUnlocked(false); }} className="text-xs font-bold text-blue-400 hover:text-blue-600 flex items-center gap-1">← Cambiar Perfil</button>
            <div className="mt-4 p-3 bg-blue-50 rounded-xl">
              <label className="text-[10px] font-bold text-blue-400 uppercase">Comunidad Autónoma</label>
              <select 
                value={region} 
                onChange={(e) => setRegion(e.target.value as Region)}
                className="w-full bg-transparent text-sm font-bold text-blue-900 outline-none cursor-pointer"
              >
                {['Madrid', 'Andalucía', 'Cataluña', 'Galicia', 'País Vasco', 'Comunidad Valenciana', 'Aragón', 'Asturias', 'Baleares', 'Canarias', 'Cantabria', 'Castilla-La Mancha', 'Castilla y León', 'Extremadura', 'Murcia', 'Navarra', 'La Rioja'].map(r => <option key={r} value={r}>{r}</option>)}
              </select>
            </div>
        </div>
        <HistorySidebar history={history} onSelect={(item) => { setViewMode('student'); setGrade(item.grade); setSubject(item.subject); setQuestion(item.question); setResult(item.answer); }} />
      </aside>

      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8">
        <Header viewMode={viewMode} setViewMode={toggleViewMode} userRole={userRole} />

        <div className="mt-8">
          {viewMode === 'student' ? (
            <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
              <StudyForm grade={grade} setGrade={setGrade} subject={subject} setSubject={setSubject} question={question} setQuestion={setQuestion} onSubmit={handleSubmit} loading={loading} />
              {error && <div className="bg-red-50 p-4 rounded shadow-sm text-red-700 font-bold">{error}</div>}
              <ResultDisplay result={result} loading={loading} grade={grade} subject={subject} onSpeak={handleSpeak} isPlayingId={isPlayingAudio} />
            </div>
          ) : viewMode === 'library' ? (
            <LibraryBrowser region={region} grade={grade} setGrade={setGrade} />
          ) : (
            <ParentDashboard history={history} onSelectItem={(item) => { setViewMode('student'); setResult(item.answer); }} />
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { ViewMode, UserRole } from '../types';

