      setTopicDetail(null);
      setUserAnswers({});
      setShowFeedback({});
    }
  }, [selectedSubject, region, grade]);

  const loadSyllabus = async () => {
    if (!selectedSubject) return;
    setLoading(true);
    try {
      const data = await getSyllabus(region, grade, selectedSubject);
      setSyllabus(data);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const loadDetail = async (topicTitle: string, sub: string) => {
    if (!selectedSubject) return;
    setLoading(true);
    setUserAnswers({});
    setShowFeedback({});
    try {
      const detail = await getTopicDetail(region, grade, selectedSubject, topicTitle, sub);
      setTopicDetail(detail);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

