                        const hasFeedback = showFeedback[ex.id || idx];

                        let bgColor = "bg-blue-50/50 hover:bg-blue-100/50";
                        let borderColor = "border-transparent";

                        if (isSelected) {
                          bgColor = "bg-blue-100";
                          borderColor = "border-blue-500";
                        }

                        if (hasFeedback) {
                          if (isCorrect) {
                            bgColor = "bg-green-100";
                            borderColor = "border-green-500";
                          } else if (isSelected) {
                            bgColor = "bg-red-100";
                            borderColor = "border-red-500";
                          }
