                            key={oIdx}
                            onClick={() => handleAnswerSelect(ex.id || idx, oIdx)}
                            disabled={hasFeedback}
                            className={`p-4 rounded-2xl border-2 text-left transition-all flex items-center gap-3 ${bgColor} ${borderColor} ${hasFeedback ? 'cursor-default' : 'cursor-pointer active:scale-[0.98]'}`}
