/**
 * Helper to execute API calls with exponential backoff for 429 and 5xx errors.
 */
async function executeWithRetry<T>(fn: () => Promise<T>, maxRetries = 3): Promise<T> {
  let lastError: any;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error: any) {
      lastError = error;
      const status = error?.status || (error?.message?.includes('429') ? 429 : 0);

      // Retry on 429 (Quota) or 5xx (Server error)
      if (attempt < maxRetries && (status === 429 || (status >= 500 && status <= 599))) {
        const delay = Math.pow(2, attempt) * 1000 + Math.random() * 1000;
        console.warn(`API Error ${status}. Retrying in ${Math.round(delay)}ms... (Attempt ${attempt + 1}/${maxRetries})`);
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw error;
    }
  }
  throw lastError;
}

