    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Escribe un capítulo de libro de texto sobre "${subtopic}" dentro del bloque "${topic}" para ${grade} en ${region} e incluye 3 ejercicios de repaso.`,
      config: {
        systemInstruction: `Actúa como una editorial de libros de texto de prestigio. 
        El contenido debe ser riguroso pero adaptado a la edad. 
        Incluye: Desarrollo extenso (content), puntos clave (keyPoints), ejemplos resueltos (examples), un resumen final (summary) y 3 ejercicios de opción múltiple (exercises).`,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            content: { type: Type.STRING },
            keyPoints: { type: Type.ARRAY, items: { type: Type.STRING } },
            examples: { type: Type.ARRAY, items: { type: Type.STRING } },
            summary: { type: Type.STRING },
            exercises: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  question: { type: Type.STRING },
                  options: { type: Type.ARRAY, items: { type: Type.STRING } },
                  correctIndex: { type: Type.NUMBER },
                  explanation: { type: Type.STRING },
                },
                required: ["id", "question", "options", "correctIndex", "explanation"],
              }
            }
          },
          required: ["title", "content", "keyPoints", "examples", "summary", "exercises"],
        },
      },
    });
    return JSON.parse(response.text || '{}') as TopicDetail;
  });
};

export const generateSpeech = async (text: string): Promise<void> => {
  return executeWithRetry(async () => {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
      },
    });
    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!base64Audio) return;
    const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const buffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.start();
  });
};

function decode(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
}

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
  }
  return buffer;
}

import React, { useState, useEffect, useRef } from 'react';
import { GradeLevel, Subject, ExplanationResponse, HistoryItem, ViewMode, UserRole, Region } from './types';
import { getExplanation, generateSpeech } from './services/geminiService';
import Header from './components/Header';
import StudyForm from './components/StudyForm';
import ResultDisplay from './components/ResultDisplay';
import HistorySidebar from './components/HistorySidebar';
import ParentDashboard from './components/ParentDashboard';
import Login from './components/Login';
import AuthScreen from './components/AuthScreen';
import ParentAuthModal from './components/ParentAuthModal';
import LibraryBrowser from './components/LibraryBrowser';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState<UserRole>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('student');
  const [region, setRegion] = useState<Region>('Madrid');
  const [isParentUnlocked, setIsParentUnlocked] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);

  const [grade, setGrade] = useState<GradeLevel>('1º Primaria');
  const [subject, setSubject] = useState<Subject>('Matemáticas');
  const [question, setQuestion] = useState('');
  const [loading, setLoading] = useState(false);
  const [isDictating, setIsDictating] = useState(false);
  const [result, setResult] = useState<ExplanationResponse | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isPlayingAudio, setIsPlayingAudio] = useState<string | null>(null);

  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const sessionAuth = sessionStorage.getItem('eduamigo_auth');
    if (sessionAuth) setIsAuthenticated(true);
    const savedRegion = localStorage.getItem('eduamigo_region');
    if (savedRegion) setRegion(savedRegion as Region);
  }, []);

  useEffect(() => {
    if (userRole && userRole !== 'demo') {
      localStorage.setItem('eduamigo_history', JSON.stringify(history));
      localStorage.setItem('eduamigo_region', region);
    }
  }, [history, userRole, region]);

  const handleAuthenticated = (email: string) => {
    setIsAuthenticated(true);
    sessionStorage.setItem('eduamigo_auth', 'true');
  };

  const handleDemoMode = () => {
    setIsAuthenticated(true);
    setUserRole('demo');
    sessionStorage.setItem('eduamigo_auth', 'demo');
  };

  const handleRoleSelection = (role: UserRole) => {
    setUserRole(role);
    if (role === 'parent') setShowAuthModal(true);
  };

  const handleParentAccess = (success: boolean) => {
    if (success) {
      setIsParentUnlocked(true);
      setViewMode('parent');
      setShowAuthModal(false);
    } else {
      setViewMode('student');
      setShowAuthModal(false);
    }
  };

  const toggleViewMode = (mode: ViewMode) => {
    if (mode === 'parent' && !isParentUnlocked) {
      setShowAuthModal(true);
    } else {
      setViewMode(mode);
    }
  };

  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!question.trim()) return;
    setLoading(true);
    setError(null);
    try {
      const data = await getExplanation(grade, subject, question, region);
      setResult(data);
      const newItem: HistoryItem = {
        id: crypto.randomUUID(),
        grade, subject, region, question, answer: data,
        timestamp: Date.now(),
      };
      setHistory(prev => [newItem, ...prev].slice(0, 50));
    } catch (err: any) {
      console.error(err);
      if (err?.message?.includes('429') || err?.status === 429) {
        setError('¡Vaya! Hemos alcanzado el límite de preguntas por ahora. Por favor, espera un minuto y vuelve a intentarlo. ⏳');
      } else {
        setError('Error al conectar con el tutor inteligente. Verifica tu conexión.');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleSpeak = async (text: string, id: string) => {
    if (isPlayingAudio) return;
    setIsPlayingAudio(id);
    try {
      await generateSpeech(text);
    } catch (err) {
      console.error(err);
    } finally {
      setTimeout(() => setIsPlayingAudio(null), 1000);
    }
  };

  if (!isAuthenticated) return <AuthScreen onAuthenticated={handleAuthenticated} onDemo={handleDemoMode} />;
  if (!userRole) return <Login onLogin={handleRoleSelection} onLogout={() => {setIsAuthenticated(false); sessionStorage.removeItem('eduamigo_auth');}} />;

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#f0f9ff]">
      {showAuthModal && <ParentAuthModal onResult={handleParentAccess} onCancel={() => { setShowAuthModal(false); setViewMode('student'); }} />}

      <aside className="hidden md:block w-80 bg-white border-r border-blue-100 p-6 overflow-y-auto h-screen sticky top-0">
        <div className="mb-6">
            <button onClick={() => { setUserRole(null); setViewMode('student'); setIsParentUnlocked(false); }} className="text-xs font-bold text-blue-400 hover:text-blue-600 flex items-center gap-1">← Cambiar Perfil</button>
            <div className="mt-4 p-3 bg-blue-50 rounded-xl">
              <label className="text-[10px] font-bold text-blue-400 uppercase">Comunidad Autónoma</label>
              <select 
                value={region} 
                onChange={(e) => setRegion(e.target.value as Region)}
                className="w-full bg-transparent text-sm font-bold text-blue-900 outline-none cursor-pointer"
              >
                {['Madrid', 'Andalucía', 'Cataluña', 'Galicia', 'País Vasco', 'Comunidad Valenciana', 'Aragón', 'Asturias', 'Baleares', 'Canarias', 'Cantabria', 'Castilla-La Mancha', 'Castilla y León', 'Extremadura', 'Murcia', 'Navarra', 'La Rioja'].map(r => <option key={r} value={r}>{r}</option>)}
              </select>
            </div>
        </div>
        <HistorySidebar history={history} onSelect={(item) => { setViewMode('student'); setGrade(item.grade); setSubject(item.subject); setQuestion(item.question); setResult(item.answer); }} />
      </aside>

      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8">
        <Header viewMode={viewMode} setViewMode={toggleViewMode} userRole={userRole} />

        <div className="mt-8">
          {viewMode === 'student' ? (
            <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
              <StudyForm grade={grade} setGrade={setGrade} subject={subject} setSubject={setSubject} question={question} setQuestion={setQuestion} onSubmit={handleSubmit} loading={loading} />
              {error && (
                <div className="bg-red-50 border-2 border-red-100 p-4 rounded-[1.5rem] shadow-sm text-red-700 font-bold flex items-center gap-3 animate-in shake duration-500">
                  <span className="text-2xl">⚠️</span>
                  <p className="text-sm">{error}</p>
                </div>
              )}
              <ResultDisplay result={result} loading={loading} grade={grade} subject={subject} onSpeak={handleSpeak} isPlayingId={isPlayingAudio} />
            </div>
          ) : viewMode === 'library' ? (
            <LibraryBrowser region={region} grade={grade} setGrade={setGrade} />
          ) : (
            <ParentDashboard history={history} onSelectItem={(item) => { setViewMode('student'); setResult(item.answer); }} />
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Region, GradeLevel, Subject, SyllabusTopic, TopicDetail, Exercise } from '../types';
import { getSyllabus, getTopicDetail, generateSpeech } from '../services/geminiService';

interface LibraryBrowserProps {
  region: Region;
  grade: GradeLevel;
  setGrade: (g: GradeLevel) => void;
}

const subjects: { name: Subject; icon: string; color: string }[] = [
  { name: 'Matemáticas', icon: '🔢', color: 'blue' },
  { name: 'Ciencias Naturales', icon: '🌿', color: 'green' },
  { name: 'Historia', icon: '📜', color: 'amber' },
  { name: 'Lengua y Literatura', icon: '📖', color: 'rose' },
  { name: 'Geografía', icon: '🗺️', color: 'emerald' },
  { name: 'Física y Química', icon: '🧪', color: 'indigo' },
];

const LibraryBrowser: React.FC<LibraryBrowserProps> = ({ region, grade, setGrade }) => {
  const [selectedSubject, setSelectedSubject] = useState<Subject | null>(null);
  const [syllabus, setSyllabus] = useState<SyllabusTopic[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [topicDetail, setTopicDetail] = useState<TopicDetail | null>(null);
  const [userAnswers, setUserAnswers] = useState<Record<string, number>>({});
  const [showFeedback, setShowFeedback] = useState<Record<string, boolean>>({});

  useEffect(() => {
    if (selectedSubject) {
      loadSyllabus();
      setTopicDetail(null);
      setUserAnswers({});
      setShowFeedback({});
      setError(null);
    }
  }, [selectedSubject, region, grade]);

  const loadSyllabus = async () => {
    if (!selectedSubject) return;
    setLoading(true);
    setError(null);
    try {
      const data = await getSyllabus(region, grade, selectedSubject);
      setSyllabus(data);
    } catch (e: any) {
      console.error(e);
      if (e?.message?.includes('429') || e?.status === 429) {
        setError('Hemos superado el límite de consultas al currículo. Inténtalo de nuevo en un minuto.');
      } else {
        setError('No hemos podido cargar el temario. Inténtalo de nuevo.');
      }
    } finally {
      setLoading(false);
    }
  };

  const loadDetail = async (topicTitle: string, sub: string) => {
    if (!selectedSubject) return;
    setLoading(true);
    setError(null);
    setUserAnswers({});
    setShowFeedback({});
    try {
      const detail = await getTopicDetail(region, grade, selectedSubject, topicTitle, sub);
      setTopicDetail(detail);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (e: any) {
      console.error(e);
      if (e?.message?.includes('429') || e?.status === 429) {
        setError('El tutor está un poco cansado por hoy (límite de cuota). Espera un minuto para leer este tema.');
      } else {
        setError('Error al cargar el contenido del tema.');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleAnswerSelect = (exerciseId: string, optionIndex: number) => {
    if (showFeedback[exerciseId]) return;
    setUserAnswers(prev => ({ ...prev, [exerciseId]: optionIndex }));
  };

  const checkAnswer = (exerciseId: string) => {
    if (userAnswers[exerciseId] === undefined) return;
    setShowFeedback(prev => ({ ...prev, [exerciseId]: true }));
  };

  if (topicDetail) {
    return (
      <div className="space-y-6 animate-in fade-in duration-500 pb-20">
        <button 
          onClick={() => setTopicDetail(null)}
          className="text-blue-600 font-bold flex items-center gap-2 hover:translate-x-[-4px] transition-transform"
        >
          ← Volver al temario de {selectedSubject}
        </button>

        {error && (
          <div className="bg-red-50 border-2 border-red-100 p-4 rounded-[1.5rem] text-red-700 font-bold text-sm">
            {error}
          </div>
        )}

        <div className="bg-white rounded-[2rem] shadow-xl overflow-hidden border border-blue-50">
          <div className="bg-blue-600 p-8 text-white relative">
             <div className="flex justify-between items-start">
               <div>
                  <h2 className="text-3xl font-bold mb-2">{topicDetail.title}</h2>
                  <p className="opacity-80 font-medium">{grade} • {region} • {selectedSubject}</p>
               </div>
               <button 
                 onClick={() => generateSpeech(`${topicDetail.title}. ${topicDetail.content}.`)}
                 className="bg-white/20 hover:bg-white/30 p-3 rounded-2xl transition-all"
               >
                 🔊 Escuchar Lección
               </button>
             </div>
          </div>

          <div className="p-8 md:p-12 space-y-10">
            <section>
              <h3 className="text-xl font-bold text-blue-900 mb-4 flex items-center gap-2">
                <span className="w-2 h-8 bg-blue-600 rounded-full"></span>
                Explicación del Tema
              </h3>
              <div className="prose prose-blue max-w-none text-blue-800 leading-relaxed text-lg whitespace-pre-wrap">
                {topicDetail.content}
              </div>
            </section>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <section className="bg-blue-50 p-6 rounded-3xl">
                <h3 className="font-bold text-blue-900 mb-4 flex items-center gap-2">📌 Puntos Clave</h3>
                <ul className="space-y-3">
                  {topicDetail.keyPoints.map((p, i) => (
                    <li key={i} className="flex gap-2 text-blue-800 text-sm italic font-medium">
                      <span className="text-blue-500">✔</span> {p}
                    </li>
                  ))}
                </ul>
              </section>

              <section className="bg-green-50 p-6 rounded-3xl">
                <h3 className="font-bold text-green-900 mb-4 flex items-center gap-2">💡 Ejemplos Prácticos</h3>
                <ul className="space-y-3">
                  {topicDetail.examples.map((e, i) => (
                    <li key={i} className="flex gap-2 text-green-800 text-sm">
                      <span className="text-green-500">★</span> {e}
                    </li>
                  ))}
                </ul>
              </section>
            </div>

            {/* Interactive Exercises Section */}
            <section className="space-y-6">
              <h3 className="text-xl font-bold text-blue-900 mb-4 flex items-center gap-2">
                <span className="w-2 h-8 bg-yellow-500 rounded-full"></span>
