/**
 * Helper to execute API calls with exponential backoff for 429 and 5xx errors.
 */
async function executeWithRetry<T>(fn: () => Promise<T>, maxRetries = 2): Promise<T> {
  let lastError: any;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error: any) {
      lastError = error;
      const status = error?.status || (error?.message?.includes('429') ? 429 : 0);

      if (attempt < maxRetries && (status === 429 || (status >= 500 && status <= 599))) {
        const delay = Math.pow(2, attempt) * 1000 + Math.random() * 500;
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw error;
    }
  }
  throw lastError;
}

export const getExplanation = async (
  grade: GradeLevel,
  subject: Subject,
  question: string,
  region: Region
): Promise<ExplanationResponse> => {
  try {
    return await executeWithRetry(async () => {
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Explica: "${question}" para ${grade} en ${subject} siguiendo el currículo de ${region}.`,
        config: {
          systemInstruction: `Eres un tutor experto en el sistema educativo español (LOMLOE). 
          Adapta la respuesta a la normativa de ${region} para el nivel ${grade}.
          Usa lenguaje ameno, 3 ejemplos claros y un dato curioso. Formato JSON.`,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              explanation: { type: Type.STRING },
              examples: { type: Type.ARRAY, items: { type: Type.STRING } },
              funFact: { type: Type.STRING },
            },
            required: ["explanation", "examples", "funFact"],
          },
        },
      });
      return JSON.parse(response.text || '{}') as ExplanationResponse;
    });
  } catch (e: any) {
    // Fallback manual si falla la IA para Q&A
    return {
      explanation: `Lo siento, el servicio de tutoría inteligente está muy saturado ahora mismo. Como resumen general sobre ${question}: se trata de un concepto clave en ${subject} para ${grade}. Te recomiendo consultar tu libro de texto de ${region} mientras recuperamos la conexión total.`,
      examples: ['Consulta el temario en la sección Biblioteca', 'Pregunta a tu profesor sobre este punto específico'],
      funFact: '¡La curiosidad es el primer paso para ser un gran científico!'
    };
  }
};

