import { GoogleGenAI, Type, Modality } from "@google/genai";
import { GradeLevel, Subject, ExplanationResponse, Region, SyllabusTopic, TopicDetail } from "../types";
import { FALLBACK_SYLLABUS, FALLBACK_TOPIC_DETAILS, getGenericSyllabus } from "../data/fallbackData";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Cache keys for local storage to prevent redundant API calls
 */
const getCacheKey = (type: string, ...args: string[]) => `eduamigo_cache_${type}_${args.join('_').toLowerCase().replace(/\s+/g, '')}`;

/**
 * Helper to execute API calls with exponential backoff for 429 and 5xx errors.
 */
async function executeWithRetry<T>(fn: () => Promise<T>, maxRetries = 1): Promise<T> {
  let lastError: any;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error: any) {
      lastError = error;
      const status = error?.status || (error?.message?.includes('429') ? 429 : 0);
      if (attempt < maxRetries && (status === 429 || (status >= 500 && status <= 599))) {
        const delay = 800 * (attempt + 1); // Aggressive retry for speed
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw error;
    }
  }
  throw lastError;
}

export const getExplanation = async (
  grade: GradeLevel,
  subject: Subject,
  question: string,
  region: Region
): Promise<ExplanationResponse> => {
  try {
    return await executeWithRetry(async () => {
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview", // Use flash for speed
        contents: `Explica: "${question}" para ${grade} en ${subject} de ${region}.`,
        config: {
          thinkingConfig: { thinkingBudget: 0 }, // Speed priority
          systemInstruction: `Eres un tutor experto LOMLOE en ${region}. Explica de forma sencilla para ${grade}. Formato JSON.`,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              explanation: { type: Type.STRING },
              examples: { type: Type.ARRAY, items: { type: Type.STRING } },
              funFact: { type: Type.STRING },
            },
            required: ["explanation", "examples", "funFact"],
          },
        },
      });
      return JSON.parse(response.text || '{}') as ExplanationResponse;
    });
  } catch (e: any) {
    return {
      explanation: `Lo siento, el servicio está saturado. Revisa tu biblioteca de ${subject} para ${grade}.`,
      examples: ['Reintenta en unos segundos'],
      funFact: '¡Aprender es una aventura constante!'
    };
  }
};

export const getSyllabus = async (
  region: Region,
  grade: GradeLevel,
  subject: Subject
): Promise<SyllabusTopic[]> => {
  const cacheKey = getCacheKey('syllabus', region, grade, subject);
  const cached = localStorage.getItem(cacheKey);
  if (cached) return JSON.parse(cached);

  try {
    return await executeWithRetry(async () => {
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview", // Flash is much faster for structural tasks
        contents: `Genera el temario oficial LOMLOE para ${subject} en ${grade} de ${region}.`,
        config: {
          thinkingConfig: { thinkingBudget: 0 }, // Instant generation
          systemInstruction: `Genera una lista de 6 bloques temáticos. Formato JSON.`,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                title: { type: Type.STRING },
                description: { type: Type.STRING },
                subtopics: { type: Type.ARRAY, items: { type: Type.STRING } },
              },
              required: ["id", "title", "description", "subtopics"],
            },
          },
        },
      });
      const data = JSON.parse(response.text || '[]');
      localStorage.setItem(cacheKey, JSON.stringify(data));
      return data;
    });
  } catch (e) {
    return FALLBACK_SYLLABUS[grade]?.[subject] || getGenericSyllabus(subject);
  }
};

