import { GoogleGenAI, Type, Modality } from "@google/genai";
import { GradeLevel, Subject, ExplanationResponse, Region, SyllabusTopic, TopicDetail, ExamResult, Exercise } from "../types";
import { FALLBACK_SYLLABUS, FALLBACK_TOPIC_DETAILS, getGenericSyllabus } from "../data/fallbackData";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getCacheKey = (type: string, ...args: string[]) => `eduamigo_cache_${type}_${args.join('_').toLowerCase().replace(/\s+/g, '')}`;

async function executeWithRetry<T>(fn: () => Promise<T>, maxRetries = 1): Promise<T> {
  let lastError: any;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error: any) {
      lastError = error;
      const status = error?.status || (error?.message?.includes('429') ? 429 : 0);
      if (attempt < maxRetries && (status === 429 || (status >= 500 && status <= 599))) {
        const delay = 800 * (attempt + 1);
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw error;
    }
  }
  throw lastError;
}

