import HistorySidebar from './components/HistorySidebar';
import ParentDashboard from './components/ParentDashboard';
import Login from './components/Login';
import AuthScreen from './components/AuthScreen';
import ParentAuthModal from './components/ParentAuthModal';
import LibraryBrowser from './components/LibraryBrowser';
import ExamMode from './components/ExamMode';
import ChildSelector from './components/ChildSelector';
import RewardsShop from './components/RewardsShop';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState<UserRole>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('student');
  const [region, setRegion] = useState<Region>('Madrid');
  const [isParentUnlocked, setIsParentUnlocked] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);

  const [children, setChildren] = useState<Child[]>([]);
  const [activeChildId, setActiveChildId] = useState<string | null>(null);
  const [rewards, setRewards] = useState<Reward[]>([]);

  const [question, setQuestion] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ExplanationResponse | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [examHistory, setExamHistory] = useState<ExamResult[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isPlayingAudio, setIsPlayingAudio] = useState<string | null>(null);

  const activeChild = children.find(c => c.id === activeChildId) || null;

  useEffect(() => {
    const sessionAuth = sessionStorage.getItem('eduamigo_auth');
    if (sessionAuth) setIsAuthenticated(true);

    setRegion(localStorage.getItem('eduamigo_region') as Region || 'Madrid');
    setHistory(JSON.parse(localStorage.getItem('eduamigo_history') || '[]'));
    setExamHistory(JSON.parse(localStorage.getItem('eduamigo_exam_history') || '[]'));
    setChildren(JSON.parse(localStorage.getItem('eduamigo_children') || '[]'));
    setRewards(JSON.parse(localStorage.getItem('eduamigo_rewards') || '[]'));
  }, []);

  useEffect(() => {
    if (userRole && userRole !== 'demo') {
      localStorage.setItem('eduamigo_history', JSON.stringify(history));
      localStorage.setItem('eduamigo_exam_history', JSON.stringify(examHistory));
      localStorage.setItem('eduamigo_children', JSON.stringify(children));
      localStorage.setItem('eduamigo_rewards', JSON.stringify(rewards));
      localStorage.setItem('eduamigo_region', region);
    }
  }, [history, examHistory, children, rewards, userRole, region]);

  const handleAuthenticated = () => {
    setIsAuthenticated(true);
    sessionStorage.setItem('eduamigo_auth', 'true');
  };

  const handleDemoMode = () => {
    setIsAuthenticated(true);
    setUserRole('demo');
    setChildren([{ id: 'demo-1', name: 'Demo Kid', avatar: '🚀', points: 150, grade: '4º Primaria' }]);
    setActiveChildId('demo-1');
    sessionStorage.setItem('eduamigo_auth', 'demo');
  };

  const awardPoints = (points: number) => {
    if (!activeChildId) return;
    setChildren(prev => prev.map(c => c.id === activeChildId ? { ...c, points: c.points + points } : c));
  };

  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!question.trim() || !activeChild) return;
    setLoading(true);
    setError(null);
    try {
      const data = await getExplanation(activeChild.grade, 'Matemáticas', question, region);
      setResult(data);
      setHistory(prev => [{
        id: crypto.randomUUID(),
        childId: activeChild.id,
        grade: activeChild.grade,
        subject: 'Matemáticas',
        region, question, answer: data,
        timestamp: Date.now(),
      }, ...prev].slice(0, 50));
      awardPoints(5);
    } catch (err) { setError('Error al conectar.'); } finally { setLoading(false); }
  };

  const handleSaveExamResult = (result: ExamResult) => {
    const points = (result.score * 10) + (result.score === result.totalQuestions ? 50 : 0);
    const finalResult = { ...result, pointsEarned: points };
    setExamHistory(prev => [...prev, finalResult]);
    awardPoints(points);
  };

  const handleAddChild = (name: string, grade: GradeLevel, avatar: string) => {
    const newChild: Child = { id: crypto.randomUUID(), name, avatar, grade, points: 0 };
    setChildren([...children, newChild]);
  };

  const handleUpdateRewards = (newRewards: Reward[]) => {
    setRewards(newRewards);
  };

  if (!isAuthenticated) return <AuthScreen onAuthenticated={handleAuthenticated} onDemo={handleDemoMode} />;
  if (!userRole) return <Login onLogin={setUserRole} onLogout={() => {setIsAuthenticated(false); sessionStorage.removeItem('eduamigo_auth');}} />;

  // Force child selection for students
  if (userRole === 'student' && !activeChildId) {
    return (
      <div className="min-h-screen bg-[#f0f9ff] p-8">
        <ChildSelector children={children} onSelect={(c) => setActiveChildId(c.id)} />
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2">
           <button onClick={() => setUserRole(null)} className="text-xs font-bold text-blue-400 hover:text-blue-600">← Atrás</button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#f0f9ff]">
      {showAuthModal && (
        <ParentAuthModal 
          onResult={(success) => { setIsParentUnlocked(success); if(success) setViewMode('parent'); setShowAuthModal(false); }} 
          onCancel={() => { setShowAuthModal(false); setViewMode('student'); }} 
        />
      )}

      <aside className="hidden md:flex w-80 bg-white border-r border-blue-100 p-6 flex-col h-screen sticky top-0">
        <div className="flex-1 overflow-y-auto no-scrollbar">
          <div className="mb-6 space-y-4">
              <button onClick={() => { setActiveChildId(null); setViewMode('student'); }} className="text-xs font-bold text-blue-400 hover:text-blue-600 flex items-center gap-1">← Cambiar Niño</button>
              <div className="p-4 bg-blue-50 rounded-[1.5rem] border border-blue-100">
                <p className="text-[10px] font-black text-blue-400 uppercase mb-1">Tu Región</p>
                <select value={region} onChange={(e) => setRegion(e.target.value as Region)} className="w-full bg-transparent text-sm font-black text-blue-900 outline-none">
                  {['Madrid', 'Andalucía', 'Cataluña', 'Galicia', 'País Vasco', 'Comunidad Valenciana', 'Murcia', 'Canarias'].map(r => <option key={r} value={r}>{r}</option>)}
                </select>
              </div>
          </div>
          <HistorySidebar 
            history={history.filter(h => h.childId === activeChildId)} 
            onSelect={(item) => { setViewMode('student'); setResult(item.answer); setQuestion(item.question); }} 
          />
        </div>
        <div className="pt-4 border-t border-blue-50 text-center space-y-2">
            <p className="text-[10px] font-black text-blue-200 uppercase tracking-widest">EWOLAJ21TECH Systems</p>
        </div>
      </aside>

      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8">
        <Header 
          viewMode={viewMode} 
          setViewMode={(m) => m === 'parent' && !isParentUnlocked ? setShowAuthModal(true) : setViewMode(m)} 
          userRole={userRole}
          activeChild={activeChild}
        />

        <div className="mt-8">
          {viewMode === 'student' && activeChild && (
            <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
              <StudyForm grade={activeChild.grade} setGrade={() => {}} subject="Matemáticas" setSubject={() => {}} question={question} setQuestion={setQuestion} onSubmit={handleSubmit} loading={loading} />
              <ResultDisplay result={result} loading={loading} grade={activeChild.grade} subject="Matemáticas" onSpeak={generateSpeech} isPlayingId={isPlayingAudio} />
            </div>
          )}
          {viewMode === 'library' && activeChild && <LibraryBrowser region={region} grade={activeChild.grade} setGrade={() => {}} />}
          {viewMode === 'exam' && activeChild && <ExamMode grade={activeChild.grade} subject="Matemáticas" region={region} onSaveResult={handleSaveExamResult} />}
          {viewMode === 'shop' && activeChild && <RewardsShop child={activeChild} rewards={rewards} />}
          {viewMode === 'parent' && (
            <ParentDashboard 
              history={history} 
              examHistory={examHistory} 
              children={children}
              rewards={rewards}
              onSelectItem={(item) => { setViewMode('student'); setResult(item.answer); }} 
              onAddChild={handleAddChild}
              onUpdateRewards={handleUpdateRewards}
            />
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { HistoryItem, ExamResult, Child, Reward, GradeLevel } from '../types';

interface ParentDashboardProps {
  history: HistoryItem[];
  examHistory: ExamResult[];
  children: Child[];
  rewards: Reward[];
  onSelectItem: (item: HistoryItem) => void;
  onAddChild: (name: string, grade: GradeLevel, avatar: string) => void;
  onUpdateRewards: (rewards: Reward[]) => void;
}

const ParentDashboard: React.FC<ParentDashboardProps> = ({ 
  history, examHistory, children, rewards, onSelectItem, onAddChild, onUpdateRewards 
}) => {
  const [activeTab, setActiveTab] = useState<'stats' | 'children' | 'rewards'>('stats');
  const [showAddChild, setShowAddChild] = useState(false);
  const [newName, setNewName] = useState('');
  const [newGrade, setNewGrade] = useState<GradeLevel>('1º Primaria');
  const [newAvatar, setNewAvatar] = useState('👦');

  const [newRewardTitle, setNewRewardTitle] = useState('');
  const [newRewardCost, setNewRewardCost] = useState(100);
  const [newRewardIcon, setNewRewardIcon] = useState('🎁');

  const handleAddReward = () => {
    if (!newRewardTitle) return;
    const reward: Reward = { id: crypto.randomUUID(), title: newRewardTitle, pointsCost: newRewardCost, icon: newRewardIcon };
    onUpdateRewards([...rewards, reward]);
    setNewRewardTitle('');
  };

  const deleteReward = (id: string) => {
    onUpdateRewards(rewards.filter(r => r.id !== id));
  };

  return (
    <div className="space-y-8 pb-10 animate-in fade-in duration-500">
      {/* Tab Navigation */}
      <div className="flex gap-2 p-1 bg-blue-100 rounded-2xl w-fit">
        <button onClick={() => setActiveTab('stats')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-sm' : 'text-blue-500'}`}>📊 Estadísticas</button>
        <button onClick={() => setActiveTab('children')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${activeTab === 'children' ? 'bg-white text-blue-600 shadow-sm' : 'text-blue-500'}`}>👥 Mis Hijos</button>
        <button onClick={() => setActiveTab('rewards')} className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${activeTab === 'rewards' ? 'bg-white text-blue-600 shadow-sm' : 'text-blue-500'}`}>🎁 Recompensas</button>
      </div>

      {activeTab === 'stats' && (
        <div className="space-y-8">
           <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-8 rounded-[2rem] border border-blue-50 shadow-sm">
              <p className="text-blue-400 text-[10px] font-black uppercase mb-1">Consultas Totales</p>
              <p className="text-4xl font-black text-blue-900">{history.length}</p>
            </div>
            <div className="bg-blue-600 p-8 rounded-[2rem] shadow-xl text-white">
              <p className="text-blue-100 text-[10px] font-black uppercase mb-1">Exámenes Hechos</p>
              <p className="text-4xl font-black">{examHistory.length}</p>
            </div>
            <div className="bg-white p-8 rounded-[2rem] border border-blue-50 shadow-sm text-center">
              <p className="text-blue-400 text-[10px] font-black uppercase mb-1">Puntos Familiares</p>
              <p className="text-4xl font-black text-yellow-600">⭐ {children.reduce((acc, c) => acc + c.points, 0)}</p>
            </div>
          </div>

          <section className="bg-white rounded-[2.5rem] border border-blue-50 shadow-sm overflow-hidden">
            <div className="p-8 bg-blue-50/30 border-b border-blue-50 flex justify-between items-center">
              <h3 className="font-black text-blue-900">Actividad Reciente por Hijo</h3>
            </div>
            <div className="divide-y divide-blue-50 max-h-[500px] overflow-y-auto">
              {children.map(child => {
                const childExams = examHistory.filter(e => e.childId === child.id);
                return (
                  <div key={child.id} className="p-6 flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <span className="text-3xl">{child.avatar}</span>
                      <div>
                        <p className="font-black text-blue-900">{child.name}</p>
                        <p className="text-xs text-blue-400 font-bold">{childExams.length} exámenes • {history.filter(h => h.childId === child.id).length} dudas</p>
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="text-lg font-black text-yellow-600">{child.points} pts</p>
                      <p className="text-[10px] font-bold text-gray-400 uppercase">Balance actual</p>
                    </div>
                  </div>
                );
              })}
            </div>
          </section>
        </div>
      )}

      {activeTab === 'children' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
            {children.map(child => (
              <div key={child.id} className="bg-white p-8 rounded-[2.5rem] border border-blue-50 shadow-sm text-center group relative overflow-hidden">
                <div className="absolute top-0 right-0 p-4 opacity-0 group-hover:opacity-100 transition-opacity">
                   <button className="text-red-400 hover:text-red-600 text-xs font-bold">Eliminar</button>
                </div>
                <div className="text-5xl mb-4 group-hover:scale-110 transition-transform inline-block">{child.avatar}</div>
                <h4 className="text-xl font-black text-blue-900">{child.name}</h4>
                <p className="text-sm font-bold text-blue-400 mb-4">{child.grade}</p>
                <div className="bg-blue-50 rounded-2xl p-3 inline-block">
                   <p className="text-[10px] font-black text-blue-400 uppercase">Puntos Totales</p>
                   <p className="text-xl font-black text-blue-600">⭐ {child.points}</p>
                </div>
              </div>
            ))}

            <button 
              onClick={() => setShowAddChild(true)}
              className="bg-blue-50 border-2 border-dashed border-blue-200 rounded-[2.5rem] p-8 flex flex-col items-center justify-center text-blue-400 hover:bg-blue-100 transition-all gap-2"
            >
              <span className="text-3xl">+</span>
              <span className="font-black text-sm uppercase">Añadir Nuevo Hijo</span>
            </button>
          </div>

          {showAddChild && (
            <div className="bg-white p-8 rounded-[2.5rem] border-4 border-blue-600 shadow-2xl animate-in zoom-in duration-300">
               <h3 className="text-2xl font-black text-blue-900 mb-6">Nuevo Perfil de Estudiante</h3>
               <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                  <div className="space-y-2">
                    <label className="text-xs font-black text-blue-400 uppercase">Nombre</label>
                    <input value={newName} onChange={e => setNewName(e.target.value)} className="w-full bg-blue-50 p-4 rounded-2xl outline-none font-bold text-blue-900 border-2 border-transparent focus:border-blue-600" placeholder="Ej: Alex" />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-blue-400 uppercase">Avatar</label>
                    <select value={newAvatar} onChange={e => setNewAvatar(e.target.value)} className="w-full bg-blue-50 p-4 rounded-2xl outline-none font-bold text-blue-900 border-2 border-transparent focus:border-blue-600">
                      {['👦', '👧', '🚀', '⭐', '🐯', '🐼', '🎨'].map(a => <option key={a} value={a}>{a} Avatar</option>)}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-black text-blue-400 uppercase">Curso Escolar</label>
                    <select value={newGrade} onChange={e => setNewGrade(e.target.value as any)} className="w-full bg-blue-50 p-4 rounded-2xl outline-none font-bold text-blue-900 border-2 border-transparent focus:border-blue-600">
                      {['1º Primaria', '2º Primaria', '3º Primaria', '4º Primaria', '5º Primaria', '6º Primaria'].map(g => <option key={g} value={g}>{g}</option>)}
                    </select>
                  </div>
               </div>
               <div className="flex gap-4">
                  <button onClick={() => { onAddChild(newName, newGrade, newAvatar); setShowAddChild(false); setNewName(''); }} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black shadow-lg hover:bg-blue-700 transition-all">Crear Perfil ✨</button>
                  <button onClick={() => setShowAddChild(false)} className="text-blue-400 font-bold px-8 py-4">Cancelar</button>
               </div>
            </div>
          )}
        </div>
      )}

      {activeTab === 'rewards' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          <div className="md:col-span-1 bg-white p-8 rounded-[2.5rem] border border-blue-50 shadow-sm h-fit space-y-6">
            <h3 className="text-xl font-black text-blue-900">Añadir Premio</h3>
            <div className="space-y-4">
               <div>
                 <label className="text-[10px] font-black text-blue-400 uppercase block mb-1">Nombre del Premio</label>
                 <input value={newRewardTitle} onChange={e => setNewRewardTitle(e.target.value)} className="w-full bg-blue-50 p-4 rounded-2xl outline-none font-bold" placeholder="Ej: Tarde de Videojuegos" />
               </div>
               <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-black text-blue-400 uppercase block mb-1">Coste Pts</label>
                    <input type="number" value={newRewardCost} onChange={e => setNewRewardCost(Number(e.target.value))} className="w-full bg-blue-50 p-4 rounded-2xl outline-none font-bold" />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-blue-400 uppercase block mb-1">Icono</label>
                    <select value={newRewardIcon} onChange={e => setNewRewardIcon(e.target.value)} className="w-full bg-blue-50 p-4 rounded-2xl outline-none font-bold">
                       {['🎁', '🎮', '🍕', '🎥', '⚽', '🍦', '🎡'].map(i => <option key={i} value={i}>{i}</option>)}
                    </select>
                  </div>
               </div>
               <button onClick={handleAddReward} className="w-full bg-yellow-500 text-white py-4 rounded-2xl font-black shadow-lg hover:bg-yellow-600 transition-all">Añadir Recompensa 🏆</button>
            </div>
          </div>

          <div className="md:col-span-2 space-y-4">
            <h3 className="text-xl font-black text-blue-900">Premios Disponibles</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {rewards.map(reward => (
                <div key={reward.id} className="bg-white p-6 rounded-3xl border border-blue-50 flex items-center justify-between group shadow-sm">
                   <div className="flex items-center gap-4">
                     <span className="text-4xl">{reward.icon}</span>
                     <div>
                       <p className="font-black text-blue-900">{reward.title}</p>
                       <p className="text-xs font-bold text-yellow-600">{reward.pointsCost} puntos</p>
                     </div>
                   </div>
                   <button onClick={() => deleteReward(reward.id)} className="text-red-300 hover:text-red-500 font-bold opacity-0 group-hover:opacity-100 transition-opacity">Eliminar</button>
                </div>
              ))}
              {rewards.length === 0 && <p className="col-span-full text-blue-300 font-medium italic p-10 text-center border-2 border-dashed border-blue-100 rounded-[2.5rem]">Aún no hay recompensas creadas.</p>}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ParentDashboard;

import React, { useState, useEffect } from 'react';
import { GradeLevel, Subject, ExplanationResponse, HistoryItem, ViewMode, UserRole, Region, ExamResult, Child, Reward } from './types';
import { getExplanation, generateSpeech } from './services/geminiService';
import Header from './components/Header';
import StudyForm from './components/StudyForm';
import ResultDisplay from './components/ResultDisplay';
import HistorySidebar from './components/HistorySidebar';
import ParentDashboard from './components/ParentDashboard';
import Login from './components/Login';
import AuthScreen from './components/AuthScreen';
import ParentAuthModal from './components/ParentAuthModal';
import LibraryBrowser from './components/LibraryBrowser';
import ExamMode from './components/ExamMode';
import ChildSelector from './components/ChildSelector';
import RewardsShop from './components/RewardsShop';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState<UserRole>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('student');
  const [region, setRegion] = useState<Region>('Madrid');
  const [isParentUnlocked, setIsParentUnlocked] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);

  const [children, setChildren] = useState<Child[]>([]);
  const [activeChildId, setActiveChildId] = useState<string | null>(null);
  const [rewards, setRewards] = useState<Reward[]>([]);

  const [question, setQuestion] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ExplanationResponse | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [examHistory, setExamHistory] = useState<ExamResult[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [isPlayingAudio, setIsPlayingAudio] = useState<string | null>(null);

  const activeChild = children.find(c => c.id === activeChildId) || null;

  useEffect(() => {
    const sessionAuth = sessionStorage.getItem('eduamigo_auth');
    if (sessionAuth) setIsAuthenticated(true);

    setRegion(localStorage.getItem('eduamigo_region') as Region || 'Madrid');
    setHistory(JSON.parse(localStorage.getItem('eduamigo_history') || '[]'));
    setExamHistory(JSON.parse(localStorage.getItem('eduamigo_exam_history') || '[]'));
    setChildren(JSON.parse(localStorage.getItem('eduamigo_children') || '[]'));
    setRewards(JSON.parse(localStorage.getItem('eduamigo_rewards') || '[]'));
  }, []);

  useEffect(() => {
    if (userRole && userRole !== 'demo') {
      localStorage.setItem('eduamigo_history', JSON.stringify(history));
      localStorage.setItem('eduamigo_exam_history', JSON.stringify(examHistory));
      localStorage.setItem('eduamigo_children', JSON.stringify(children));
      localStorage.setItem('eduamigo_rewards', JSON.stringify(rewards));
      localStorage.setItem('eduamigo_region', region);
    }
  }, [history, examHistory, children, rewards, userRole, region]);

  const handleAuthenticated = () => {
    setIsAuthenticated(true);
    sessionStorage.setItem('eduamigo_auth', 'true');
  };

  const handleDemoMode = () => {
    setIsAuthenticated(true);
    setUserRole('demo');
    setChildren([{ id: 'demo-1', name: 'Demo Kid', avatar: '🚀', points: 150, grade: '4º Primaria' }]);
    setActiveChildId('demo-1');
    sessionStorage.setItem('eduamigo_auth', 'demo');
  };

  const awardPoints = (points: number) => {
    if (!activeChildId) return;
    setChildren(prev => prev.map(c => c.id === activeChildId ? { ...c, points: c.points + points } : c));
  };

  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!question.trim() || !activeChild) return;
    setLoading(true);
    setError(null);
    try {
      const data = await getExplanation(activeChild.grade, 'Matemáticas', question, region);
      setResult(data);
      // Explicitly typing newItem as HistoryItem to resolve 'Subject' union literal inference issue.
      const newItem: HistoryItem = {
        id: crypto.randomUUID(),
        childId: activeChild.id,
        grade: activeChild.grade,
        subject: 'Matemáticas',
        region, 
        question, 
        answer: data,
        timestamp: Date.now(),
      };
      setHistory(prev => [newItem, ...prev].slice(0, 50));
      awardPoints(5);
    } catch (err) { setError('Error al conectar.'); } finally { setLoading(false); }
  };

  const handleSaveExamResult = (result: ExamResult) => {
    // ExamResult now comes fully populated with childId and pointsEarned from ExamMode component
    setExamHistory(prev => [...prev, result]);
    awardPoints(result.pointsEarned);
  };

  const handleAddChild = (name: string, grade: GradeLevel, avatar: string) => {
    const newChild: Child = { id: crypto.randomUUID(), name, avatar, grade, points: 0 };
    setChildren([...children, newChild]);
  };

  const handleUpdateRewards = (newRewards: Reward[]) => {
    setRewards(newRewards);
  };

  if (!isAuthenticated) return <AuthScreen onAuthenticated={handleAuthenticated} onDemo={handleDemoMode} />;
  if (!userRole) return <Login onLogin={setUserRole} onLogout={() => {setIsAuthenticated(false); sessionStorage.removeItem('eduamigo_auth');}} />;

  // Force child selection for students
  if (userRole === 'student' && !activeChildId) {
    return (
      <div className="min-h-screen bg-[#f0f9ff] p-8">
        <ChildSelector children={children} onSelect={(c) => setActiveChildId(c.id)} />
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2">
           <button onClick={() => setUserRole(null)} className="text-xs font-bold text-blue-400 hover:text-blue-600">← Atrás</button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#f0f9ff]">
      {showAuthModal && (
        <ParentAuthModal 
          onResult={(success) => { setIsParentUnlocked(success); if(success) setViewMode('parent'); setShowAuthModal(false); }} 
          onCancel={() => { setShowAuthModal(false); setViewMode('student'); }} 
        />
      )}

      <aside className="hidden md:flex w-80 bg-white border-r border-blue-100 p-6 flex-col h-screen sticky top-0">
        <div className="flex-1 overflow-y-auto no-scrollbar">
          <div className="mb-6 space-y-4">
              <button onClick={() => { setActiveChildId(null); setViewMode('student'); }} className="text-xs font-bold text-blue-400 hover:text-blue-600 flex items-center gap-1">← Cambiar Niño</button>
              <div className="p-4 bg-blue-50 rounded-[1.5rem] border border-blue-100">
                <p className="text-[10px] font-black text-blue-400 uppercase mb-1">Tu Región</p>
                <select value={region} onChange={(e) => setRegion(e.target.value as Region)} className="w-full bg-transparent text-sm font-black text-blue-900 outline-none">
                  {['Madrid', 'Andalucía', 'Cataluña', 'Galicia', 'País Vasco', 'Comunidad Valenciana', 'Murcia', 'Canarias'].map(r => <option key={r} value={r}>{r}</option>)}
                </select>
              </div>
          </div>
          <HistorySidebar 
            history={history.filter(h => h.childId === activeChildId)} 
            onSelect={(item) => { setViewMode('student'); setResult(item.answer); setQuestion(item.question); }} 
          />
        </div>
        <div className="pt-4 border-t border-blue-50 text-center space-y-2">
            <p className="text-[10px] font-black text-blue-200 uppercase tracking-widest">EWOLAJ21TECH Systems</p>
        </div>
      </aside>

      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8">
        <Header 
          viewMode={viewMode} 
          setViewMode={(m) => m === 'parent' && !isParentUnlocked ? setShowAuthModal(true) : setViewMode(m)} 
          userRole={userRole}
          activeChild={activeChild}
        />

        <div className="mt-8">
          {viewMode === 'student' && activeChild && (
            <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
              <StudyForm grade={activeChild.grade} setGrade={() => {}} subject="Matemáticas" setSubject={() => {}} question={question} setQuestion={setQuestion} onSubmit={handleSubmit} loading={loading} />
              <ResultDisplay result={result} loading={loading} grade={activeChild.grade} subject="Matemáticas" onSpeak={generateSpeech} isPlayingId={isPlayingAudio} />
            </div>
          )}
          {viewMode === 'library' && activeChild && <LibraryBrowser region={region} grade={activeChild.grade} setGrade={() => {}} />}
          {viewMode === 'exam' && activeChild && <ExamMode grade={activeChild.grade} subject="Matemáticas" region={region} childId={activeChild.id} onSaveResult={handleSaveExamResult} />}
          {viewMode === 'shop' && activeChild && <RewardsShop child={activeChild} rewards={rewards} />}
          {viewMode === 'parent' && (
            <ParentDashboard 
              history={history} 
              examHistory={examHistory} 
              children={children}
              rewards={rewards}
              onSelectItem={(item) => { setViewMode('student'); setResult(item.answer); }} 
              onAddChild={handleAddChild}
              onUpdateRewards={handleUpdateRewards}
            />
          )}
        </div>
      </main>
    </div>
  );
};

