        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-3 mb-4">
            {eventTypes.map((t) => (
              <button
                key={t.type}
                type="button"
                onClick={() => setType(t.type)}
                className={`flex items-center gap-2 p-3 rounded-2xl border-2 transition-all font-bold text-xs ${
                  type === t.type 
                    ? 'bg-indigo-600 border-indigo-600 text-white' 
                    : 'bg-gray-50 border-transparent text-gray-600 hover:bg-indigo-50'
                }`}
              >
                <span>{t.icon}</span>
                {t.label}
              </button>
            ))}
          </div>

          <div>
            <label className="text-xs font-black text-indigo-400 uppercase ml-2 mb-1 block">¿De qué se trata?</label>
            <input 
              value={title} 
              onChange={e => setTitle(e.target.value)}
              className="w-full bg-indigo-50 p-4 rounded-2xl outline-none font-bold text-indigo-900 border-2 border-transparent focus:border-indigo-600"
              placeholder="Ej: Examen de Mates Temas 4 y 5"
              required
            />
          </div>

          <div>
            <label className="text-xs font-black text-indigo-400 uppercase ml-2 mb-1 block">¿Cuándo es?</label>
            <input 
              type="date"
              value={date} 
              onChange={e => setDate(e.target.value)}
              className="w-full bg-indigo-50 p-4 rounded-2xl outline-none font-bold text-indigo-900 border-2 border-transparent focus:border-indigo-600"
              required
            />
          </div>

          <div className="pt-4 flex flex-col gap-3">
            <button type="submit" className="bg-indigo-600 text-white py-4 rounded-2xl font-black shadow-lg hover:bg-indigo-700 transition-all text-lg flex items-center justify-center gap-2">
              Guardar y ganar +20 ⭐
            </button>
            <button type="button" onClick={onClose} className="text-gray-400 font-bold py-2">
              Cancelar
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default StudentEventForm;

import React, { useState, useEffect } from 'react';
import { GradeLevel, Subject, ExplanationResponse, HistoryItem, ViewMode, UserRole, Region, ExamResult, Child, Reward, Country, CalendarEvent, Task, StudentRequest, EventType } from './types';
import { getExplanation, getSOSExplanation, generateSpeech } from './services/geminiService';
import { requestNotificationPermission, checkUpcomingEvents, sendLocalNotification } from './services/notificationService';
import Header from './components/Header';
import StudyForm from './components/StudyForm';
import ResultDisplay from './components/ResultDisplay';
import HistorySidebar from './components/HistorySidebar';
import ParentDashboard from './components/ParentDashboard';
import Login from './components/Login';
import AuthScreen from './components/AuthScreen';
import ParentAuthModal from './components/ParentAuthModal';
import LibraryBrowser from './components/LibraryBrowser';
import ExamMode from './components/ExamMode';
import ChildSelector from './components/ChildSelector';
import RewardsShop from './components/RewardsShop';
import SOSModal from './components/SOSModal';
import StudentRequestForm from './components/StudentRequestForm';
import StudentEventForm from './components/StudentEventForm';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState<UserRole>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('student');
  const [region, setRegion] = useState<Region>('Madrid');
  const [isParentUnlocked, setIsParentUnlocked] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [showSOSModal, setShowSOSModal] = useState(false);
  const [showRequestForm, setShowRequestForm] = useState(false);
  const [showStudentEventForm, setShowStudentEventForm] = useState(false);

  const [children, setChildren] = useState<Child[]>([]);
  const [activeChildId, setActiveChildId] = useState<string | null>(null);
  const [rewards, setRewards] = useState<Reward[]>([]);
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [requests, setRequests] = useState<StudentRequest[]>([]);

  const [question, setQuestion] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ExplanationResponse | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [examHistory, setExamHistory] = useState<ExamResult[]>([]);
  const [isPlayingAudio, setIsPlayingAudio] = useState<string | null>(null);

  const activeChild = children.find(c => c.id === activeChildId) || null;

  useEffect(() => {
    const sessionAuth = sessionStorage.getItem('eduamigo_auth');
    if (sessionAuth) setIsAuthenticated(true);

    setRegion(localStorage.getItem('eduamigo_region') as Region || 'Madrid');
    setHistory(JSON.parse(localStorage.getItem('eduamigo_history') || '[]'));
    setExamHistory(JSON.parse(localStorage.getItem('eduamigo_exam_history') || '[]'));
    setChildren(JSON.parse(localStorage.getItem('eduamigo_children') || '[]'));
    setRewards(JSON.parse(localStorage.getItem('eduamigo_rewards') || '[]'));
    setEvents(JSON.parse(localStorage.getItem('eduamigo_events') || '[]'));
    setTasks(JSON.parse(localStorage.getItem('eduamigo_tasks') || '[]'));
    setRequests(JSON.parse(localStorage.getItem('eduamigo_requests') || '[]'));

    requestNotificationPermission();
  }, []);

  useEffect(() => {
    if (userRole && userRole !== 'demo') {
      const data = { history, examHistory, children, rewards, events, tasks, requests };
      Object.entries(data).forEach(([key, val]) => localStorage.setItem(`eduamigo_${key}`, JSON.stringify(val)));
      localStorage.setItem('eduamigo_region', region);
    }
  }, [history, examHistory, children, rewards, events, tasks, requests, userRole, region]);

  useEffect(() => {
    if (events.length > 0 && children.length > 0) checkUpcomingEvents(events, children);
  }, [events, children]);

  const awardPoints = (points: number) => {
    if (!activeChildId) return;
    setChildren(prev => prev.map(c => c.id === activeChildId ? { ...c, points: c.points + points } : c));
  };

  const handleSubmit = async (e?: React.FormEvent, sosCountry?: Country) => {
    if (e) e.preventDefault();
    if (!question.trim() || !activeChild) return;

    setLoading(true);
    setResult(null);

    try {
      const res = sosCountry 
        ? await getSOSExplanation(activeChild.grade, 'Matemáticas' as Subject, question, sosCountry)
        : await getExplanation(activeChild.grade, 'Matemáticas' as Subject, question, region);

      setResult(res);

      const newHistoryItem: HistoryItem = {
        id: crypto.randomUUID(),
        childId: activeChild.id,
        grade: activeChild.grade,
        subject: 'Matemáticas' as Subject,
        region,
        question,
        answer: res,
        timestamp: Date.now()
      };

      setHistory(prev => [newHistoryItem, ...prev].slice(0, 20));
      awardPoints(5);
      if (sosCountry) setShowSOSModal(false);
    } catch (error) {
      console.error("Query submission error:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleAddRequest = (title: string, message: string) => {
    if (!activeChildId) return;
    const newRequest: StudentRequest = {
      id: crypto.randomUUID(),
      childId: activeChildId,
      title,
      message,
      timestamp: Date.now(),
      status: 'pending'
    };
    setRequests([...requests, newRequest]);
    setShowRequestForm(false);
    sendLocalNotification(`✨ ¡Petición de ${activeChild?.name}!`, `Ha solicitado: ${title}`, activeChild?.avatar);
  };

  const handleStudentAddEvent = (title: string, date: string, type: EventType) => {
    if (!activeChildId) return;
    const newEvent: CalendarEvent = {
      id: crypto.randomUUID(),
      childId: activeChildId,
      title,
      date,
      type,
      notified: false
    };
    setEvents([...events, newEvent]);
    setShowStudentEventForm(false);
    awardPoints(20); // Organizarse tiene premio
    sendLocalNotification(`🚀 Nuevo evento de ${activeChild?.name}`, `${title} agendado para el día ${date}`, activeChild?.avatar);
  };

  const handleApproveRequest = (requestId: string, dueDate: string) => {
    const request = requests.find(r => r.id === requestId);
    if (!request) return;

    const newTask: Task = {
      id: crypto.randomUUID(),
      childId: request.childId,
      title: `[SOLICITUD] ${request.title}`,
      dueDate,
      completed: false,
      priority: 'medium',
      fromRequestId: requestId
    };
    setTasks([...tasks, newTask]);
    setRequests(requests.map(r => r.id === requestId ? { ...r, status: 'approved' } : r));
  };

  const handleRejectRequest = (requestId: string) => {
    setRequests(requests.map(r => r.id === requestId ? { ...r, status: 'rejected' } : r));
  };

  const handleUpdateTask = (id: string, updates: Partial<Task>) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, ...updates } : t));
  };

  const handleAddChild = (name: string, grade: GradeLevel, avatar: string) => {
    const newChild: Child = {
      id: crypto.randomUUID(),
      name,
      avatar,
      points: 0,
      grade
    };
    setChildren([...children, newChild]);
  };

  const handleAddEvent = (event: Omit<CalendarEvent, 'id'>) => {
    const newEvent: CalendarEvent = {
      ...event,
      id: crypto.randomUUID()
    };
    setEvents([...events, newEvent]);
  };

  const handleDeleteEvent = (id: string) => {
    setEvents(events.filter(e => e.id !== id));
  };

  const handleAddTask = (task: Omit<Task, 'id'>) => {
    const newTask: Task = {
      ...task,
      id: crypto.randomUUID()
    };
    setTasks([...tasks, newTask]);
  };

  const handleToggleTask = (id: string) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  const handleDeleteTask = (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
  };

  if (!isAuthenticated) return <AuthScreen onAuthenticated={() => { setIsAuthenticated(true); sessionStorage.setItem('eduamigo_auth', 'true'); }} onDemo={() => setIsAuthenticated(true)} />;
  if (!userRole) return <Login onLogin={setUserRole} onLogout={() => { setIsAuthenticated(false); sessionStorage.removeItem('eduamigo_auth'); }} />;

  if (userRole === 'student' && !activeChildId) return <div className="min-h-screen bg-[#f0f9ff] p-8"><ChildSelector children={children} onSelect={(c) => setActiveChildId(c.id)} /></div>;

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#f0f9ff]">
      {showAuthModal && <ParentAuthModal onResult={(s) => { setIsParentUnlocked(s); if(s) setViewMode('parent'); setShowAuthModal(false); }} onCancel={() => setShowAuthModal(false)} />}
      {showSOSModal && <SOSModal onSelect={(c) => { handleSubmit(undefined, c); }} onClose={() => setShowSOSModal(false)} />}
      {showRequestForm && <StudentRequestForm onSend={handleAddRequest} onClose={() => setShowRequestForm(false)} />}
      {showStudentEventForm && <StudentEventForm onAdd={handleStudentAddEvent} onClose={() => setShowStudentEventForm(false)} />}

      <aside className="hidden md:flex w-80 bg-white border-r border-blue-100 p-6 flex-col h-screen sticky top-0">
        <div className="flex-1 overflow-y-auto no-scrollbar">
          <HistorySidebar history={history.filter(h => h.childId === activeChildId)} onSelect={(item) => { setViewMode('student'); setResult(item.answer); setQuestion(item.question); }} />
        </div>
      </aside>

      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8 relative">
        <Header viewMode={viewMode} setViewMode={(m) => m === 'parent' && !isParentUnlocked ? setShowAuthModal(true) : setViewMode(m)} userRole={userRole} activeChild={activeChild} />

        {viewMode === 'student' && (
          <div className="fixed bottom-24 right-6 md:bottom-10 md:right-10 flex flex-col gap-3 z-50">
            <button 
              onClick={() => setShowStudentEventForm(true)}
              className="w-16 h-16 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center text-3xl hover:scale-110 transition-transform"
              title="Agendar Evento 📅"
            >
              📅
            </button>
            <button 
              onClick={() => setShowRequestForm(true)}
              className="w-16 h-16 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center text-3xl hover:scale-110 transition-transform animate-bounce"
              title="Solicitar algo ✨"
            >
              ✨
            </button>
          </div>
        )}

        <div className="mt-8">
          {viewMode === 'student' && activeChild && (
            <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
              <StudyForm grade={activeChild.grade} setGrade={() => {}} subject="Matemáticas" setSubject={() => {}} question={question} setQuestion={setQuestion} onSubmit={handleSubmit} onSOS={() => setShowSOSModal(true)} loading={loading} />
              <ResultDisplay result={result} loading={loading} grade={activeChild.grade} subject="Matemáticas" onSpeak={generateSpeech} isPlayingId={isPlayingAudio} />
            </div>
          )}
          {viewMode === 'parent' && (
            <ParentDashboard 
              history={history} examHistory={examHistory} children={children} rewards={rewards} events={events} tasks={tasks} requests={requests}
              onSelectItem={() => {}} onAddChild={handleAddChild} onUpdateRewards={setRewards} onAddEvent={handleAddEvent} onDeleteEvent={handleDeleteEvent}
              onAddTask={handleAddTask} onToggleTask={handleToggleTask} onDeleteTask={handleDeleteTask}
              onApproveRequest={handleApproveRequest} onRejectRequest={handleRejectRequest} onUpdateTask={handleUpdateTask}
            />
          )}
          {viewMode === 'library' && (
            <LibraryBrowser region={region} grade={activeChild?.grade || '1º Primaria'} setGrade={() => {}} />
          )}
          {viewMode === 'exam' && activeChild && (
            <ExamMode grade={activeChild.grade} subject="Matemáticas" region={region} childId={activeChild.id} onSaveResult={(res) => {
              setExamHistory([res, ...examHistory]);
              awardPoints(res.pointsEarned);
            }} />
          )}
          {viewMode === 'shop' && activeChild && (
            <RewardsShop child={activeChild} rewards={rewards} />
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

export type GradeLevel = 
  | '1º Primaria' | '2º Primaria' | '3º Primaria' | '4º Primaria' | '5º Primaria' | '6º Primaria'
  | '1º ESO' | '2º ESO' | '3º ESO' | '4º ESO'
  | '1º Bachillerato' | '2º Bachillerato';

