import React, { useState } from 'react';
import { HistoryItem, ExamResult, Child, Reward, GradeLevel, CalendarEvent, Task, StudentRequest, SchoolCommunication, QuickNote } from '../types';
import AgendaManager from './AgendaManager';
import RequestManager from './RequestManager';
