          <div>
            <label className="text-[10px] font-black text-blue-400 uppercase ml-2 block mb-2">Selecciona un Avatar</label>
            <div className="flex flex-wrap gap-2">
              {avatars.map(a => (
                <button
                  key={a}
                  type="button"
                  onClick={() => setAvatar(a)}
