                >
                  {a}
                </button>
              ))}
            </div>
          </div>
          <button type="submit" className="w-full bg-blue-600 text-white py-3 rounded-xl font-black shadow-lg">
            Dar de Alta Estudiante 🚀
          </button>
        </form>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
