      {activeTab === 'agenda' && (
        <AgendaManager 
          children={children} 
          events={events} 
          tasks={tasks}
          onAddEvent={onAddEvent}
          onDeleteEvent={onDeleteEvent}
          onAddTask={onAddTask}
          onToggleTask={onToggleTask}
          onDeleteTask={onDeleteTask}
        />
