  );
};

export default ParentDashboard;

import React, { useState, useEffect } from 'react';
import { GradeLevel, Subject, ExplanationResponse, HistoryItem, ViewMode, UserRole, Region, ExamResult, Child, Reward, Country, CalendarEvent, Task, StudentRequest, EventType, SchoolCommunication, QuickNote } from './types';
import { getExplanation, getSOSExplanation, generateSpeech } from './services/geminiService';
import { requestNotificationPermission, checkUpcomingEvents, sendLocalNotification } from './services/notificationService';
import Header from './components/Header';
import StudyForm from './components/StudyForm';
import ResultDisplay from './components/ResultDisplay';
import HistorySidebar from './components/HistorySidebar';
import ParentDashboard from './components/ParentDashboard';
import Login from './components/Login';
import AuthScreen from './components/AuthScreen';
import ParentAuthModal from './components/ParentAuthModal';
import LibraryBrowser from './components/LibraryBrowser';
import ExamMode from './components/ExamMode';
import ChildSelector from './components/ChildSelector';
import RewardsShop from './components/RewardsShop';
import SOSModal from './components/SOSModal';
import StudentRequestForm from './components/StudentRequestForm';
import StudentEventForm from './components/StudentEventForm';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState<UserRole>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('student');
  const [region, setRegion] = useState<Region>('Madrid');
  const [isParentUnlocked, setIsParentUnlocked] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [showSOSModal, setShowSOSModal] = useState(false);
  const [showRequestForm, setShowRequestForm] = useState(false);
  const [showStudentEventForm, setShowStudentEventForm] = useState(false);

  const [children, setChildren] = useState<Child[]>([]);
  const [activeChildId, setActiveChildId] = useState<string | null>(null);
  const [rewards, setRewards] = useState<Reward[]>([]);
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [requests, setRequests] = useState<StudentRequest[]>([]);
  const [schoolComms, setSchoolComms] = useState<SchoolCommunication[]>([]);
  const [quickNotes, setQuickNotes] = useState<QuickNote[]>([]);

  const [question, setQuestion] = useState('');
  const [activeSubject, setActiveSubject] = useState<Subject>('Matemáticas');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ExplanationResponse | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [examHistory, setExamHistory] = useState<ExamResult[]>([]);
  const [isPlayingAudio, setIsPlayingAudio] = useState<string | null>(null);

  const activeChild = children.find(c => c.id === activeChildId) || null;

  useEffect(() => {
    const sessionAuth = sessionStorage.getItem('eduamigo_auth');
    if (sessionAuth) setIsAuthenticated(true);

    setRegion(localStorage.getItem('eduamigo_region') as Region || 'Madrid');
    setHistory(JSON.parse(localStorage.getItem('eduamigo_history') || '[]'));
    setExamHistory(JSON.parse(localStorage.getItem('eduamigo_exam_history') || '[]'));
    setChildren(JSON.parse(localStorage.getItem('eduamigo_children') || '[]'));
    setRewards(JSON.parse(localStorage.getItem('eduamigo_rewards') || '[]'));
    setEvents(JSON.parse(localStorage.getItem('eduamigo_events') || '[]'));
    setTasks(JSON.parse(localStorage.getItem('eduamigo_tasks') || '[]'));
    setRequests(JSON.parse(localStorage.getItem('eduamigo_requests') || '[]'));
    setSchoolComms(JSON.parse(localStorage.getItem('eduamigo_schoolComms') || '[]'));
    setQuickNotes(JSON.parse(localStorage.getItem('eduamigo_quickNotes') || '[]'));

    requestNotificationPermission();
  }, []);

  useEffect(() => {
    if (userRole && userRole !== 'demo') {
      const data = { history, examHistory, children, rewards, events, tasks, requests, schoolComms, quickNotes };
      Object.entries(data).forEach(([key, val]) => localStorage.setItem(`eduamigo_${key}`, JSON.stringify(val)));
      localStorage.setItem('eduamigo_region', region);
    }
  }, [history, examHistory, children, rewards, events, tasks, requests, schoolComms, quickNotes, userRole, region]);

  useEffect(() => {
    if (events.length > 0 && children.length > 0) checkUpcomingEvents(events, children);
  }, [events, children]);

  const awardPoints = (points: number) => {
    if (!activeChildId) return;
    setChildren(prev => prev.map(c => c.id === activeChildId ? { ...c, points: c.points + points } : c));
  };

  const handleStudySubmit = async (e?: React.FormEvent, sosCountry?: Country) => {
    if (e) e.preventDefault();
    if (!question.trim() || !activeChild) return;
    setLoading(true);
    setResult(null);
    try {
      const res = sosCountry 
        ? await getSOSExplanation(activeChild.grade, activeSubject, question, sosCountry)
        : await getExplanation(activeChild.grade, activeSubject, question, region);
      setResult(res);
      const newHistoryItem: HistoryItem = { id: crypto.randomUUID(), childId: activeChild.id, grade: activeChild.grade, subject: activeSubject, region, question, answer: res, timestamp: Date.now() };
      setHistory(prev => [newHistoryItem, ...prev].slice(0, 20));
      awardPoints(5);
      if (sosCountry) setShowSOSModal(false);
    } catch (error) { console.error(error); } finally { setLoading(false); }
  };

  const handleAddRequest = (title: string, message: string) => {
    if (!activeChildId) return;
    const newRequest: StudentRequest = { id: crypto.randomUUID(), childId: activeChildId, title, message, timestamp: Date.now(), status: 'pending' };
    setRequests([...requests, newRequest]);
    setShowRequestForm(false);
    sendLocalNotification(`✨ ¡Petición de ${activeChild?.name}!`, `Ha solicitado: ${title}`, activeChild?.avatar);
  };

  const handleStudentAddEvent = (title: string, date: string, type: EventType) => {
    if (!activeChildId) return;
    const newEvent: CalendarEvent = { id: crypto.randomUUID(), childId: activeChildId, title, date, type, notified: false };
    setEvents([...events, newEvent]);
    setShowStudentEventForm(false);
    awardPoints(20);
    sendLocalNotification(`🚀 Nuevo evento de ${activeChild?.name}`, `${title} agendado para el día ${date}`, activeChild?.avatar);
  };

  const handleApproveRequest = (requestId: string, dueDate: string) => {
    const request = requests.find(r => r.id === requestId);
    if (!request) return;
    const newTask: Task = { id: crypto.randomUUID(), childId: request.childId, title: `[SOLICITUD] ${request.title}`, dueDate, completed: false, priority: 'medium', fromRequestId: requestId };
    setTasks([...tasks, newTask]);
    setRequests(requests.map(r => r.id === requestId ? { ...r, status: 'approved' } : r));
  };

  const handleRejectRequest = (requestId: string) => {
    setRequests(requests.map(r => r.id === requestId ? { ...r, status: 'rejected' } : r));
  };

  const handleUpdateTask = (id: string, updates: Partial<Task>) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, ...updates } : t));
  };

  const handleAddQuickNote = (note: Omit<QuickNote, 'id' | 'timestamp'>) => {
    const newNote: QuickNote = { ...note, id: crypto.randomUUID(), timestamp: Date.now() };
    setQuickNotes([newNote, ...quickNotes]);
  };

  const handleDeleteQuickNote = (id: string) => {
    setQuickNotes(quickNotes.filter(n => n.id !== id));
  };

  const handleSyncSchoolComms = () => {
    if (children.length === 0) return;
    const randomChild = children[Math.floor(Math.random() * children.length)];
    const mockComms: SchoolCommunication[] = [
      { id: crypto.randomUUID(), childId: randomChild.id, type: 'circular', sender: 'Secretaría Centro', subject: 'Menú Comedor Junio', content: 'Ya está disponible el menú del mes de Junio en la web del centro...', date: new Date().toISOString().split('T')[0], isImportant: false, isRead: false },
      { id: crypto.randomUUID(), childId: randomChild.id, type: 'interview', sender: 'Tutor/a ' + randomChild.name, subject: 'Citación Entrevista Trimestral', content: 'Me gustaría reunirnos el próximo martes a las 16:00 para comentar la evolución de ' + randomChild.name, date: new Date().toISOString().split('T')[0], isImportant: true, isRead: false }
    ];
    setSchoolComms([...mockComms, ...schoolComms]);
    sendLocalNotification("📬 Nuevos correos del colegio", "Tienes comunicaciones nuevas de la escuela.", "🏫");
  };

  const handleMarkCommRead = (id: string) => {
    setSchoolComms(schoolComms.map(c => c.id === id ? { ...c, isRead: true } : c));
  };

  const handleAddEvent = (event: Omit<CalendarEvent, 'id'>) => {
    const newEvent: CalendarEvent = { ...event, id: crypto.randomUUID(), notified: false };
    setEvents(prev => [...prev, newEvent]);
  };

  const handleDeleteEvent = (id: string) => {
    setEvents(prev => prev.filter(e => e.id !== id));
  };

  const handleAddTask = (task: Omit<Task, 'id'>) => {
    const newTask: Task = { ...task, id: crypto.randomUUID() };
    setTasks(prev => [...prev, newTask]);
  };

  const handleToggleTask = (id: string) => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  const handleDeleteTask = (id: string) => {
    setTasks(prev => prev.filter(t => t.id !== id));
  };

  const handleAddChild = (name: string, grade: GradeLevel, avatar: string) => {
    const newChild: Child = { id: crypto.randomUUID(), name, avatar, points: 0, grade };
    setChildren([...children, newChild]);
  };

  const handleTts = (text: string, id: string) => {
    if (isPlayingAudio) return;
    setIsPlayingAudio(id);
    generateSpeech(text).finally(() => setIsPlayingAudio(null));
  };

  if (!isAuthenticated) return <AuthScreen onAuthenticated={() => { setIsAuthenticated(true); sessionStorage.setItem('eduamigo_auth', 'true'); }} onDemo={() => setIsAuthenticated(true)} />;
  if (!userRole) return <Login onLogin={setUserRole} onLogout={() => { setIsAuthenticated(false); sessionStorage.removeItem('eduamigo_auth'); }} />;
  if (userRole === 'student' && !activeChildId) return <div className="min-h-screen bg-[#f0f9ff] p-8"><ChildSelector children={children} onSelect={(c) => setActiveChildId(c.id)} /></div>;

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#f0f9ff]">
      {showAuthModal && <ParentAuthModal onResult={(s) => { setIsParentUnlocked(s); if(s) setViewMode('parent'); setShowAuthModal(false); }} onCancel={() => setShowAuthModal(false)} />}
      {showSOSModal && <SOSModal onSelect={(c) => { handleStudySubmit(undefined, c); }} onClose={() => setShowSOSModal(false)} />}
      {showRequestForm && <StudentRequestForm onSend={handleAddRequest} onClose={() => setShowRequestForm(false)} />}
      {showStudentEventForm && <StudentEventForm onAdd={handleStudentAddEvent} onClose={() => setShowStudentEventForm(false)} />}

      <aside className="hidden md:flex w-80 bg-white border-r border-blue-100 p-6 flex-col h-screen sticky top-0">
        <div className="flex-1 overflow-y-auto no-scrollbar">
          <HistorySidebar history={history.filter(h => h.childId === activeChildId)} onSelect={(item) => { setViewMode('student'); setResult(item.answer); setQuestion(item.question); setActiveSubject(item.subject); }} />
        </div>
      </aside>

      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8 relative">
        <Header viewMode={viewMode} setViewMode={(m) => m === 'parent' && !isParentUnlocked ? setShowAuthModal(true) : setViewMode(m)} userRole={userRole} activeChild={activeChild} />

        {viewMode === 'student' && (
          <div className="fixed bottom-24 right-6 md:bottom-10 md:right-10 flex flex-col gap-3 z-50">
            <button onClick={() => setShowStudentEventForm(true)} className="w-16 h-16 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center text-3xl hover:scale-110 transition-transform" title="Agendar Evento 📅">📅</button>
            <button onClick={() => setShowRequestForm(true)} className="w-16 h-16 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center text-3xl hover:scale-110 transition-transform animate-bounce" title="Solicitar algo ✨">✨</button>
          </div>
        )}

        <div className="mt-8">
          {viewMode === 'student' && activeChild && (
            <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
              <StudyForm 
                grade={activeChild.grade} 
                setGrade={() => {}} 
                subject={activeSubject} 
                setSubject={setActiveSubject} 
                question={question} 
                setQuestion={setQuestion} 
                onSubmit={handleStudySubmit} 
                onSOS={() => setShowSOSModal(true)} 
                loading={loading} 
              />
              <ResultDisplay 
                result={result} 
                loading={loading} 
                grade={activeChild.grade} 
                subject={activeSubject} 
                onSpeak={handleTts} 
                isPlayingId={isPlayingAudio} 
              />
            </div>
          )}
          {viewMode === 'parent' && (
            <ParentDashboard 
              history={history} examHistory={examHistory} children={children} rewards={rewards} events={events} tasks={tasks} requests={requests}
              communications={schoolComms} quickNotes={quickNotes}
              onSelectItem={() => {}} onAddChild={handleAddChild} onUpdateRewards={setRewards} onAddEvent={handleAddEvent} onDeleteEvent={handleDeleteEvent}
              onAddTask={handleAddTask} onToggleTask={handleToggleTask} onDeleteTask={handleDeleteTask}
              onApproveRequest={handleApproveRequest} onRejectRequest={handleRejectRequest} onUpdateTask={handleUpdateTask}
              onAddQuickNote={handleAddQuickNote} onDeleteQuickNote={handleDeleteQuickNote} onSyncSchoolComms={handleSyncSchoolComms} onMarkCommRead={handleMarkCommRead}
            />
          )}
          {viewMode === 'library' && (
            <LibraryBrowser region={region} grade={activeChild?.grade || '1º Primaria'} setGrade={() => {}} />
          )}
          {viewMode === 'exam' && activeChild && (
            <ExamMode grade={activeChild.grade} subject={activeSubject} region={region} childId={activeChild.id} onSaveResult={(res) => {
              setExamHistory([res, ...examHistory]);
              awardPoints(res.pointsEarned);
            }} />
          )}
          {viewMode === 'shop' && activeChild && (
            <RewardsShop child={activeChild} rewards={rewards} />
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { GradeLevel, Subject, ExplanationResponse, Region, Country } from '../types';
import { getExplanation, getSOSExplanation, generateSpeech } from '../services/geminiService';
import StudyForm from './StudyForm';
import ResultDisplay from './ResultDisplay';

interface StudentInquiryProps {
  childName: string;
  grade: GradeLevel;
  region: Region;
  onSuccess: (question: string, subject: Subject, answer: ExplanationResponse) => void;
  onSOS: () => void;
}

const StudentInquiry: React.FC<StudentInquiryProps> = ({ childName, grade, region, onSuccess, onSOS }) => {
  const [question, setQuestion] = useState('');
  const [subject, setSubject] = useState<Subject>('Matemáticas');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ExplanationResponse | null>(null);
  const [isPlayingAudio, setIsPlayingAudio] = useState<string | null>(null);

  const handleTts = (text: string, id: string) => {
    if (isPlayingAudio) return;
    setIsPlayingAudio(id);
    generateSpeech(text).finally(() => setIsPlayingAudio(null));
  };

  const handleQuerySubmit = async (e?: React.FormEvent, sosCountry?: Country) => {
    if (e) e.preventDefault();
    if (!question.trim()) return;

    setLoading(true);
    setResult(null);

    try {
      const res = sosCountry 
        ? await getSOSExplanation(grade, subject, question, sosCountry)
        : await getExplanation(grade, subject, question, region);

      setResult(res);
      onSuccess(question, subject, res);
    } catch (error) {
      console.error("Error al consultar:", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
      <div className="bg-white rounded-[2.5rem] p-8 md:p-10 shadow-xl border-2 border-blue-100">
        <div className="flex items-center gap-4 mb-6">
          <div className="bg-blue-600 p-3 rounded-2xl">
             <span className="text-2xl">✍️</span>
          </div>
          <div>
            <h2 className="text-2xl font-black text-blue-900">¿Qué quieres aprender hoy, {childName}?</h2>
            <p className="text-blue-500 font-bold text-sm">Explícame tu duda y la resolveremos juntos con IA.</p>
          </div>
        </div>

        <StudyForm 
          grade={grade}
          setGrade={() => {}} 
          subject={subject}
          setSubject={setSubject}
          question={question}
          setQuestion={setQuestion}
          onSubmit={handleQuerySubmit}
          onSOS={onSOS}
          loading={loading}
        />
      </div>

      <ResultDisplay 
        result={result} 
        loading={loading} 
        grade={grade} 
        subject={subject} 
        onSpeak={handleTts} 
        isPlayingId={isPlayingAudio} 
      />
    </div>
  );
};

