import StudentInquiry from './components/StudentInquiry';
import LocationHub from './components/LocationHub';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState<UserRole>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('student');
  const [region, setRegion] = useState<Region>('Madrid');
  const [isParentUnlocked, setIsParentUnlocked] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [showSOSModal, setShowSOSModal] = useState(false);
  const [showRequestForm, setShowRequestForm] = useState(false);
  const [showStudentEventForm, setShowStudentEventForm] = useState(false);

  const [children, setChildren] = useState<Child[]>([]);
  const [activeChildId, setActiveChildId] = useState<string | null>(null);
  const [rewards, setRewards] = useState<Reward[]>([]);
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [requests, setRequests] = useState<StudentRequest[]>([]);
  const [schoolComms, setSchoolComms] = useState<SchoolCommunication[]>([]);
  const [quickNotes, setQuickNotes] = useState<QuickNote[]>([]);
  const [locationStates, setLocationStates] = useState<LocationState[]>([]);

  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [examHistory, setExamHistory] = useState<ExamResult[]>([]);

  const watchIdRef = useRef<number | null>(null);
  const activeChild = children.find(c => c.id === activeChildId) || null;

  useEffect(() => {
    const sessionAuth = sessionStorage.getItem('eduamigo_auth');
    if (sessionAuth) setIsAuthenticated(true);

    setRegion(localStorage.getItem('eduamigo_region') as Region || 'Madrid');
    setHistory(JSON.parse(localStorage.getItem('eduamigo_history') || '[]'));
    setExamHistory(JSON.parse(localStorage.getItem('eduamigo_exam_history') || '[]'));
    setChildren(JSON.parse(localStorage.getItem('eduamigo_children') || '[]'));
    setRewards(JSON.parse(localStorage.getItem('eduamigo_rewards') || '[]'));
    setEvents(JSON.parse(localStorage.getItem('eduamigo_events') || '[]'));
    setTasks(JSON.parse(localStorage.getItem('eduamigo_tasks') || '[]'));
    setRequests(JSON.parse(localStorage.getItem('eduamigo_requests') || '[]'));
    setSchoolComms(JSON.parse(localStorage.getItem('eduamigo_schoolComms') || '[]'));
    setQuickNotes(JSON.parse(localStorage.getItem('eduamigo_quickNotes') || '[]'));
    setLocationStates(JSON.parse(localStorage.getItem('eduamigo_locationStates') || '[]'));

    requestNotificationPermission();
  }, []);

  useEffect(() => {
    if (userRole && userRole !== 'demo') {
      const data = { history, examHistory, children, rewards, events, tasks, requests, schoolComms, quickNotes, locationStates };
      Object.entries(data).forEach(([key, val]) => localStorage.setItem(`eduamigo_${key}`, JSON.stringify(val)));
      localStorage.setItem('eduamigo_region', region);
    }
  }, [history, examHistory, children, rewards, events, tasks, requests, schoolComms, quickNotes, locationStates, userRole, region]);

  useEffect(() => {
    const isTrackingAny = locationStates.some(s => s.isTracking);
    const shouldWatch = viewMode === 'location' || isTrackingAny;

    if (shouldWatch && navigator.geolocation) {
      if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current);

      watchIdRef.current = navigator.geolocation.watchPosition(
        (pos) => {
          const newCoord: Coordinate = { lat: pos.coords.latitude, lng: pos.coords.longitude };
          if (activeChildId) {
            updateLocation(activeChildId, newCoord);
          }
        },
        (err) => console.error("Geolocation Error:", err),
        { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
      );
    } else {
      if (watchIdRef.current !== null) {
        navigator.geolocation.clearWatch(watchIdRef.current);
        watchIdRef.current = null;
      }
    }

    return () => {
      if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current);
    };
  }, [activeChildId, locationStates.some(s => s.isTracking), viewMode]);

  const fetchRouteViaGemini = async (childId: string, origin: Coordinate, destination: Coordinate, destinationName: string) => {
    try {
      const prompt = `Actúa como un experto en navegación. Usando Google Maps, encuentra la mejor ruta a pie desde [Lat: ${origin.lat}, Lng: ${origin.lng}] hasta [Lat: ${destination.lat}, Lng: ${destination.lng}] (que es ${destinationName}). 
      Proporciona una lista de al menos 10 coordenadas intermedias (latitud, longitud) que sigan las calles reales. 
      Devuelve los puntos en este formato estricto: "PUNTO: LAT, LNG".`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: { latitude: origin.lat, longitude: origin.lng }
            }
          }
        }
      });

      const text = response.text || "";
      const urls = response.candidates?.[0]?.groundingMetadata?.groundingChunks
        ?.map(c => c.maps?.uri || "")
        .filter(u => u !== "") || [];

      // Extract points via regex
      const regex = /PUNTO:\s*(-?\d+\.\d+)\s*,\s*(-?\d+\.\d+)/g;
      const points: Coordinate[] = [];
      let match;
      while ((match = regex.exec(text)) !== null) {
        points.push({ lat: parseFloat(match[1]), lng: parseFloat(match[2]) });
      }

      if (points.length > 0) {
        setLocationStates(prev => prev.map(s => 
          s.childId === childId ? { ...s, routePath: points, groundingUrls: urls } : s
        ));
      }
    } catch (e) {
      console.error("Error fetching Maps route:", e);
    }
  };

  const updateLocation = (childId: string, coord: Coordinate) => {
    setLocationStates(prev => prev.map(s => {
      if (s.childId !== childId) return s;

      const newPoint: RoutePoint = { coord, timestamp: Date.now(), status: 'normal' };

      // Geofencing and Deviation logic
      if (s.homeCoord && getDist(coord, s.homeCoord) < s.safeRadius) {
         if (s.history.length > 0 && s.history[s.history.length-1].status !== 'home') {
           sendLocalNotification("🏠 ¡A casa!", "Tu hijo/a ha llegado a CASA correctamente.");
         }
         newPoint.status = 'home';
      } else if (s.schoolCoord && getDist(coord, s.schoolCoord) < s.safeRadius) {
        if (s.history.length > 0 && s.history[s.history.length-1].status !== 'school') {
          sendLocalNotification("🏫 ¡Llegada al cole!", "Tu hijo/a ha llegado al COLEGIO correctamente.");
        }
        newPoint.status = 'school';
      } else if (s.routePath.length > 0 && s.isTracking) {
        // Deviation Check against the Google Maps Route Path
        const minDistToRoute = Math.min(...s.routePath.map(p => getDist(coord, p)));
        if (minDistToRoute > 300) { 
           newPoint.status = 'deviation';
           sendLocalNotification("⚠️ ¡Fuera de Ruta!", "Se ha detectado una desviación de más de 300 metros de la ruta de Google Maps.", "🚩");
        }
      }

      return { 
        ...s, 
        currentCoord: coord, 
        history: s.isTracking ? [...s.history, newPoint].slice(-100) : s.history 
      };
    }));
  };

  const getDist = (c1: Coordinate, c2: Coordinate) => {
    const R = 6371e3; 
    const φ1 = c1.lat * Math.PI/180;
    const φ2 = c2.lat * Math.PI/180;
    const Δφ = (c2.lat-c1.lat) * Math.PI/180;
    const Δλ = (c2.lng-c1.lng) * Math.PI/180;
    const a = Math.sin(Δφ/2) * Math.sin(Δφ/2) + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ/2) * Math.sin(Δλ/2);
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  };

  const handleToggleTracking = (childId: string) => {
    setLocationStates(prev => {
      const newState = prev.map(s => {
        if (s.childId !== childId) return s;
        const willBeTracking = !s.isTracking;

        // When starting tracking, determine destination based on proximity
        let destination: 'home' | 'school' | null = s.destination;
        if (willBeTracking && s.currentCoord && s.homeCoord && s.schoolCoord) {
          const distToHome = getDist(s.currentCoord, s.homeCoord);
          const distToSchool = getDist(s.currentCoord, s.schoolCoord);

          // Logic: If closer to home, destination is school (going to school). Else, destination is home (returning).
          destination = distToHome < distToSchool ? 'school' : 'home';

          const targetCoord = destination === 'home' ? s.homeCoord : s.schoolCoord;
          fetchRouteViaGemini(childId, s.currentCoord, targetCoord, destination === 'home' ? "Casa" : "Colegio");
        }

        return { 
          ...s, 
          isTracking: willBeTracking, 
          destination: willBeTracking ? destination : null,
          history: willBeTracking ? [] : s.history,
          routePath: willBeTracking ? s.routePath : [], // Reset path when done
          groundingUrls: willBeTracking ? s.groundingUrls : []
        };
      });
      return newState;
    });
  };

  const handleSetLocationPoint = (childId: string, type: 'home' | 'school', coord: Coordinate) => {
    setLocationStates(prev => prev.map(s => s.childId === childId ? { ...s, [type === 'home' ? 'homeCoord' : 'schoolCoord']: coord } : s));
  };

  const handleAddChild = (name: string, grade: GradeLevel, avatar: string) => {
    const id = crypto.randomUUID();
    const newChild: Child = { id, name, avatar, points: 0, grade };
    setChildren([...children, newChild]);
    const newLoc: LocationState = { 
      childId: id, isTracking: false, currentCoord: null, history: [], 
      homeCoord: null, schoolCoord: null, safeRadius: 100, 
      routePath: [], destination: null, groundingUrls: [] 
    };
    setLocationStates([...locationStates, newLoc]);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    sessionStorage.removeItem('eduamigo_auth');
    setUserRole(null);
    setActiveChildId(null);
  };

  if (!isAuthenticated) return <AuthScreen onAuthenticated={() => { setIsAuthenticated(true); sessionStorage.setItem('eduamigo_auth', 'true'); }} onDemo={() => setIsAuthenticated(true)} />;
  if (!userRole) return <Login onLogin={setUserRole} onLogout={handleLogout} />;

  if (viewMode !== 'parent' && !activeChildId) {
    return (
      <div className="min-h-screen bg-[#f0f9ff] p-8 flex flex-col items-center justify-center">
        <ChildSelector children={children} onSelect={(c) => setActiveChildId(c.id)} onAddChild={() => setViewMode('parent')} />
        <button onClick={handleLogout} className="mt-8 text-blue-400 font-bold hover:underline">Cerrar Sesión</button>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#f0f9ff]">
      {showAuthModal && <ParentAuthModal onResult={(s) => { setIsParentUnlocked(s); if(s) setViewMode('parent'); setShowAuthModal(false); }} onCancel={() => setShowAuthModal(false)} />}
      {showSOSModal && <SOSModal onSelect={(c) => { }} onClose={() => setShowSOSModal(false)} />}
      {showRequestForm && <StudentRequestForm onSend={handleAddRequest} onClose={() => setShowRequestForm(false)} />}
      {showStudentEventForm && <StudentEventForm onAdd={handleStudentAddEvent} onClose={() => setShowStudentEventForm(false)} />}

      <aside className="hidden md:flex w-80 bg-white border-r border-blue-100 p-6 flex-col h-screen sticky top-0">
        <div className="flex-1 overflow-y-auto no-scrollbar">
          <HistorySidebar history={history.filter(h => h.childId === activeChildId)} onSelect={(item) => { setViewMode('student'); }} />
        </div>
      </aside>

      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8 relative">
        <Header viewMode={viewMode} setViewMode={(m) => m === 'parent' && !isParentUnlocked ? setShowAuthModal(true) : setViewMode(m)} userRole={userRole} activeChild={activeChild} />

        {viewMode === 'student' && (
          <div className="fixed bottom-24 right-6 md:bottom-10 md:right-10 flex flex-col gap-3 z-50">
            <button onClick={() => setShowStudentEventForm(true)} className="w-16 h-16 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center text-3xl hover:scale-110 transition-transform" title="Agendar Evento 📅">📅</button>
            <button onClick={() => setShowRequestForm(true)} className="w-16 h-16 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center text-3xl hover:scale-110 transition-transform animate-bounce" title="Solicitar algo ✨">✨</button>
          </div>
        )}

        <div className="mt-8">
          {viewMode === 'student' && activeChild && (
            <StudentInquiry childName={activeChild.name} grade={activeChild.grade} region={region} onSuccess={handleInquirySuccess} onSOS={() => setShowSOSModal(true)} />
          )}
          {viewMode === 'location' && (
            <LocationHub viewMode="student" child={activeChild} locationStates={locationStates} onToggleTracking={handleToggleTracking} onSetPoint={handleSetLocationPoint} />
          )}
          {viewMode === 'parent' && (
            <ParentDashboard 
              history={history} examHistory={examHistory} children={children} rewards={rewards} events={events} tasks={tasks} requests={requests}
              communications={schoolComms} quickNotes={quickNotes} locationStates={locationStates}
              onSelectItem={() => {}} onAddChild={handleAddChild} onUpdateRewards={setRewards} onAddEvent={(e) => setEvents([...events, {...e, id: crypto.randomUUID(), notified: false}])} onDeleteEvent={(id) => setEvents(events.filter(e => e.id !== id))}
              onAddTask={(t) => setTasks([...tasks, {...t, id: crypto.randomUUID()}])} onToggleTask={(id) => setTasks(tasks.map(t => t.id === id ? {...t, completed: !t.completed} : t))} onDeleteTask={(id) => setTasks(tasks.filter(t => t.id !== id))}
              onApproveRequest={handleApproveRequest} onRejectRequest={(id) => setRequests(requests.map(r => r.id === id ? { ...r, status: 'rejected' } : r))} onUpdateTask={(id, up) => setTasks(tasks.map(t => t.id === id ? {...t, ...up} : t))}
              onAddQuickNote={(n) => setQuickNotes([{...n, id: crypto.randomUUID(), timestamp: Date.now()}, ...quickNotes])} onDeleteQuickNote={(id) => setQuickNotes(quickNotes.filter(q => q.id !== id))} onSyncSchoolComms={() => {}} onMarkCommRead={(id) => setSchoolComms(schoolComms.map(c => c.id === id ? {...c, isRead: true} : c))}
              onToggleTracking={handleToggleTracking} onSetLocationPoint={handleSetLocationPoint}
            />
          )}
          {viewMode === 'library' && <LibraryBrowser region={region} grade={activeChild?.grade || '1º Primaria'} setGrade={() => {}} />}
          {viewMode === 'exam' && activeChild && (
            <ExamMode grade={activeChild.grade} subject={'Matemáticas'} region={region} childId={activeChild.id} onSaveResult={(res) => {
              setExamHistory([res, ...examHistory]); awardPoints(res.pointsEarned);
            }} />
          )}
          {viewMode === 'shop' && activeChild && <RewardsShop child={activeChild} rewards={rewards} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Child, LocationState, Coordinate } from '../types';

interface LocationHubProps {
  viewMode: 'student' | 'parent';
  child: Child | null;
  locationStates: LocationState[];
  onToggleTracking: (childId: string) => void;
  onSetPoint: (childId: string, type: 'home' | 'school', coord: Coordinate) => void;
}

const LocationHub: React.FC<LocationHubProps> = ({ 
  viewMode, child, locationStates, onToggleTracking, onSetPoint 
}) => {
  const state = locationStates.find(s => s.childId === (child?.id || '')) || null;
  const [saveStatus, setSaveStatus] = useState<'none' | 'home' | 'school'>('none');

  // Helper: Haversine distance in meters
  const getDistance = (c1: Coordinate, c2: Coordinate) => {
    if (!c1 || !c2) return 999999;
    const R = 6371e3; 
    const φ1 = c1.lat * Math.PI/180;
    const φ2 = c2.lat * Math.PI/180;
    const Δφ = (c2.lat-c1.lat) * Math.PI/180;
    const Δλ = (c2.lng-c1.lng) * Math.PI/180;
    const a = Math.sin(Δφ/2) * Math.sin(Δφ/2) +
              Math.cos(φ1) * Math.cos(φ2) *
              Math.sin(Δλ/2) * Math.sin(Δλ/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    return R * c;
  };

  const handleSetCurrentAs = (type: 'home' | 'school') => {
    if (!state?.currentCoord) {
      alert("Esperando señal GPS activa... Asegúrate de permitir la ubicación en tu navegador y espera unos segundos.");
      return;
    }
    onSetPoint(state.childId, type, state.currentCoord);
    setSaveStatus(type);
    setTimeout(() => setSaveStatus('none'), 3000);
  };

  if (viewMode === 'student') {
    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <div className={`p-8 rounded-[3rem] shadow-xl border-4 transition-all text-center ${state?.isTracking ? 'bg-green-600 border-green-400 text-white' : 'bg-white border-indigo-600 text-indigo-900'}`}>
          <div className="text-6xl mb-4">{state?.isTracking ? (state.destination === 'home' ? '🏠' : '🎒') : '🏠'}</div>
          <h2 className="text-3xl font-black mb-2">
            {state?.isTracking ? (state.destination === 'home' ? 'Volviendo a Casa' : 'Yendo al Colegio') : 'Ruta Segura'}
          </h2>
          <p className={`font-bold mb-8 opacity-80 ${state?.isTracking ? 'text-green-100' : 'text-indigo-500'}`}>
            {state?.isTracking 
              ? `EduAmigo está calculando la mejor ruta de Google Maps hasta tu destino.` 
              : 'Avísanos cuando salgas solo hacia el cole o vuelvas a casa para protegerte.'}
          </p>

          <button 
            onClick={() => state && onToggleTracking(state.childId)}
            className={`w-full py-6 rounded-3xl font-black text-xl shadow-2xl transform active:scale-95 transition-all ${state?.isTracking ? 'bg-white text-green-600' : 'bg-indigo-600 text-white'}`}
          >
            {state?.isTracking ? 'He llegado al destino ✅' : 'Iniciar Ruta 🎒'}
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
           <button 
            onClick={() => handleSetCurrentAs('home')} 
            className={`p-4 rounded-2xl border-2 font-black text-xs transition-all flex items-center justify-center gap-2 ${saveStatus === 'home' ? 'bg-green-100 border-green-500 text-green-600' : 'bg-white border-indigo-50 text-indigo-400 hover:border-indigo-200'}`}
           >
             📍 {saveStatus === 'home' ? '¡Casa Guardada! ✅' : state?.homeCoord ? 'Actualizar mi Casa' : 'Guardar Ubicación como Casa'}
           </button>
           <button 
            onClick={() => handleSetCurrentAs('school')} 
            className={`p-4 rounded-2xl border-2 font-black text-xs transition-all flex items-center justify-center gap-2 ${saveStatus === 'school' ? 'bg-green-100 border-green-500 text-green-600' : 'bg-white border-indigo-50 text-indigo-400 hover:border-indigo-200'}`}
           >
             📍 {saveStatus === 'school' ? '¡Cole Guardado! ✅' : state?.schoolCoord ? 'Actualizar mi Cole' : 'Guardar Ubicación como Cole'}
           </button>
        </div>
      </div>
    );
  }

  // Parent View
  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h3 className="text-xl font-black text-blue-900">Seguridad y Rutas Dinámicas</h3>
        {locationStates.some(s => s.isTracking) && (
          <span className="flex items-center gap-2 text-green-500 text-xs font-black animate-pulse bg-green-50 px-3 py-1 rounded-full border border-green-100">
            <span className="w-2 h-2 bg-green-500 rounded-full"></span> GOOGLE MAPS ACTIVE
          </span>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1 space-y-4">
          {locationStates.map(ls => {
            const isAtHome = ls.currentCoord && ls.homeCoord && getDistance(ls.currentCoord, ls.homeCoord) < ls.safeRadius;
            const isAtSchool = ls.currentCoord && ls.schoolCoord && getDistance(ls.currentCoord, ls.schoolCoord) < ls.safeRadius;
            const lastPoint = ls.history[ls.history.length - 1];
            const isDeviated = lastPoint?.status === 'deviation';

            return (
              <div key={ls.childId} className={`p-6 rounded-[2rem] border-2 transition-all ${isDeviated ? 'bg-red-50 border-red-200 shadow-lg shadow-red-100' : ls.isTracking ? 'bg-green-50 border-green-200 shadow-lg shadow-green-100' : 'bg-white border-blue-50'}`}>
                <div className="flex items-center gap-4 mb-4">
                  <div className="w-12 h-12 bg-blue-100 rounded-2xl flex items-center justify-center text-3xl">👦</div>
                  <div>
                    <h4 className="font-black text-blue-900">Seguimiento</h4>
                    <span className={`text-[10px] font-black px-2 py-0.5 rounded uppercase ${ls.isTracking ? 'bg-green-500 text-white' : 'bg-gray-200 text-gray-500'}`}>
                      {ls.isTracking ? (ls.destination === 'home' ? 'Vuelta a casa' : 'Hacia el cole') : 'Reposo'}
                    </span>
                  </div>
                </div>

                <div className="space-y-2">
                  <div className="flex justify-between text-xs">
                    <span className="text-gray-400">Estado:</span>
                    <span className={`font-bold ${isDeviated ? 'text-red-600' : 'text-blue-600'}`}>
                      {isDeviated ? '⚠️ DESVIADO DE RUTA' : isAtHome ? 'En Casa 🏠' : isAtSchool ? 'En el Cole 🏫' : ls.isTracking ? 'En camino🚶' : 'Localizado'}
                    </span>
                  </div>
                  {ls.groundingUrls.length > 0 && (
                    <div className="mt-4 pt-4 border-t border-blue-100">
                      <p className="text-[10px] font-black text-blue-400 uppercase mb-2">Fuentes Google Maps:</p>
                      <div className="flex flex-col gap-1">
                        {ls.groundingUrls.map((url, i) => (
                          <a key={i} href={url} target="_blank" rel="noreferrer" className="text-[10px] text-blue-600 hover:underline font-bold truncate">
                            🔗 Ver ruta en Google Maps
                          </a>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        <div className="lg:col-span-2 bg-white rounded-[2.5rem] border border-blue-50 shadow-sm p-6 overflow-hidden relative min-h-[400px]">
           <div className="absolute top-6 left-6 z-10 bg-white/80 backdrop-blur px-3 py-1 rounded-full text-[10px] font-black text-blue-600 border border-blue-100 uppercase flex items-center gap-2">
             <span className="w-2 h-2 bg-blue-600 rounded-full"></span> Pasillo de Google Maps (300m)
           </div>

           <div className="w-full h-full flex items-center justify-center bg-blue-50/30 rounded-[2rem] border border-dashed border-blue-100 relative">
             <svg width="100%" height="100%" viewBox="0 0 400 300" className="opacity-90">
                {/* School Zone */}
                <circle cx="340" cy="60" r="25" fill="rgba(79, 70, 229, 0.1)" stroke="rgba(79, 70, 229, 0.4)" strokeDasharray="4" />
                <text x="325" y="30" fontSize="9" className="fill-indigo-500 font-black">COLEGIO</text>

                {/* Home Zone */}
                <circle cx="60" cy="240" r="25" fill="rgba(234, 179, 8, 0.1)" stroke="rgba(234, 179, 8, 0.4)" strokeDasharray="4" />
                <text x="48" y="210" fontSize="9" className="fill-yellow-600 font-black">CASA</text>

                {/* Dynamic Google Maps Path */}
                {state?.routePath.length && state.routePath.length > 1 ? (
                  <path 
                    d={`M ${60 + (Math.random() * 20)} ${240 + (Math.random() * 20)} ${state.routePath.map((_, i) => `L ${100 + i*20} ${200 - i*12}`).join(' ')} L 340 60`}
                    fill="none" 
                    stroke="rgba(79, 70, 229, 0.2)" 
                    strokeWidth="40" 
                    strokeLinecap="round" 
                  />
                ) : (
                   <path d="M 60 240 Q 150 200 200 150 T 340 60" fill="none" stroke="rgba(79, 70, 229, 0.08)" strokeWidth="60" strokeLinecap="round" />
                )}

                {/* Main Visual Line */}
                <path d="M 60 240 Q 150 200 200 150 T 340 60" fill="none" stroke="#4f46e5" strokeWidth="2" strokeLinecap="round" strokeDasharray="6" />

                {/* Current Location Marker */}
                {state?.currentCoord && (
                   <g>
                     <circle cx="210" cy="140" r="10" fill={state.history[state.history.length-1]?.status === 'deviation' ? 'rgba(239, 68, 68, 0.3)' : 'rgba(79, 70, 229, 0.3)'} className="animate-pulse" />
                     <circle cx="210" cy="140" r="4" fill={state.history[state.history.length-1]?.status === 'deviation' ? '#ef4444' : '#4f46e5'} />
                   </g>
                )}
             </svg>

             <div className="absolute bottom-6 right-6 flex flex-col gap-2">
                <div className="flex items-center gap-2 bg-white/90 backdrop-blur px-3 py-1.5 rounded-full text-[10px] shadow-sm font-bold text-gray-600">
                   <div className="w-2.5 h-2.5 rounded-full bg-blue-600"></div> Ruta de Google Maps
                </div>
                <div className="flex items-center gap-2 bg-white/90 backdrop-blur px-3 py-1.5 rounded-full text-[10px] shadow-sm font-bold text-red-600">
                   <div className="w-2.5 h-2.5 rounded-full bg-red-500 animate-pulse"></div> Desviación Real
                </div>
             </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default LocationHub;

import React, { useState, useEffect, useRef } from 'react';
import { GradeLevel, Subject, ExplanationResponse, HistoryItem, ViewMode, UserRole, Region, ExamResult, Child, Reward, Country, CalendarEvent, Task, StudentRequest, EventType, SchoolCommunication, QuickNote, LocationState, Coordinate, RoutePoint } from './types';
import { requestNotificationPermission, checkUpcomingEvents, sendLocalNotification } from './services/notificationService';
import { GoogleGenAI } from "@google/genai";
import Header from './components/Header';
import HistorySidebar from './components/HistorySidebar';
import ParentDashboard from './components/ParentDashboard';
import Login from './components/Login';
import AuthScreen from './components/AuthScreen';
import ParentAuthModal from './components/ParentAuthModal';
import LibraryBrowser from './components/LibraryBrowser';
import ExamMode from './components/ExamMode';
import ChildSelector from './components/ChildSelector';
import RewardsShop from './components/RewardsShop';
import SOSModal from './components/SOSModal';
import StudentRequestForm from './components/StudentRequestForm';
import StudentEventForm from './components/StudentEventForm';
import StudentInquiry from './components/StudentInquiry';
import LocationHub from './components/LocationHub';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState<UserRole>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('student');
  const [region, setRegion] = useState<Region>('Madrid');
  const [isParentUnlocked, setIsParentUnlocked] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [showSOSModal, setShowSOSModal] = useState(false);
  const [showRequestForm, setShowRequestForm] = useState(false);
  const [showStudentEventForm, setShowStudentEventForm] = useState(false);

  const [children, setChildren] = useState<Child[]>([]);
  const [activeChildId, setActiveChildId] = useState<string | null>(null);
  const [rewards, setRewards] = useState<Reward[]>([]);
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [requests, setRequests] = useState<StudentRequest[]>([]);
  const [schoolComms, setSchoolComms] = useState<SchoolCommunication[]>([]);
  const [quickNotes, setQuickNotes] = useState<QuickNote[]>([]);
  const [locationStates, setLocationStates] = useState<LocationState[]>([]);

  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [examHistory, setExamHistory] = useState<ExamResult[]>([]);

  const watchIdRef = useRef<number | null>(null);
  const activeChild = children.find(c => c.id === activeChildId) || null;

  useEffect(() => {
    const sessionAuth = sessionStorage.getItem('eduamigo_auth');
    if (sessionAuth) setIsAuthenticated(true);

    setRegion(localStorage.getItem('eduamigo_region') as Region || 'Madrid');
    setHistory(JSON.parse(localStorage.getItem('eduamigo_history') || '[]'));
    setExamHistory(JSON.parse(localStorage.getItem('eduamigo_exam_history') || '[]'));
    setChildren(JSON.parse(localStorage.getItem('eduamigo_children') || '[]'));
    setRewards(JSON.parse(localStorage.getItem('eduamigo_rewards') || '[]'));
    setEvents(JSON.parse(localStorage.getItem('eduamigo_events') || '[]'));
    setTasks(JSON.parse(localStorage.getItem('eduamigo_tasks') || '[]'));
    setRequests(JSON.parse(localStorage.getItem('eduamigo_requests') || '[]'));
    setSchoolComms(JSON.parse(localStorage.getItem('eduamigo_schoolComms') || '[]'));
    setQuickNotes(JSON.parse(localStorage.getItem('eduamigo_quickNotes') || '[]'));
    setLocationStates(JSON.parse(localStorage.getItem('eduamigo_locationStates') || '[]'));

    requestNotificationPermission();
  }, []);

  useEffect(() => {
    if (userRole && userRole !== 'demo') {
      const data = { history, examHistory, children, rewards, events, tasks, requests, schoolComms, quickNotes, locationStates };
      Object.entries(data).forEach(([key, val]) => localStorage.setItem(`eduamigo_${key}`, JSON.stringify(val)));
      localStorage.setItem('eduamigo_region', region);
    }
  }, [history, examHistory, children, rewards, events, tasks, requests, schoolComms, quickNotes, locationStates, userRole, region]);

  useEffect(() => {
    const isTrackingAny = locationStates.some(s => s.isTracking);
    const shouldWatch = viewMode === 'location' || isTrackingAny;

    if (shouldWatch && navigator.geolocation) {
      if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current);

      watchIdRef.current = navigator.geolocation.watchPosition(
        (pos) => {
          const newCoord: Coordinate = { lat: pos.coords.latitude, lng: pos.coords.longitude };
          if (activeChildId) {
            updateLocation(activeChildId, newCoord);
          }
        },
        (err) => console.error("Geolocation Error:", err),
        { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
      );
    } else {
      if (watchIdRef.current !== null) {
        navigator.geolocation.clearWatch(watchIdRef.current);
        watchIdRef.current = null;
      }
    }

    return () => {
      if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current);
    };
  }, [activeChildId, locationStates.some(s => s.isTracking), viewMode]);

  const fetchRouteViaGemini = async (childId: string, origin: Coordinate, destination: Coordinate, destinationName: string) => {
    try {
      const prompt = `Actúa como un experto en navegación. Usando Google Maps, encuentra la mejor ruta a pie desde [Lat: ${origin.lat}, Lng: ${origin.lng}] hasta [Lat: ${destination.lat}, Lng: ${destination.lng}] (que es ${destinationName}). 
      Proporciona una lista de al menos 10 coordenadas intermedias (latitud, longitud) que sigan las calles reales. 
      Devuelve los puntos en este formato estricto: "PUNTO: LAT, LNG".`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: { latitude: origin.lat, longitude: origin.lng }
            }
          }
        }
      });

      const text = response.text || "";
      const urls = response.candidates?.[0]?.groundingMetadata?.groundingChunks
        ?.map(c => c.maps?.uri || "")
        .filter(u => u !== "") || [];

      // Extract points via regex
      const regex = /PUNTO:\s*(-?\d+\.\d+)\s*,\s*(-?\d+\.\d+)/g;
      const points: Coordinate[] = [];
      let match;
      while ((match = regex.exec(text)) !== null) {
        points.push({ lat: parseFloat(match[1]), lng: parseFloat(match[2]) });
      }

      if (points.length > 0) {
        setLocationStates(prev => prev.map(s => 
          s.childId === childId ? { ...s, routePath: points, groundingUrls: urls } : s
        ));
      }
    } catch (e) {
      console.error("Error fetching Maps route:", e);
    }
  };

  const updateLocation = (childId: string, coord: Coordinate) => {
    setLocationStates(prev => prev.map(s => {
      if (s.childId !== childId) return s;

      const newPoint: RoutePoint = { coord, timestamp: Date.now(), status: 'normal' };

      // Geofencing and Deviation logic
      if (s.homeCoord && getDist(coord, s.homeCoord) < s.safeRadius) {
         if (s.history.length > 0 && s.history[s.history.length-1].status !== 'home') {
           sendLocalNotification("🏠 ¡A casa!", "Tu hijo/a ha llegado a CASA correctamente.");
         }
         newPoint.status = 'home';
      } else if (s.schoolCoord && getDist(coord, s.schoolCoord) < s.safeRadius) {
        if (s.history.length > 0 && s.history[s.history.length-1].status !== 'school') {
          sendLocalNotification("🏫 ¡Llegada al cole!", "Tu hijo/a ha llegado al COLEGIO correctamente.");
        }
        newPoint.status = 'school';
      } else if (s.routePath.length > 0 && s.isTracking) {
        // Deviation Check against the Google Maps Route Path
        const minDistToRoute = Math.min(...s.routePath.map(p => getDist(coord, p)));
        if (minDistToRoute > 300) { 
           newPoint.status = 'deviation';
           sendLocalNotification("⚠️ ¡Fuera de Ruta!", "Se ha detectado una desviación de más de 300 metros de la ruta de Google Maps.", "🚩");
        }
      }

      return { 
        ...s, 
        currentCoord: coord, 
        history: s.isTracking ? [...s.history, newPoint].slice(-100) : s.history 
      };
    }));
  };

  const getDist = (c1: Coordinate, c2: Coordinate) => {
    const R = 6371e3; 
    const φ1 = c1.lat * Math.PI/180;
    const φ2 = c2.lat * Math.PI/180;
    const Δφ = (c2.lat-c1.lat) * Math.PI/180;
    const Δλ = (c2.lng-c1.lng) * Math.PI/180;
    const a = Math.sin(Δφ/2) * Math.sin(Δφ/2) + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ/2) * Math.sin(Δλ/2);
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  };

  // Fix: Missing handler for awarding points to the active child
  const awardPoints = (points: number) => {
    if (!activeChildId) return;
    setChildren(prev => prev.map(c => 
      c.id === activeChildId ? { ...c, points: c.points + points } : c
    ));
  };

  // Fix: Missing handler for successful inquiry processing
  const handleInquirySuccess = (question: string, subject: Subject, answer: ExplanationResponse) => {
    if (!activeChildId || !activeChild) return;
    const newItem: HistoryItem = {
      id: crypto.randomUUID(),
      childId: activeChildId,
      grade: activeChild.grade,
      subject,
      region,
      question,
      answer,
      timestamp: Date.now()
    };
    setHistory(prev => [newItem, ...prev].slice(0, 20));
    awardPoints(5);
  };

  // Fix: Missing handler for student requests
  const handleAddRequest = (title: string, message: string) => {
    if (!activeChildId) return;
    const newRequest: StudentRequest = {
      id: crypto.randomUUID(),
      childId: activeChildId,
      title,
      message,
      timestamp: Date.now(),
      status: 'pending'
    };
    setRequests(prev => [...prev, newRequest]);
    setShowRequestForm(false);
  };

  // Fix: Missing handler for students adding events to the agenda
  const handleStudentAddEvent = (title: string, date: string, type: EventType) => {
    if (!activeChildId) return;
    const newEvent: CalendarEvent = {
      id: crypto.randomUUID(),
      childId: activeChildId,
      title,
      date,
      type,
      notified: false
    };
    setEvents(prev => [...prev, newEvent]);
    awardPoints(20);
    setShowStudentEventForm(false);
  };

  // Fix: Missing handler for approving student requests from parent dashboard
  const handleApproveRequest = (requestId: string, dueDate: string) => {
    const request = requests.find(r => r.id === requestId);
    if (!request) return;

    const newTask: Task = {
      id: crypto.randomUUID(),
      childId: request.childId,
      title: request.title,
      dueDate,
      completed: false,
      priority: 'medium',
      fromRequestId: requestId
    };

    setTasks(prev => [...prev, newTask]);
    setRequests(prev => prev.map(r => r.id === requestId ? { ...r, status: 'approved' } : r));
  };

  const handleToggleTracking = (childId: string) => {
    setLocationStates(prev => {
      const newState = prev.map(s => {
        if (s.childId !== childId) return s;
        const willBeTracking = !s.isTracking;

        // When starting tracking, determine destination based on proximity
        let destination: 'home' | 'school' | null = s.destination;
        if (willBeTracking && s.currentCoord && s.homeCoord && s.schoolCoord) {
          const distToHome = getDist(s.currentCoord, s.homeCoord);
          const distToSchool = getDist(s.currentCoord, s.schoolCoord);

          // Logic: If closer to home, destination is school (going to school). Else, destination is home (returning).
          destination = distToHome < distToSchool ? 'school' : 'home';

          const targetCoord = destination === 'home' ? s.homeCoord : s.schoolCoord;
          fetchRouteViaGemini(childId, s.currentCoord, targetCoord, destination === 'home' ? "Casa" : "Colegio");
        }

        return { 
          ...s, 
          isTracking: willBeTracking, 
          destination: willBeTracking ? destination : null,
          history: willBeTracking ? [] : s.history,
          routePath: willBeTracking ? s.routePath : [], // Reset path when done
          groundingUrls: willBeTracking ? s.groundingUrls : []
        };
      });
      return newState;
    });
  };

  const handleSetLocationPoint = (childId: string, type: 'home' | 'school', coord: Coordinate) => {
    setLocationStates(prev => prev.map(s => s.childId === childId ? { ...s, [type === 'home' ? 'homeCoord' : 'schoolCoord']: coord } : s));
  };

  const handleAddChild = (name: string, grade: GradeLevel, avatar: string) => {
    const id = crypto.randomUUID();
    const newChild: Child = { id, name, avatar, points: 0, grade };
    setChildren([...children, newChild]);
    const newLoc: LocationState = { 
      childId: id, isTracking: false, currentCoord: null, history: [], 
      homeCoord: null, schoolCoord: null, safeRadius: 100, 
      routePath: [], destination: null, groundingUrls: [] 
    };
    setLocationStates([...locationStates, newLoc]);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    sessionStorage.removeItem('eduamigo_auth');
    setUserRole(null);
    setActiveChildId(null);
  };

  if (!isAuthenticated) return <AuthScreen onAuthenticated={() => { setIsAuthenticated(true); sessionStorage.setItem('eduamigo_auth', 'true'); }} onDemo={() => setIsAuthenticated(true)} />;
  if (!userRole) return <Login onLogin={setUserRole} onLogout={handleLogout} />;

  if (viewMode !== 'parent' && !activeChildId) {
    return (
      <div className="min-h-screen bg-[#f0f9ff] p-8 flex flex-col items-center justify-center">
        <ChildSelector children={children} onSelect={(c) => setActiveChildId(c.id)} onAddChild={() => setViewMode('parent')} />
        <button onClick={handleLogout} className="mt-8 text-blue-400 font-bold hover:underline">Cerrar Sesión</button>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#f0f9ff]">
      {showAuthModal && <ParentAuthModal onResult={(s) => { setIsParentUnlocked(s); if(s) setViewMode('parent'); setShowAuthModal(false); }} onCancel={() => setShowAuthModal(false)} />}
      {showSOSModal && <SOSModal onSelect={(c) => { }} onClose={() => setShowSOSModal(false)} />}
      {showRequestForm && <StudentRequestForm onSend={handleAddRequest} onClose={() => setShowRequestForm(false)} />}
      {showStudentEventForm && <StudentEventForm onAdd={handleStudentAddEvent} onClose={() => setShowStudentEventForm(false)} />}

      <aside className="hidden md:flex w-80 bg-white border-r border-blue-100 p-6 flex-col h-screen sticky top-0">
        <div className="flex-1 overflow-y-auto no-scrollbar">
          <HistorySidebar history={history.filter(h => h.childId === activeChildId)} onSelect={(item) => { setViewMode('student'); }} />
        </div>
      </aside>

      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8 relative">
        <Header viewMode={viewMode} setViewMode={(m) => m === 'parent' && !isParentUnlocked ? setShowAuthModal(true) : setViewMode(m)} userRole={userRole} activeChild={activeChild} />

        {viewMode === 'student' && (
          <div className="fixed bottom-24 right-6 md:bottom-10 md:right-10 flex flex-col gap-3 z-50">
            <button onClick={() => setShowStudentEventForm(true)} className="w-16 h-16 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center text-3xl hover:scale-110 transition-transform" title="Agendar Evento 📅">📅</button>
            <button onClick={() => setShowRequestForm(true)} className="w-16 h-16 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center text-3xl hover:scale-110 transition-transform animate-bounce" title="Solicitar algo ✨">✨</button>
          </div>
        )}

        <div className="mt-8">
          {viewMode === 'student' && activeChild && (
            <StudentInquiry childName={activeChild.name} grade={activeChild.grade} region={region} onSuccess={handleInquirySuccess} onSOS={() => setShowSOSModal(true)} />
          )}
          {viewMode === 'location' && (
            <LocationHub viewMode="student" child={activeChild} locationStates={locationStates} onToggleTracking={handleToggleTracking} onSetPoint={handleSetLocationPoint} />
          )}
          {viewMode === 'parent' && (
            <ParentDashboard 
              history={history} examHistory={examHistory} children={children} rewards={rewards} events={events} tasks={tasks} requests={requests}
              communications={schoolComms} quickNotes={quickNotes} locationStates={locationStates}
              onSelectItem={() => {}} onAddChild={handleAddChild} onUpdateRewards={setRewards} onAddEvent={(e) => setEvents([...events, {...e, id: crypto.randomUUID(), notified: false}])} onDeleteEvent={(id) => setEvents(events.filter(e => e.id !== id))}
              onAddTask={(t) => setTasks([...tasks, {...t, id: crypto.randomUUID()}])} onToggleTask={(id) => setTasks(tasks.map(t => t.id === id ? {...t, completed: !t.completed} : t))} onDeleteTask={(id) => setTasks(tasks.filter(t => t.id !== id))}
              onApproveRequest={handleApproveRequest} onRejectRequest={(id) => setRequests(requests.map(r => r.id === id ? { ...r, status: 'rejected' } : r))} onUpdateTask={(id, up) => setTasks(tasks.map(t => t.id === id ? {...t, ...up} : t))}
              onAddQuickNote={(n) => setQuickNotes([{...n, id: crypto.randomUUID(), timestamp: Date.now()}, ...quickNotes])} onDeleteQuickNote={(id) => setQuickNotes(quickNotes.filter(q => q.id !== id))} onSyncSchoolComms={() => {}} onMarkCommRead={(id) => setSchoolComms(schoolComms.map(c => c.id === id ? {...c, isRead: true} : c))}
              onToggleTracking={handleToggleTracking} onSetLocationPoint={handleSetLocationPoint}
            />
          )}
          {viewMode === 'library' && <LibraryBrowser region={region} grade={activeChild?.grade || '1º Primaria'} setGrade={() => {}} />}
          {viewMode === 'exam' && activeChild && (
            <ExamMode grade={activeChild.grade} subject={'Matemáticas'} region={region} childId={activeChild.id} onSaveResult={(res) => {
              setExamHistory([res, ...examHistory]); awardPoints(res.pointsEarned);
            }} />
          )}
          {viewMode === 'shop' && activeChild && <RewardsShop child={activeChild} rewards={rewards} />}
        </div>
      </main>
    </div>
  );
};

export default App;

export type GradeLevel = 
  | '1º Primaria' | '2º Primaria' | '3º Primaria' | '4º Primaria' | '5º Primaria' | '6º Primaria'
  | '1º ESO' | '2º ESO' | '3º ESO' | '4º ESO'
  | '1º Bachillerato' | '2º Bachillerato';

export type Subject = 
  | 'Matemáticas' | 'Ciencias Naturales' | 'Historia' | 'Lengua y Literatura' 
  | 'Inglés' | 'Geografía' | 'Física y Química' | 'Arte';

export type Region = 
  | 'Andalucía' | 'Aragón' | 'Asturias' | 'Baleares' | 'Canarias' | 'Cantabria' 
  | 'Castilla-La Mancha' | 'Castilla y León' | 'Cataluña' | 'Comunidad Valenciana' 
  | 'Extremadura' | 'Galicia' | 'Madrid' | 'Murcia' | 'Navarra' | 'País Vasco' | 'La Rio_ja';

export type Country = 
  | 'República Dominicana' | 'Colombia' | 'Perú' | 'Ecuador' | 'Argentina' | 'Bolivia' 
  | 'Chile' | 'Costa Rica' | 'Cuba' | 'El Salvador' | 'España' | 'Guatemala' 
  | 'Honduras' | 'México' | 'Nicaragua' | 'Panamá' | 'Paraguay' | 'Puerto Rico' 
  | 'Uruguay' | 'Venezuela';

export type ViewMode = 'student' | 'parent' | 'library' | 'exam' | 'shop' | 'location';
export type UserRole = 'student' | 'parent' | 'demo' | null;

export type EventType = 'exam' | 'meeting' | 'excursion' | 'support' | 'medical' | 'other';

export interface CalendarEvent {
  id: string;
  childId: string;
  title: string;
  date: string;
  type: EventType;
  description?: string;
  notified?: boolean;
}

export interface StudentRequest {
  id: string;
  childId: string;
  title: string;
  message: string;
  timestamp: number;
  status: 'pending' | 'approved' | 'rejected';
}

export interface Task {
  id: string;
  childId: string;
  title: string;
  dueDate: string;
  completed: boolean;
  priority: 'low' | 'medium' | 'high';
  fromRequestId?: string;
}

export type SchoolCommType = 'email' | 'circular' | 'interview' | 'warning';

export interface SchoolCommunication {
  id: string;
  childId: string;
  type: SchoolCommType;
  sender: string;
  subject: string;
  content: string;
  date: string;
  isImportant: boolean;
  isRead: boolean;
}

export interface QuickNote {
  id: string;
  childId: string;
  text: string;
  timestamp: number;
  source: string; // e.g., "Profe Mates", "Tutor", "WhatsApp"
}

// --- Location Types ---
export interface Coordinate {
  lat: number;
  lng: number;
}

export interface RoutePoint {
  coord: Coordinate;
  timestamp: number;
  status: 'normal' | 'home' | 'school' | 'deviation';
}

export interface LocationState {
  childId: string;
  isTracking: boolean;
  currentCoord: Coordinate | null;
  history: RoutePoint[];
  homeCoord: Coordinate | null;
  homeAddress?: string;
  schoolCoord: Coordinate | null;
  schoolAddress?: string;
  safeRadius: number; // in meters
  routePath: Coordinate[]; // Points obtained via Maps grounding
  destination: 'home' | 'school' | null;
  groundingUrls: string[];
}

export interface ExplanationResponse {
  explanation: string;
  examples: string[];
  funFact: string;
  isSOS?: boolean;
  country?: Country;
}

export interface SyllabusTopic {
  id: string;
  title: string;
  description: string;
  subtopics: string[];
}

export interface Exercise {
  id: string;
  question: string;
  options: string[];
  correctIndex: number;
  explanation: string;
}

export interface TopicDetail {
  title: string;
  content: string;
  keyPoints: string[];
  examples: string[];
  summary: string;
  exercises: Exercise[];
}

export interface HistoryItem {
  id: string;
  childId: string;
  grade: GradeLevel;
  subject: Subject;
  region: Region;
  question: string;
  answer: ExplanationResponse;
  timestamp: number;
}

export interface ExamResult {
  id: string;
  childId: string;
  grade: GradeLevel;
  subject: Subject;
  topic: string;
  score: number;
  totalQuestions: number;
  strengths: string[];
  weaknesses: string[];
  studyGuideContent: string;
  timestamp: number;
  pointsEarned: number;
}

export interface Reward {
  id: string;
  title: string;
  pointsCost: number;
  icon: string;
}

export interface Child {
  id: string;
  name: string;
  avatar: string;
  points: number;
  grade: GradeLevel;
  country?: Country;
}

import React, { useState, useEffect, useRef } from 'react';
import { GradeLevel, Subject, ExplanationResponse, HistoryItem, ViewMode, UserRole, Region, ExamResult, Child, Reward, Country, CalendarEvent, Task, StudentRequest, EventType, SchoolCommunication, QuickNote, LocationState, Coordinate, RoutePoint } from './types';
import { requestNotificationPermission, checkUpcomingEvents, sendLocalNotification } from './services/notificationService';
import { GoogleGenAI } from "@google/genai";
import Header from './components/Header';
import HistorySidebar from './components/HistorySidebar';
import ParentDashboard from './components/ParentDashboard';
import Login from './components/Login';
import AuthScreen from './components/AuthScreen';
import ParentAuthModal from './components/ParentAuthModal';
import LibraryBrowser from './components/LibraryBrowser';
import ExamMode from './components/ExamMode';
import ChildSelector from './components/ChildSelector';
import RewardsShop from './components/RewardsShop';
import SOSModal from './components/SOSModal';
import StudentRequestForm from './components/StudentRequestForm';
import StudentEventForm from './components/StudentEventForm';
import StudentInquiry from './components/StudentInquiry';
import LocationHub from './components/LocationHub';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState<UserRole>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('student');
  const [region, setRegion] = useState<Region>('Madrid');
  const [isParentUnlocked, setIsParentUnlocked] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [showSOSModal, setShowSOSModal] = useState(false);
  const [showRequestForm, setShowRequestForm] = useState(false);
  const [showStudentEventForm, setShowStudentEventForm] = useState(false);

  const [children, setChildren] = useState<Child[]>([]);
  const [activeChildId, setActiveChildId] = useState<string | null>(null);
  const [rewards, setRewards] = useState<Reward[]>([]);
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [requests, setRequests] = useState<StudentRequest[]>([]);
  const [schoolComms, setSchoolComms] = useState<SchoolCommunication[]>([]);
  const [quickNotes, setQuickNotes] = useState<QuickNote[]>([]);
  const [locationStates, setLocationStates] = useState<LocationState[]>([]);

  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [examHistory, setExamHistory] = useState<ExamResult[]>([]);

  const watchIdRef = useRef<number | null>(null);
  const activeChild = children.find(c => c.id === activeChildId) || null;

  useEffect(() => {
    const sessionAuth = sessionStorage.getItem('eduamigo_auth');
    if (sessionAuth) setIsAuthenticated(true);

    setRegion(localStorage.getItem('eduamigo_region') as Region || 'Madrid');
    setHistory(JSON.parse(localStorage.getItem('eduamigo_history') || '[]'));
    setExamHistory(JSON.parse(localStorage.getItem('eduamigo_exam_history') || '[]'));
    setChildren(JSON.parse(localStorage.getItem('eduamigo_children') || '[]'));
    setRewards(JSON.parse(localStorage.getItem('eduamigo_rewards') || '[]'));
    setEvents(JSON.parse(localStorage.getItem('eduamigo_events') || '[]'));
    setTasks(JSON.parse(localStorage.getItem('eduamigo_tasks') || '[]'));
    setRequests(JSON.parse(localStorage.getItem('eduamigo_requests') || '[]'));
    setSchoolComms(JSON.parse(localStorage.getItem('eduamigo_schoolComms') || '[]'));
    setQuickNotes(JSON.parse(localStorage.getItem('eduamigo_quickNotes') || '[]'));
    setLocationStates(JSON.parse(localStorage.getItem('eduamigo_locationStates') || '[]'));

    requestNotificationPermission();
  }, []);

  useEffect(() => {
    if (userRole && userRole !== 'demo') {
      const data = { history, examHistory, children, rewards, events, tasks, requests, schoolComms, quickNotes, locationStates };
      Object.entries(data).forEach(([key, val]) => localStorage.setItem(`eduamigo_${key}`, JSON.stringify(val)));
      localStorage.setItem('eduamigo_region', region);
    }
  }, [history, examHistory, children, rewards, events, tasks, requests, schoolComms, quickNotes, locationStates, userRole, region]);

  useEffect(() => {
    const isTrackingAny = locationStates.some(s => s.isTracking);
    const shouldWatch = viewMode === 'location' || isTrackingAny;

    if (shouldWatch && navigator.geolocation) {
      if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current);

      watchIdRef.current = navigator.geolocation.watchPosition(
        (pos) => {
          const newCoord: Coordinate = { lat: pos.coords.latitude, lng: pos.coords.longitude };
          if (activeChildId) {
            updateLocation(activeChildId, newCoord);
          }
        },
        (err) => console.error("Geolocation Error:", err),
        { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
      );
    } else {
      if (watchIdRef.current !== null) {
        navigator.geolocation.clearWatch(watchIdRef.current);
        watchIdRef.current = null;
      }
    }

    return () => {
      if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current);
    };
  }, [activeChildId, locationStates.some(s => s.isTracking), viewMode]);

  const searchAddressViaGemini = async (childId: string, address: string, type: 'home' | 'school') => {
    try {
      const prompt = `Usa Google Maps para encontrar la latitud y longitud exacta de esta dirección: "${address}". 
      Devuelve SOLO un JSON con este formato: {"lat": número, "lng": número, "full_address": "dirección normalizada"}`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
        }
      });

      const text = response.text || "";
      const match = text.match(/\{.*\}/s);
      if (match) {
        const data = JSON.parse(match[0]);
        handleSetLocationPoint(childId, type, { lat: data.lat, lng: data.lng }, data.full_address);
        return data.full_address;
      }
    } catch (e) {
      console.error("Error geocoding address:", e);
      alert("No se pudo encontrar la dirección. Intenta ser más específico (Calle, Número, Ciudad).");
    }
    return null;
  };

  const reverseGeocodeViaGemini = async (childId: string, coord: Coordinate, type: 'home' | 'school') => {
    try {
      const prompt = `Usa Google Maps para identificar la dirección postal de estas coordenadas: [Lat: ${coord.lat}, Lng: ${coord.lng}]. 
      Devuelve SOLO el nombre de la calle y el número, o el nombre del lugar si es un centro público.`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
        }
      });

      const address = response.text?.trim() || "Ubicación Guardada";
      handleSetLocationPoint(childId, type, coord, address);
      return address;
    } catch (e) {
      handleSetLocationPoint(childId, type, coord, "Ubicación GPS");
      return "Ubicación GPS";
    }
  };

  const fetchRouteViaGemini = async (childId: string, origin: Coordinate, destination: Coordinate, destinationName: string) => {
    try {
      const prompt = `Actúa como un experto en navegación. Usando Google Maps, encuentra la mejor ruta a pie desde [Lat: ${origin.lat}, Lng: ${origin.lng}] hasta [Lat: ${destination.lat}, Lng: ${destination.lng}] (que es ${destinationName}). 
      Proporciona una lista de al menos 15 coordenadas intermedias (latitud, longitud) que sigan las calles reales paso a paso. 
      Devuelve los puntos en este formato estricto: "PUNTO: LAT, LNG".`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
          toolConfig: {
            retrievalConfig: {
              latLng: { latitude: origin.lat, longitude: origin.lng }
            }
          }
        }
      });

      const text = response.text || "";
      const urls = response.candidates?.[0]?.groundingMetadata?.groundingChunks
        ?.map(c => c.maps?.uri || "")
        .filter(u => u !== "") || [];

      const regex = /PUNTO:\s*(-?\d+\.\d+)\s*,\s*(-?\d+\.\d+)/g;
      const points: Coordinate[] = [];
      let match;
      while ((match = regex.exec(text)) !== null) {
        points.push({ lat: parseFloat(match[1]), lng: parseFloat(match[2]) });
      }

      if (points.length > 0) {
        setLocationStates(prev => prev.map(s => 
          s.childId === childId ? { ...s, routePath: points, groundingUrls: urls } : s
        ));
      }
    } catch (e) {
      console.error("Error fetching Maps route:", e);
    }
  };

  const updateLocation = (childId: string, coord: Coordinate) => {
    setLocationStates(prev => prev.map(s => {
      if (s.childId !== childId) return s;

      const newPoint: RoutePoint = { coord, timestamp: Date.now(), status: 'normal' };

      if (s.homeCoord && getDist(coord, s.homeCoord) < s.safeRadius) {
         if (s.history.length > 0 && s.history[s.history.length-1].status !== 'home') {
           sendLocalNotification("🏠 ¡A casa!", "Tu hijo/a ha llegado a CASA correctamente.");
         }
         newPoint.status = 'home';
      } else if (s.schoolCoord && getDist(coord, s.schoolCoord) < s.safeRadius) {
        if (s.history.length > 0 && s.history[s.history.length-1].status !== 'school') {
          sendLocalNotification("🏫 ¡Llegada al cole!", "Tu hijo/a ha llegado al COLEGIO correctamente.");
        }
        newPoint.status = 'school';
      } else if (s.routePath.length > 0 && s.isTracking) {
        const minDistToRoute = Math.min(...s.routePath.map(p => getDist(coord, p)));
        if (minDistToRoute > 300) { 
           newPoint.status = 'deviation';
           sendLocalNotification("⚠️ ¡Fuera de Ruta!", "Se ha detectado una desviación de más de 300 metros de la ruta de Google Maps.", "🚩");
        }
      }

      return { 
        ...s, 
        currentCoord: coord, 
        history: s.isTracking ? [...s.history, newPoint].slice(-100) : s.history 
      };
    }));
  };

  const getDist = (c1: Coordinate, c2: Coordinate) => {
    const R = 6371e3; 
    const φ1 = c1.lat * Math.PI/180;
    const φ2 = c2.lat * Math.PI/180;
    const Δφ = (c2.lat-c1.lat) * Math.PI/180;
    const Δλ = (c2.lng-c1.lng) * Math.PI/180;
    const a = Math.sin(Δφ/2) * Math.sin(Δφ/2) + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ/2) * Math.sin(Δλ/2);
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  };

  const awardPoints = (points: number) => {
    if (!activeChildId) return;
    setChildren(prev => prev.map(c => 
      c.id === activeChildId ? { ...c, points: c.points + points } : c
    ));
  };

  const handleInquirySuccess = (question: string, subject: Subject, answer: ExplanationResponse) => {
    if (!activeChildId || !activeChild) return;
    const newItem: HistoryItem = {
      id: crypto.randomUUID(),
      childId: activeChildId,
      grade: activeChild.grade,
      subject,
      region,
      question,
      answer,
      timestamp: Date.now()
    };
    setHistory(prev => [newItem, ...prev].slice(0, 20));
    awardPoints(5);
  };

  const handleAddRequest = (title: string, message: string) => {
    if (!activeChildId) return;
    const newRequest: StudentRequest = {
      id: crypto.randomUUID(),
      childId: activeChildId,
      title,
      message,
      timestamp: Date.now(),
      status: 'pending'
    };
    setRequests(prev => [...prev, newRequest]);
    setShowRequestForm(false);
  };

  const handleStudentAddEvent = (title: string, date: string, type: EventType) => {
    if (!activeChildId) return;
    const newEvent: CalendarEvent = {
      id: crypto.randomUUID(),
      childId: activeChildId,
      title,
      date,
      type,
      notified: false
    };
    setEvents(prev => [...prev, newEvent]);
    awardPoints(20);
    setShowStudentEventForm(false);
  };

  const handleApproveRequest = (requestId: string, dueDate: string) => {
    const request = requests.find(r => r.id === requestId);
    if (!request) return;

    const newTask: Task = {
      id: crypto.randomUUID(),
      childId: request.childId,
      title: request.title,
      dueDate,
      completed: false,
      priority: 'medium',
      fromRequestId: requestId
    };

    setTasks(prev => [...prev, newTask]);
    setRequests(prev => prev.map(r => r.id === requestId ? { ...r, status: 'approved' } : r));
  };

  const handleToggleTracking = (childId: string) => {
    setLocationStates(prev => {
      const newState = prev.map(s => {
        if (s.childId !== childId) return s;
        const willBeTracking = !s.isTracking;

        let destination: 'home' | 'school' | null = s.destination;
        if (willBeTracking && s.currentCoord && s.homeCoord && s.schoolCoord) {
          const distToHome = getDist(s.currentCoord, s.homeCoord);
          const distToSchool = getDist(s.currentCoord, s.schoolCoord);
          destination = distToHome < distToSchool ? 'school' : 'home';

          const targetCoord = destination === 'home' ? s.homeCoord : s.schoolCoord;
          fetchRouteViaGemini(childId, s.currentCoord, targetCoord, destination === 'home' ? "Casa" : "Colegio");
        }

        return { 
          ...s, 
          isTracking: willBeTracking, 
          destination: willBeTracking ? destination : null,
          history: willBeTracking ? [] : s.history,
          routePath: willBeTracking ? s.routePath : [],
          groundingUrls: willBeTracking ? s.groundingUrls : []
        };
      });
      return newState;
    });
  };

  const handleSetLocationPoint = (childId: string, type: 'home' | 'school', coord: Coordinate, address?: string) => {
    setLocationStates(prev => prev.map(s => s.childId === childId ? { 
      ...s, 
      [type === 'home' ? 'homeCoord' : 'schoolCoord']: coord,
      [type === 'home' ? 'homeAddress' : 'schoolAddress']: address
    } : s));
  };

  const handleAddChild = (name: string, grade: GradeLevel, avatar: string) => {
    const id = crypto.randomUUID();
    const newChild: Child = { id, name, avatar, points: 0, grade };
    setChildren([...children, newChild]);
    const newLoc: LocationState = { 
      childId: id, isTracking: false, currentCoord: null, history: [], 
      homeCoord: null, schoolCoord: null, safeRadius: 100, 
      routePath: [], destination: null, groundingUrls: [] 
    };
    setLocationStates([...locationStates, newLoc]);
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    sessionStorage.removeItem('eduamigo_auth');
    setUserRole(null);
    setActiveChildId(null);
  };

  if (!isAuthenticated) return <AuthScreen onAuthenticated={() => { setIsAuthenticated(true); sessionStorage.setItem('eduamigo_auth', 'true'); }} onDemo={() => setIsAuthenticated(true)} />;
  if (!userRole) return <Login onLogin={setUserRole} onLogout={handleLogout} />;

  if (viewMode !== 'parent' && !activeChildId) {
    return (
      <div className="min-h-screen bg-[#f0f9ff] p-8 flex flex-col items-center justify-center">
        <ChildSelector children={children} onSelect={(c) => setActiveChildId(c.id)} onAddChild={() => setViewMode('parent')} />
        <button onClick={handleLogout} className="mt-8 text-blue-400 font-bold hover:underline">Cerrar Sesión</button>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#f0f9ff]">
      {showAuthModal && <ParentAuthModal onResult={(s) => { setIsParentUnlocked(s); if(s) setViewMode('parent'); setShowAuthModal(false); }} onCancel={() => setShowAuthModal(false)} />}
      {showSOSModal && <SOSModal onSelect={(c) => { }} onClose={() => setShowSOSModal(false)} />}
      {showRequestForm && <StudentRequestForm onSend={handleAddRequest} onClose={() => setShowRequestForm(false)} />}
      {showStudentEventForm && <StudentEventForm onAdd={handleStudentAddEvent} onClose={() => setShowStudentEventForm(false)} />}

      <aside className="hidden md:flex w-80 bg-white border-r border-blue-100 p-6 flex-col h-screen sticky top-0">
        <div className="flex-1 overflow-y-auto no-scrollbar">
          <HistorySidebar history={history.filter(h => h.childId === activeChildId)} onSelect={(item) => { setViewMode('student'); }} />
        </div>
      </aside>

      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 md:pb-8 relative">
        <Header viewMode={viewMode} setViewMode={(m) => m === 'parent' && !isParentUnlocked ? setShowAuthModal(true) : setViewMode(m)} userRole={userRole} activeChild={activeChild} />

        {viewMode === 'student' && (
          <div className="fixed bottom-24 right-6 md:bottom-10 md:right-10 flex flex-col gap-3 z-50">
            <button onClick={() => setShowStudentEventForm(true)} className="w-16 h-16 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center text-3xl hover:scale-110 transition-transform" title="Agendar Evento 📅">📅</button>
            <button onClick={() => setShowRequestForm(true)} className="w-16 h-16 bg-blue-600 text-white rounded-full shadow-2xl flex items-center justify-center text-3xl hover:scale-110 transition-transform animate-bounce" title="Solicitar algo ✨">✨</button>
          </div>
        )}

        <div className="mt-8">
          {viewMode === 'student' && activeChild && (
            <StudentInquiry childName={activeChild.name} grade={activeChild.grade} region={region} onSuccess={handleInquirySuccess} onSOS={() => setShowSOSModal(true)} />
          )}
          {viewMode === 'location' && (
            <LocationHub 
              viewMode="student" 
              child={activeChild} 
              locationStates={locationStates} 
              onToggleTracking={handleToggleTracking} 
              onSetPoint={handleSetLocationPoint} 
              onSearchAddress={searchAddressViaGemini}
              onReverseGeocode={reverseGeocodeViaGemini}
            />
          )}
          {viewMode === 'parent' && (
            <ParentDashboard 
              history={history} examHistory={examHistory} children={children} rewards={rewards} events={events} tasks={tasks} requests={requests}
              communications={schoolComms} quickNotes={quickNotes} locationStates={locationStates}
              onSelectItem={() => {}} onAddChild={handleAddChild} onUpdateRewards={setRewards} onAddEvent={(e) => setEvents([...events, {...e, id: crypto.randomUUID(), notified: false}])} onDeleteEvent={(id) => setEvents(events.filter(e => e.id !== id))}
              onAddTask={(t) => setTasks([...tasks, {...t, id: crypto.randomUUID()}])} onToggleTask={(id) => setTasks(tasks.map(t => t.id === id ? {...t, completed: !t.completed} : t))} onDeleteTask={(id) => setTasks(tasks.filter(t => t.id !== id))}
              onApproveRequest={handleApproveRequest} onRejectRequest={(id) => setRequests(requests.map(r => r.id === id ? { ...r, status: 'rejected' } : r))} onUpdateTask={(id, up) => setTasks(tasks.map(t => t.id === id ? {...t, ...up} : t))}
              onAddQuickNote={(n) => setQuickNotes([{...n, id: crypto.randomUUID(), timestamp: Date.now()}, ...quickNotes])} onDeleteQuickNote={(id) => setQuickNotes(quickNotes.filter(q => q.id !== id))} onSyncSchoolComms={() => {}} onMarkCommRead={(id) => setSchoolComms(schoolComms.map(c => c.id === id ? {...c, isRead: true} : c))}
              onToggleTracking={handleToggleTracking} 
              onSetLocationPoint={handleSetLocationPoint}
              onSearchAddress={searchAddressViaGemini}
              onReverseGeocode={reverseGeocodeViaGemini}
            />
          )}
          {viewMode === 'library' && <LibraryBrowser region={region} grade={activeChild?.grade || '1º Primaria'} setGrade={() => {}} />}
          {viewMode === 'exam' && activeChild && (
            <ExamMode grade={activeChild.grade} subject={'Matemáticas'} region={region} childId={activeChild.id} onSaveResult={(res) => {
              setExamHistory([res, ...examHistory]); awardPoints(res.pointsEarned);
            }} />
          )}
          {viewMode === 'shop' && activeChild && <RewardsShop child={activeChild} rewards={rewards} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { HistoryItem, ExamResult, Child, Reward, GradeLevel, CalendarEvent, Task, StudentRequest, SchoolCommunication, QuickNote, LocationState, Coordinate } from '../types';
import AgendaManager from './AgendaManager';
import RequestManager from './RequestManager';
import SchoolHub from './SchoolHub';
import ChildManager from './ChildManager';
import RewardManager from './RewardManager';
import LocationHub from './LocationHub';

interface ParentDashboardProps {
  history: HistoryItem[];
  examHistory: ExamResult[];
  children: Child[];
  rewards: Reward[];
  events: CalendarEvent[];
  tasks: Task[];
  requests: StudentRequest[];
  communications: SchoolCommunication[];
  quickNotes: QuickNote[];
  locationStates: LocationState[];
  onSelectItem: (item: HistoryItem) => void;
  onAddChild: (name: string, grade: GradeLevel, avatar: string) => void;
  onUpdateRewards: (rewards: Reward[]) => void;
  onAddEvent: (event: Omit<CalendarEvent, 'id'>) => void;
  onDeleteEvent: (id: string) => void;
  onAddTask: (task: Omit<Task, 'id'>) => void;
  onToggleTask: (id: string) => void;
  onDeleteTask: (id: string) => void;
  onApproveRequest: (requestId: string, dueDate: string) => void;
  onRejectRequest: (requestId: string) => void;
  onUpdateTask: (taskId: string, updates: Partial<Task>) => void;
  onAddQuickNote: (note: Omit<QuickNote, 'id' | 'timestamp'>) => void;
  onDeleteQuickNote: (id: string) => void;
  onSyncSchoolComms: () => void;
  onMarkCommRead: (id: string) => void;
  onToggleTracking: (id: string) => void;
  onSetLocationPoint: (id: string, type: 'home' | 'school', coord: Coordinate, address?: string) => void;
  onSearchAddress: (childId: string, address: string, type: 'home' | 'school') => Promise<string | null>;
  onReverseGeocode: (childId: string, coord: Coordinate, type: 'home' | 'school') => Promise<string>;
}

const ParentDashboard: React.FC<ParentDashboardProps> = ({ 
  history, examHistory, children, rewards, events, tasks, requests, communications, quickNotes, locationStates,
  onSelectItem, onAddChild, onUpdateRewards, onAddEvent, onDeleteEvent, onAddTask, onToggleTask, onDeleteTask,
  onApproveRequest, onRejectRequest, onUpdateTask, onAddQuickNote, onDeleteQuickNote, onSyncSchoolComms, onMarkCommRead,
  onToggleTracking, onSetLocationPoint, onSearchAddress, onReverseGeocode
}) => {
  const [activeTab, setActiveTab] = useState<'stats' | 'children' | 'rewards' | 'agenda' | 'inbox' | 'school' | 'location'>('stats');

  const pendingRequestsCount = requests.filter(r => r.status === 'pending').length;
  const unreadCommsCount = communications.filter(c => !c.isRead).length;
  const activeTrackingCount = locationStates.filter(s => s.isTracking).length;

  return (
    <div className="space-y-8 pb-10 animate-in fade-in duration-500">
      <div className="flex flex-wrap gap-2 p-1 bg-blue-100 rounded-2xl w-fit">
        <button onClick={() => setActiveTab('stats')} className={`px-4 md:px-6 py-2 rounded-xl text-xs font-black transition-all ${activeTab === 'stats' ? 'bg-white text-blue-600 shadow-sm' : 'text-blue-500'}`}>📊 Stats</button>
        <button onClick={() => setActiveTab('school')} className={`relative px-4 md:px-6 py-2 rounded-xl text-xs font-black transition-all ${activeTab === 'school' ? 'bg-white text-indigo-600 shadow-sm' : 'text-indigo-500'}`}>
          🏫 Escuela
          {unreadCommsCount > 0 && <span className="absolute -top-1 -right-1 bg-indigo-600 text-white text-[8px] w-4 h-4 rounded-full flex items-center justify-center font-black">{unreadCommsCount}</span>}
        </button>
        <button onClick={() => setActiveTab('location')} className={`relative px-4 md:px-6 py-2 rounded-xl text-xs font-black transition-all ${activeTab === 'location' ? 'bg-white text-indigo-600 shadow-sm' : 'text-indigo-500'}`}>
          🚶 Rutas
          {activeTrackingCount > 0 && <span className="absolute -top-1 -right-1 bg-green-500 text-white text-[8px] w-4 h-4 rounded-full flex items-center justify-center font-black animate-pulse">●</span>}
        </button>
        <button onClick={() => setActiveTab('inbox')} className={`relative px-4 md:px-6 py-2 rounded-xl text-xs font-black transition-all ${activeTab === 'inbox' ? 'bg-white text-blue-600 shadow-sm' : 'text-blue-500'}`}>
          📥 Peticiones
