        <button onClick={() => setActiveTab('rewards')} className={`px-4 md:px-6 py-2 rounded-xl text-xs font-black transition-all ${activeTab === 'rewards' ? 'bg-white text-blue-600 shadow-sm' : 'text-blue-500'}`}>🎁 Premios</button>
