            <div className="bg-indigo-600 p-8 rounded-[2rem] shadow-xl text-white">
              <p className="text-indigo-100 text-[10px] font-black uppercase mb-1">Exámenes</p>
              <p className="text-4xl font-black">{examHistory.length}</p>
