      {activeTab === 'location' && (
        <LocationHub 
          viewMode="parent" 
          child={null} 
          locationStates={locationStates} 
          onToggleTracking={onToggleTracking} 
          onSetPoint={onSetLocationPoint}
          onSearchAddress={onSearchAddress}
          onReverseGeocode={onReverseGeocode}
        />
      )}

      {activeTab === 'school' && (
        <SchoolHub 
          children={children} 
          communications={communications} 
          quickNotes={quickNotes}
          onAddNote={onAddQuickNote}
          onDeleteNote={onDeleteQuickNote}
          onSyncEmails={onSyncSchoolComms}
          onMarkRead={onMarkCommRead}
        />
      )}

      {activeTab === 'inbox' && (
        <RequestManager 
          requests={requests} 
          tasks={tasks} 
          children={children} 
          onApprove={onApproveRequest} 
          onReject={onRejectRequest} 
          onUpdateTask={onUpdateTask} 
          onDeleteTask={onDeleteTask} 
        />
      )}

      {activeTab === 'agenda' && (
        <AgendaManager 
          children={children} 
          events={events} 
          tasks={tasks}
          onAddEvent={onAddEvent}
          onDeleteEvent={onDeleteEvent}
          onAddTask={onAddTask}
          onToggleTask={onToggleTask}
          onDeleteTask={onDeleteTask}
        />
      )}

      {activeTab === 'children' && (
        <ChildManager 
          children={children} 
          onAddChild={onAddChild} 
        />
      )}

      {activeTab === 'rewards' && (
        <RewardManager 
          rewards={rewards} 
          onUpdateRewards={onUpdateRewards} 
        />
      )}
    </div>
  );
};

