export const analyzeExamResults = async (grade: GradeLevel, subject: Subject, topic: string, questions: Exercise[], answers: number[]): Promise<Partial<ExamResult>> => {
  try {
    const score = answers.filter((ans, idx) => ans === questions[idx].correctIndex).length;
    const performanceData = questions.map((q, idx) => ({
      question: q.question,
      correct: answers[idx] === q.correctIndex,
      explanation: q.explanation
    }));

    return await executeWithRetry(async () => {
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Analiza este resultado de examen de ${grade}: ${JSON.stringify(performanceData)} sobre ${topic}.`,
        config: {
          thinkingConfig: { thinkingBudget: 0 },
          systemInstruction: `Como tutor pedagógico, identifica 3 fortalezas y 3 debilidades basadas en los fallos. 
          Genera también una guía de estudio descargable con explicaciones breves de los puntos fallados. Formato JSON.`,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              strengths: { type: Type.ARRAY, items: { type: Type.STRING } },
              weaknesses: { type: Type.ARRAY, items: { type: Type.STRING } },
              studyGuideContent: { type: Type.STRING, description: "Markdown text for a reinforcement document" },
            },
            required: ["strengths", "weaknesses", "studyGuideContent"],
          },
        },
      });
      const analysis = JSON.parse(response.text || '{}');
      return { ...analysis, score, totalQuestions: questions.length };
    });
  } catch (e) {
    return { strengths: ["No analizado"], weaknesses: ["Revisar manualmente"], studyGuideContent: "Error en el análisis automático." };
  }
};

export const generateSpeech = async (text: string): Promise<void> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
      },
    });
    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!base64Audio) return;
    const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const buffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.start();
  } catch (e) { console.error("TTS error", e); }
};

function decode(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
}

async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
  }
  return buffer;
}

import React, { useRef, useState } from 'react';
import { analyzeWorksheet } from '../services/geminiService';
import { GradeLevel } from '../types';

interface VisionTutorProps {
  grade: GradeLevel;
}

const VisionTutor: React.FC<VisionTutorProps> = ({ grade }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [analysis, setAnalysis] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setIsCameraActive(true);
      }
    } catch (err) {
      alert("No se pudo acceder a la cámara.");
    }
  };

  const captureAndAnalyze = async () => {
    if (!canvasRef.current || !videoRef.current) return;
    setLoading(true);
    const ctx = canvasRef.current.getContext('2d');
    canvasRef.current.width = videoRef.current.videoWidth;
    canvasRef.current.height = videoRef.current.videoHeight;
    ctx?.drawImage(videoRef.current, 0, 0);

    const dataUrl = canvasRef.current.toDataURL('image/jpeg');
    const result = await analyzeWorksheet(dataUrl, grade);
    setAnalysis(result);
    setLoading(false);

    // Stop camera
    const stream = videoRef.current.srcObject as MediaStream;
    stream.getTracks().forEach(track => track.stop());
    setIsCameraActive(false);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="bg-white p-8 rounded-[2.5rem] shadow-xl border-2 border-blue-100">
        <h2 className="text-2xl font-black text-blue-900 mb-2 flex items-center gap-2">
          📸 Tutor Visual
        </h2>
        <p className="text-blue-500 font-bold text-sm mb-6">Saca una foto a tus deberes y te los explicaré.</p>

        {isCameraActive ? (
          <div className="relative rounded-3xl overflow-hidden bg-black aspect-video">
            <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
            <button 
              onClick={captureAndAnalyze}
              disabled={loading}
              className="absolute bottom-6 left-1/2 -translate-x-1/2 bg-blue-600 text-white px-8 py-3 rounded-2xl font-black shadow-2xl hover:bg-blue-700 transition-all"
            >
              {loading ? 'Analizando...' : 'Capturar y Analizar 📸'}
            </button>
          </div>
        ) : (
          <div className="space-y-6">
            {!analysis && (
              <button 
                onClick={startCamera}
                className="w-full py-16 border-4 border-dashed border-blue-100 rounded-[2rem] text-blue-300 font-black text-xl hover:border-blue-400 hover:text-blue-500 transition-all flex flex-col items-center gap-4"
              >
                <span className="text-6xl">📷</span>
                Activar Cámara para Escanear
              </button>
            )}

            {analysis && (
              <div className="bg-blue-50 p-8 rounded-[2rem] border border-blue-100 animate-in slide-in-from-bottom-4">
                <div className="flex justify-between items-start mb-4">
                  <h3 className="font-black text-blue-900">Análisis del Ejercicio</h3>
                  <button onClick={() => setAnalysis(null)} className="text-blue-400 font-bold text-xs uppercase">Borrar</button>
                </div>
                <div className="prose prose-blue text-blue-800 whitespace-pre-wrap leading-relaxed">
                  {analysis}
                </div>
                <button 
                  onClick={startCamera}
                  className="mt-6 w-full bg-blue-600 text-white py-4 rounded-2xl font-black shadow-lg"
                >
                  Escanear otro ejercicio 📸
                </button>
              </div>
            )}
          </div>
        )}
      </div>
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default VisionTutor;

import React, { useState, useEffect, useRef } from 'react';
import { GradeLevel, Subject, Region, ChatTurn } from '../types';
import { getChatExplanation } from '../services/geminiService';

interface ChatInterfaceProps {
  grade: GradeLevel;
  subject: Subject;
  region: Region;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ grade, subject, region }) => {
  const [history, setHistory] = useState<ChatTurn[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [isSocratic, setIsSocratic] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [history]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || loading) return;

    const userTurn: ChatTurn = { role: 'user', parts: [{ text: input }] };
    const newHistory = [...history, userTurn];
    setHistory(newHistory);
    setInput('');
    setLoading(true);

    try {
      const responseText = await getChatExplanation(grade, subject, newHistory, region, isSocratic);
      setHistory([...newHistory, { role: 'model', parts: [{ text: responseText }] }]);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-[2.5rem] shadow-xl border-2 border-blue-100 flex flex-col h-[600px] overflow-hidden">
      <div className="p-6 border-b border-blue-50 flex justify-between items-center bg-blue-50/50">
        <div>
          <h2 className="text-xl font-black text-blue-900">Chat Interactivo ✨</h2>
          <p className="text-[10px] font-bold text-blue-400 uppercase tracking-widest">{subject} • {grade}</p>
        </div>
        <button 
          onClick={() => setIsSocratic(!isSocratic)}
          className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all ${isSocratic ? 'bg-indigo-600 text-white shadow-md' : 'bg-white text-indigo-400 border border-indigo-100'}`}
        >
          {isSocratic ? '🧠 MODO SOCRÁTICO ACTIVO' : '🧠 ACTIVAR MODO SOCRÁTICO'}
        </button>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-4 no-scrollbar">
        {history.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center text-center opacity-40">
            <span className="text-6xl mb-4">💬</span>
            <p className="font-bold text-blue-900">Pregúntame lo que quieras sobre {subject}.<br/>Recuerdo lo que hablamos en este chat.</p>
          </div>
        )}
        {history.map((turn, i) => (
          <div key={i} className={`flex ${turn.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-4 rounded-3xl font-medium text-sm leading-relaxed ${
              turn.role === 'user' 
              ? 'bg-blue-600 text-white rounded-tr-none' 
              : 'bg-blue-50 text-blue-900 rounded-tl-none border border-blue-100'
            }`}>
              {turn.parts[0].text}
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex justify-start">
            <div className="bg-blue-50 p-4 rounded-3xl rounded-tl-none animate-pulse text-blue-400 font-black text-xs">
              Escribiendo...
            </div>
          </div>
        )}
      </div>

      <form onSubmit={handleSubmit} className="p-6 bg-gray-50 border-t border-blue-50 flex gap-3">
        <input 
          value={input}
          onChange={e => setInput(e.target.value)}
          placeholder="Dime más sobre esto..."
          className="flex-1 bg-white p-4 rounded-2xl text-sm font-bold outline-none border-2 border-transparent focus:border-blue-500 shadow-sm"
        />
        <button 
          type="submit"
          disabled={loading || !input.trim()}
          className="bg-blue-600 text-white px-6 py-4 rounded-2xl font-black shadow-lg hover:bg-blue-700 disabled:opacity-50 transition-all"
        >
          →
        </button>
      </form>
    </div>
  );
};

export default ChatInterface;

