}

export interface Reward {
  id: string;
  title: string;
  pointsCost: number;
  icon: string;
}

export interface Child {
  id: string;
  name: string;
  avatar: string;
  points: number;
  grade: GradeLevel;
  country?: Country;
  badges: string[]; // ids of unlocked badges
  streak: Streak;
