export default ParentAuthModal;

import { UserRole } from '../types';

export interface AuthResponse {
  userId: string;
  email: string;
  pin: string;
  error?: string;
}

export const authService = {
  async register(email: string, password: string, parentPin: string): Promise<AuthResponse> {
    try {
      const response = await fetch('auth.php?action=register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password, parentPin })
      });
      return await response.json();
    } catch (err) {
      return { userId: '', email: '', pin: '', error: 'Error de conexión con el servidor backend.' };
    }
  },

  async login(email: string, password: string): Promise<AuthResponse> {
    try {
      const response = await fetch('auth.php?action=login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      return await response.json();
    } catch (err) {
      return { userId: '', email: '', pin: '', error: 'Error de conexión con el servidor backend.' };
    }
  },

  async updatePin(userId: string, newPin: string): Promise<{ success: boolean; error?: string }> {
    try {
      const response = await fetch('auth.php?action=update_pin', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId, newPin })
      });
      const data = await response.json();
      return { success: data.status === 'success', error: data.error };
    } catch (err) {
      return { success: false, error: 'Error de conexión.' };
    }
  }
};

import React, { useState } from 'react';
import { authService } from '../services/authService';

interface AuthScreenProps {
  onAuthenticated: (userId: string, email: string, pin: string) => void;
  onDemo: () => void;
}

const AuthScreen: React.FC<AuthScreenProps> = ({ onAuthenticated, onDemo }) => {
  const [isRegister, setIsRegister] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [parentPin, setParentPin] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (isRegister && parentPin.length !== 4) {
      setError('El PIN parental debe ser de 4 dígitos.');
      setLoading(false);
      return;
    }

    try {
      const data = isRegister 
        ? await authService.register(email, password, parentPin)
        : await authService.login(email, password);

      if (data.error) {
        setError(data.error);
      } else if (data.userId) {
        onAuthenticated(data.userId, data.email, data.pin);
      }
    } catch (err) {
      setError('Error inesperado. Verifica que auth.php existe en tu servidor.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-600 to-indigo-800 flex items-center justify-center p-6 overflow-hidden relative">
      <div className="absolute top-[-10%] right-[-10%] w-96 h-96 bg-white/10 rounded-full blur-3xl animate-pulse"></div>

      <div className="max-w-md w-full bg-white/95 backdrop-blur-xl rounded-[2.5rem] p-10 shadow-2xl border border-white/20 animate-in zoom-in duration-500">
        <div className="text-center mb-8">
          <div className="bg-blue-600 w-20 h-20 rounded-3xl shadow-xl flex items-center justify-center mx-auto mb-6 transform -rotate-3">
              <span className="text-4xl">🎓</span>
          </div>
          <h1 className="text-3xl font-bold text-blue-900 tracking-tight mb-2">EduAmigo</h1>
          <p className="text-blue-600 font-medium text-sm">
            {isRegister ? 'Crea tu cuenta familiar' : 'Bienvenido al Aula Virtual'}
          </p>
        </div>

        <form onSubmit={handleAuth} className="space-y-4">
          <div className="space-y-1">
            <label className="text-[10px] font-black text-blue-800 ml-1 uppercase tracking-wider">Email del Tutor</label>
            <input 
              type="email" 
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="padre@correo.com"
              className="w-full bg-blue-50/50 border-2 border-blue-100 rounded-2xl px-5 py-3.5 focus:border-blue-500 focus:bg-white transition-all outline-none text-blue-900 text-sm"
            />
          </div>

          <div className="space-y-1">
            <label className="text-[10px] font-black text-blue-800 uppercase tracking-wider ml-1">Contraseña de Acceso</label>
            <input 
              type="password" 
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="••••••••"
              className="w-full bg-blue-50/50 border-2 border-blue-100 rounded-2xl px-5 py-3.5 focus:border-blue-500 focus:bg-white transition-all outline-none text-blue-900 text-sm"
            />
          </div>

          {isRegister && (
            <div className="space-y-1 animate-in slide-in-from-top-2">
              <label className="text-[10px] font-black text-indigo-800 uppercase tracking-wider ml-1">PIN Área Parental (4 dígitos)</label>
              <input 
                type="text" 
                maxLength={4}
                required
                value={parentPin}
                onChange={(e) => setParentPin(e.target.value.replace(/\D/g, ''))}
                placeholder="1234"
