import { UserRole } from '../types';

export interface AuthResponse {
  userId: string;
  email: string;
  pin: string;
  error?: string;
}

export const authService = {
  async register(email: string, password: string, parentPin: string): Promise<AuthResponse> {
    try {
      const response = await fetch('auth.php?action=register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password, parentPin })
      });
      return await response.json();
    } catch (err) {
      return { userId: '', email: '', pin: '', error: 'Error de conexión con el servidor.' };
    }
  },

  async login(email: string, password: string): Promise<AuthResponse> {
    try {
      const response = await fetch('auth.php?action=login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });
      return await response.json();
    } catch (err) {
      return { userId: '', email: '', pin: '', error: 'Error de conexión con el servidor.' };
    }
  },

  async resetPassword(email: string, pin: string, newPassword: string): Promise<{ success: boolean; error?: string }> {
    try {
      const response = await fetch('auth.php?action=reset_password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, pin, newPassword })
      });
      const data = await response.json();
      return { success: data.status === 'success', error: data.error };
    } catch (err) {
      return { success: false, error: 'Error de conexión.' };
    }
  },

  async updatePin(userId: string, newPin: string): Promise<{ success: boolean; error?: string }> {
    try {
      const response = await fetch('auth.php?action=update_pin', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId, newPin })
      });
      const data = await response.json();
      return { success: data.status === 'success', error: data.error };
    } catch (err) {
      return { success: false, error: 'Error de conexión.' };
    }
  }
};

import React, { useState } from 'react';
import { authService } from '../services/authService';

interface AuthScreenProps {
  onAuthenticated: (userId: string, email: string, pin: string) => void;
  onDemo: () => void;
}

type AuthMode = 'login' | 'register' | 'forgot';

const AuthScreen: React.FC<AuthScreenProps> = ({ onAuthenticated, onDemo }) => {
  const [mode, setMode] = useState<AuthMode>('login');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [parentPin, setParentPin] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setSuccessMsg('');

    try {
      if (mode === 'register') {
        if (parentPin.length !== 4) throw new Error('El PIN debe tener 4 dígitos.');
        const data = await authService.register(email, password, parentPin);
        if (data.error) throw new Error(data.error);
        onAuthenticated(data.userId, data.email, data.pin);
      } else if (mode === 'login') {
        const data = await authService.login(email, password);
        if (data.error) throw new Error(data.error);
        onAuthenticated(data.userId, data.email, data.pin);
      } else if (mode === 'forgot') {
        const res = await authService.resetPassword(email, parentPin, password);
        if (!res.success) throw new Error(res.error || 'Error al resetear.');
        setSuccessMsg('Contraseña actualizada. Ya puedes iniciar sesión.');
        setMode('login');
      }
    } catch (err: any) {
      setError(err.message || 'Error de conexión.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-600 to-indigo-800 flex items-center justify-center p-6 relative overflow-hidden">
      <div className="max-w-md w-full bg-white/95 backdrop-blur-xl rounded-[2.5rem] p-10 shadow-2xl border border-white/20 animate-in zoom-in duration-500">
        <div className="text-center mb-8">
          <div className="bg-blue-600 w-20 h-20 rounded-3xl shadow-xl flex items-center justify-center mx-auto mb-6">
              <span className="text-4xl">🎓</span>
          </div>
          <h1 className="text-3xl font-bold text-blue-900 tracking-tight">EduAmigo</h1>
          <p className="text-blue-600 font-medium text-sm mt-1">
            {mode === 'register' ? 'Nueva Cuenta Familiar' : mode === 'forgot' ? 'Recuperar Acceso' : 'Bienvenido de nuevo'}
          </p>
        </div>

        {successMsg && (
          <div className="mb-6 p-4 bg-green-50 text-green-600 rounded-2xl text-xs font-bold border border-green-100 animate-in fade-in">
            ✅ {successMsg}
          </div>
        )}

        <form onSubmit={handleAuth} className="space-y-4">
          <div className="space-y-1">
            <label className="text-[10px] font-black text-blue-800 ml-1 uppercase">Email del Tutor</label>
            <input 
              type="email" required value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-blue-50/50 border-2 border-blue-100 rounded-2xl px-5 py-3.5 focus:border-blue-500 outline-none text-blue-900 text-sm"
            />
          </div>

          {(mode === 'forgot' || mode === 'register') && (
            <div className="space-y-1">
              <label className="text-[10px] font-black text-indigo-800 uppercase ml-1">PIN Parental (4 dígitos)</label>
              <input 
                type="text" maxLength={4} required value={parentPin}
                onChange={(e) => setParentPin(e.target.value.replace(/\D/g, ''))}
                className="w-full bg-indigo-50/50 border-2 border-indigo-100 rounded-2xl px-5 py-3.5 focus:border-indigo-500 outline-none text-indigo-900 text-sm text-center font-black"
              />
            </div>
          )}

          <div className="space-y-1">
            <label className="text-[10px] font-black text-blue-800 uppercase ml-1">
              {mode === 'forgot' ? 'Nueva Contraseña' : 'Contraseña'}
            </label>
            <input 
              type="password" required value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-blue-50/50 border-2 border-blue-100 rounded-2xl px-5 py-3.5 focus:border-blue-500 outline-none text-blue-900 text-sm"
            />
          </div>

          {error && (
            <div className="p-3 bg-red-50 text-red-600 text-[10px] font-bold rounded-xl border border-red-100 animate-in shake">
              ⚠️ {error}
            </div>
          )}

          <button
            type="submit" disabled={loading}
            className="w-full bg-blue-600 hover:bg-blue-700 text-white py-4 rounded-2xl font-bold shadow-lg transition-all active:scale-95 disabled:opacity-50"
          >
            {loading ? 'Cargando...' : mode === 'register' ? 'Crear Cuenta ✨' : mode === 'forgot' ? 'Cambiar Contraseña 🔐' : 'Entrar 🚀'}
          </button>
        </form>

        <div className="mt-6 flex flex-col gap-3 text-center">
          {mode === 'login' && (
            <button onClick={() => setMode('forgot')} className="text-xs text-blue-400 font-bold hover:underline">
              ¿Olvidaste tu contraseña?
            </button>
          )}
          <button onClick={() => { setMode(mode === 'register' ? 'login' : 'register'); setError(''); }} className="text-sm text-blue-600 font-bold hover:underline">
            {mode === 'register' ? '¿Ya tienes cuenta? Entra' : '¿Eres nuevo? Regístrate'}
          </button>
          {mode === 'forgot' && (
             <button onClick={() => setMode('login')} className="text-xs text-gray-400 font-bold">Volver al login</button>
          )}
        </div>

        <div className="relative py-6">
          <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-gray-100"></div></div>
          <div className="relative flex justify-center text-[10px] uppercase font-black text-gray-300"><span className="bg-white px-4">O</span></div>
        </div>

        <button onClick={onDemo} className="w-full bg-yellow-400 hover:bg-yellow-500 text-yellow-900 py-3 rounded-2xl font-black text-xs shadow-md">
          PROBAR COMO INVITADO (DEMO)
        </button>
      </div>
    </div>
  );
};

