          {viewMode === 'chat' && activeChild && <ChatInterface grade={activeChild.grade} subject="Matemáticas" region={region} />}
          {viewMode === 'library' && <LibraryBrowser region={region} grade={activeChild?.grade || '1º Primaria'} setGrade={() => {}} />}
          {viewMode === 'planner' && activeChild && <StudyPlanner child={activeChild} events={events} examResults={examHistory} />}
          {viewMode === 'exam' && activeChild && <ExamMode grade={activeChild.grade} subject="Matemáticas" region={region} childId={activeChild.id} onSaveResult={async (r) => {
             await fetch(`api.php?action=save_exam&userId=${userId}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(r) });
             setExamHistory([r, ...examHistory]); awardPoints(r.pointsEarned);
