import React, { useState, useEffect, useRef } from 'react';
import { GradeLevel, Subject, ExplanationResponse, HistoryItem, ViewMode, UserRole, Region, ExamResult, Child, Reward, Country, CalendarEvent, Task, StudentRequest, EventType, SchoolCommunication, QuickNote, LocationState, Coordinate, RoutePoint, Insight } from './types';
import { requestNotificationPermission, checkUpcomingEvents, sendLocalNotification } from './services/notificationService';
import { GoogleGenAI } from "@google/genai";
import Header from './components/Header';
import HistorySidebar from './components/HistorySidebar';
import ParentDashboard from './components/ParentDashboard';
import Login from './components/Login';
import AuthScreen from './components/AuthScreen';
import ParentAuthModal from './components/ParentAuthModal';
import LibraryBrowser from './components/LibraryBrowser';
import ExamMode from './components/ExamMode';
import ChildSelector from './components/ChildSelector';
import RewardsShop from './components/RewardsShop';
import SOSModal from './components/SOSModal';
import StudentInquiry from './components/StudentInquiry';
import ChatInterface from './components/ChatInterface';
import LocationHub from './components/LocationHub';
import VisionTutor from './components/VisionTutor';
import OralPractice from './components/OralPractice';
import GamificationCenter from './components/GamificationCenter';
import StudyPlanner from './components/StudyPlanner';
import SchoolDocumentScanner from './components/SchoolDocumentScanner';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userId, setUserId] = useState<string | null>(null);
  const [parentPin, setParentPin] = useState('1234');
  const [userRole, setUserRole] = useState<UserRole>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('ask');
  const [region, setRegion] = useState<Region>('Madrid');
  const [isParentUnlocked, setIsParentUnlocked] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [showSOSModal, setShowSOSModal] = useState(false);

  const [children, setChildren] = useState<Child[]>([]);
  const [activeChildId, setActiveChildId] = useState<string | null>(null);
  const [rewards, setRewards] = useState<Reward[]>([]);
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [examHistory, setExamHistory] = useState<ExamResult[]>([]);

  const [toast, setToast] = useState<{ msg: string; type: 'info' | 'success' | 'error' } | null>(null);

  const activeChild = children.find(c => c.id === activeChildId) || null;

  const showToast = (msg: string, type: 'info' | 'success' | 'error' = 'info') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3000);
  };

  const loadDemoData = () => {
    // Datos iniciales para que el invitado vea potencial inmediato
    const demoChild: Child = { 
      id: 'demo-hugo', name: 'Hugo Invitado', avatar: '👦', points: 120, grade: '4º Primaria', 
      badges: ['math-10'], streak: { current: 3, lastActive: Date.now(), multiplier: 1.2 } 
    };
    const demoRewards: Reward[] = [
      { id: 'r1', title: '30 min Consola', pointsCost: 500, icon: '🎮' },
      { id: 'r2', title: 'Pizza Familiar', pointsCost: 1000, icon: '🍕' }
    ];
    setChildren([demoChild]);
    setRewards(demoRewards);
    setActiveChildId('demo-hugo');
  };

  const loadServerData = async (uid: string) => {
    if (userRole === 'demo') return;
    try {
      const response = await fetch(`api.php?action=get_initial_data&userId=${uid}`);
      const data = await response.json();
      if (data.children) setChildren(data.children);
      if (data.rewards) setRewards(data.rewards);
      if (data.history) setHistory(data.history);
      if (data.examHistory) setExamHistory(data.examHistory);
      if (data.events) setEvents(data.events);
      if (data.tasks) setTasks(data.tasks);
    } catch (e) { 
      console.error("Error cargando datos:", e);
      showToast("Error al conectar con la base de datos", "error");
    }
  };

  useEffect(() => {
    const savedId = sessionStorage.getItem('eduamigo_userId');
    const savedPin = sessionStorage.getItem('eduamigo_pin');
    const savedRole = sessionStorage.getItem('eduamigo_role') as UserRole;

    if (savedRole === 'demo') {
      setUserRole('demo');
      setIsAuthenticated(true);
      loadDemoData();
    } else if (savedId) {
      setUserId(savedId);
      setParentPin(savedPin || '1234');
      setUserRole('parent'); // O student según se prefiera
      setIsAuthenticated(true);
      loadServerData(savedId);
    }
    setRegion(localStorage.getItem('eduamigo_region') as Region || 'Madrid');
    requestNotificationPermission();
  }, []);

  const handleAuthenticated = (uid: string, email: string, pin: string) => {
    setUserId(uid);
    setParentPin(pin);
    setUserRole('parent');
    sessionStorage.setItem('eduamigo_userId', uid);
    sessionStorage.setItem('eduamigo_pin', pin);
    sessionStorage.setItem('eduamigo_role', 'parent');
    setIsAuthenticated(true);
    showToast("¡Bienvenido al Aula Virtual!", "success");
    loadServerData(uid);
  };

  const handleDemoMode = () => {
    setUserRole('demo');
    setIsAuthenticated(true);
    sessionStorage.setItem('eduamigo_role', 'demo');
    loadDemoData();
    showToast("Modo Invitado Activo. Los datos no se guardarán permanentemente.", "info");
  };

  const handleViewChange = (mode: ViewMode) => {
    if (mode === 'parent' && !isParentUnlocked && userRole !== 'demo') {
      setShowAuthModal(true);
      return;
    }

    // En modo demo dejamos pasar al área de padres sin PIN para que vean las opciones
    if (mode === 'parent' && userRole === 'demo') {
      setIsParentUnlocked(true);
    }

    if (['planner', 'exam', 'voice', 'ask', 'chat'].includes(mode) && !activeChildId) {
      showToast("Primero selecciona un perfil de estudiante", "info");
      setViewMode('ask');
      return;
    }

    if (mode === 'planner') showToast("Calculando tu plan de hoy con IA...", "info");
    if (mode === 'exam') showToast("Preparando simulacro de examen...", "info");
    if (mode === 'voice') showToast("Iniciando práctica oral Live...", "info");

    setViewMode(mode);
  };

  const handleInquirySuccess = async (question: string, subject: Subject, answer: ExplanationResponse) => {
    if (!activeChildId || !activeChild) return;
    const newItem: HistoryItem = {
      id: crypto.randomUUID(),
      childId: activeChildId,
      grade: activeChild.grade,
      subject, region, question, answer,
      timestamp: Date.now()
    };

    if (userRole !== 'demo' && userId) {
      await fetch(`api.php?action=save_history&userId=${userId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newItem)
      });
    }
    setHistory(prev => [newItem, ...prev].slice(0, 100));
    awardPoints(5);
  };

  const awardPoints = async (points: number) => {
    if (!activeChildId) return;
    const updatedChildren = children.map(c => {
      if (c.id === activeChildId) {
        const updated = { ...c, points: c.points + points, streak: { ...c.streak, lastActive: Date.now() } };
        if (userRole !== 'demo' && userId) {
          fetch(`api.php?action=update_child_points&userId=${userId}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(updated)
          });
        }
        return updated;
      }
      return c;
    });
    setChildren(updatedChildren);
    showToast(`¡Has ganado ${points} puntos! ⭐`, "success");
  };

  const handleAddChild = async (name: string, grade: GradeLevel, avatar: string) => {
    const id = crypto.randomUUID();
    const newChild: Child = { id, name, avatar, points: 0, grade, badges: [], streak: { current: 1, lastActive: Date.now(), multiplier: 1 } };

    if (userRole !== 'demo' && userId) {
      await fetch(`api.php?action=add_child&userId=${userId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newChild)
      });
    }
    setChildren([...children, newChild]);
    showToast(`Estudiante ${name} registrado.`, "success");
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    sessionStorage.clear();
    setUserId(null);
    setUserRole(null);
    setChildren([]);
    setActiveChildId(null);
    showToast("Sesión cerrada.");
  };

  if (!isAuthenticated) return <AuthScreen onAuthenticated={handleAuthenticated} onDemo={handleDemoMode} />;
  if (!userRole) return <Login onLogin={setUserRole} onLogout={handleLogout} />;

  if (viewMode !== 'parent' && !activeChildId) {
    return (
      <div className="min-h-screen bg-[#f0f9ff] p-8 flex flex-col items-center justify-center relative">
        {toast && (
          <div className="absolute top-6 bg-white shadow-xl px-6 py-3 rounded-full border border-blue-50 text-xs font-black animate-in slide-in-from-top duration-300">
            {toast.type === 'success' ? '✅' : toast.type === 'error' ? '❌' : 'ℹ️'} {toast.msg}
          </div>
        )}
        <ChildSelector children={children} onSelect={(c) => { setActiveChildId(c.id); showToast(`¡Hola ${c.name}!`, "success"); }} onAddChild={() => setViewMode('parent')} />
        <button onClick={handleLogout} className="mt-8 text-blue-400 font-bold hover:underline">Cerrar Sesión</button>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#f0f9ff]">
      {toast && (
        <div className="fixed top-6 left-1/2 -translate-x-1/2 z-[200] bg-white shadow-2xl px-6 py-3 rounded-full border border-blue-100 text-xs font-black animate-in slide-in-from-top duration-300 flex items-center gap-2">
          <div className={`w-2 h-2 rounded-full ${toast.type === 'success' ? 'bg-green-500' : toast.type === 'error' ? 'bg-red-500' : 'bg-blue-500'}`}></div>
          {toast.msg}
        </div>
      )}

      {showAuthModal && <ParentAuthModal correctPin={parentPin} onResult={(s) => { setIsParentUnlocked(s); if(s) setViewMode('parent'); setShowAuthModal(false); }} onCancel={() => setShowAuthModal(false)} />}
      {showSOSModal && <SOSModal onSelect={() => { setViewMode('ask'); setShowSOSModal(false); }} onClose={() => setShowSOSModal(false)} />}

      <aside className="hidden md:flex w-80 bg-white border-r border-blue-100 p-6 flex-col h-screen sticky top-0 overflow-y-auto no-scrollbar">
        {activeChild && <GamificationCenter child={activeChild} />}
        <div className="mt-8">
          <HistorySidebar history={history.filter(h => h.childId === activeChildId)} onSelect={() => setViewMode('ask')} />
        </div>
      </aside>

      <main className="flex-1 p-4 md:p-8 max-w-5xl mx-auto w-full pb-24 relative">
        <Header viewMode={viewMode} setViewMode={handleViewChange} userRole={userRole} activeChild={activeChild} />

        {userRole === 'demo' && (
          <div className="mt-4 bg-yellow-50 border border-yellow-200 p-2 rounded-xl text-center">
            <p className="text-[10px] font-black text-yellow-700 uppercase tracking-widest">⚠️ Estás en modo demostración. Los cambios no se guardarán en la nube.</p>
          </div>
        )}

        <div className="mt-8">
          {viewMode === 'ask' && activeChild && <StudentInquiry childName={activeChild.name} grade={activeChild.grade} region={region} onSuccess={handleInquirySuccess} onSOS={() => setShowSOSModal(true)} />}
          {viewMode === 'chat' && activeChild && <ChatInterface grade={activeChild.grade} subject="Matemáticas" region={region} />}
          {viewMode === 'library' && <LibraryBrowser region={region} grade={activeChild?.grade || '1º Primaria'} setGrade={() => {}} />}
          {viewMode === 'planner' && activeChild && <StudyPlanner child={activeChild} events={events} examResults={examHistory} />}
          {viewMode === 'exam' && activeChild && <ExamMode grade={activeChild.grade} subject="Matemáticas" region={region} childId={activeChild.id} onSaveResult={async (r) => {
             if (userRole !== 'demo' && userId) {
               await fetch(`api.php?action=save_exam&userId=${userId}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(r) });
             }
             setExamHistory([r, ...examHistory]); awardPoints(r.pointsEarned);
          }} />}
          {viewMode === 'voice' && activeChild && <OralPractice grade={activeChild.grade} subject="Inglés" />}
          {viewMode === 'shop' && activeChild && <RewardsShop child={activeChild} rewards={rewards} />}

          {viewMode === 'parent' && (
            <div className="space-y-8">
              <ParentDashboard 
                history={history} examHistory={examHistory} children={children} rewards={rewards} events={events} tasks={tasks} requests={[]}
                communications={[]} quickNotes={[]} locationStates={[]}
                onSelectItem={() => {}} onAddChild={handleAddChild} onUpdateRewards={setRewards} 
                onAddEvent={async (e) => {
                  const id = crypto.randomUUID(); const fe = { ...e, id };
                  if (userRole !== 'demo' && userId) {
                    await fetch(`api.php?action=add_event&userId=${userId}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(fe) });
                  }
                  setEvents([...events, fe]);
                }} 
                onDeleteEvent={(id) => { 
                  if (userRole !== 'demo') fetch(`api.php?action=delete_event&id=${id}`); 
                  setEvents(events.filter(e => e.id !== id)); 
                }}
                onAddTask={async (t) => {
                  const tid = crypto.randomUUID(); const ft = { ...t, id: tid };
                  if (userRole !== 'demo' && userId) {
                    await fetch(`api.php?action=add_task&userId=${userId}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(ft) });
                  }
                  setTasks([...tasks, ft]);
                }} 
                onToggleTask={(id) => { 
                  if (userRole !== 'demo') fetch(`api.php?action=toggle_task&id=${id}`); 
                  setTasks(tasks.map(t => t.id === id ? { ...t, completed: !t.completed } : t)); 
                }}
                onDeleteTask={(id) => { 
                  if (userRole !== 'demo') fetch(`api.php?action=delete_task&id=${id}`); 
                  setTasks(tasks.filter(t => t.id !== id)); 
                }}
                onApproveRequest={() => {}} onRejectRequest={() => {}} onUpdateTask={() => {}} onAddQuickNote={() => {}} onDeleteQuickNote={() => {}} onSyncSchoolComms={() => {}} onMarkCommRead={() => {}} onToggleTracking={() => {}} onSetLocationPoint={() => {}} onSearchAddress={async () => null} onReverseGeocode={async () => ''}
              />
              <div className="bg-white p-6 rounded-3xl shadow-sm border border-blue-50 mt-8">
                <h3 className="font-bold text-blue-900 mb-2">Seguridad Parental</h3>
                <p className="text-xs text-gray-500 mb-4">
                  {userRole === 'demo' ? 'En modo demo, el PIN es 1234.' : `Tu PIN actual para acceder al panel es: ${parentPin}`}
                </p>
                <button onClick={async () => {
                    if (userRole === 'demo') {
                      showToast("No se puede cambiar el PIN en modo invitado.");
                      return;
                    }
                    const n = prompt("Nuevo PIN (4 dígitos)");
                    if (n && n.length === 4 && userId) {
                      await fetch(`auth.php?action=update_pin`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ userId, newPin: n }) });
                      setParentPin(n); sessionStorage.setItem('eduamigo_pin', n); showToast("PIN actualizado.");
                    }
                  }} className="bg-blue-100 text-blue-600 px-4 py-2 rounded-xl text-xs font-bold"
                >Cambiar PIN</button>
              </div>
            </div>
          )}
        </div>

        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-white/95 backdrop-blur-md px-6 py-3 rounded-full shadow-2xl border border-blue-50 flex gap-4 z-40">
           <button onClick={() => handleViewChange('ask')} title="Estudiar" className={`p-2 rounded-xl transition-all ${viewMode === 'ask' ? 'bg-blue-600 text-white shadow-lg' : 'text-blue-400'}`}>💡</button>
           <button onClick={() => handleViewChange('chat')} title="Chat IA" className={`p-2 rounded-xl transition-all ${viewMode === 'chat' ? 'bg-blue-600 text-white shadow-lg' : 'text-blue-400'}`}>💬</button>
           <button onClick={() => handleViewChange('library')} title="Biblioteca" className={`p-2 rounded-xl transition-all ${viewMode === 'library' ? 'bg-blue-600 text-white shadow-lg' : 'text-blue-400'}`}>📚</button>
           <button onClick={() => handleViewChange('shop')} title="Recompensas" className={`p-2 rounded-xl transition-all ${viewMode === 'shop' ? 'bg-blue-600 text-white shadow-lg' : 'text-blue-400'}`}>🎁</button>
        </div>
      </main>
    </div>
  );
};

