import React, { useState } from 'react';
import { authService } from '../services/authService';

interface AuthScreenProps {
  onAuthenticated: (userId: string, email: string, pin: string) => void;
  onDemo: () => void;
}

type AuthMode = 'login' | 'register' | 'forgot';

const AuthScreen: React.FC<AuthScreenProps> = ({ onAuthenticated, onDemo }) => {
  const [mode, setMode] = useState<AuthMode>('login');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [parentPin, setParentPin] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setSuccessMsg('');

    try {
      if (mode === 'register') {
        if (parentPin.length !== 4) throw new Error('El PIN debe tener 4 dígitos.');
        const data = await authService.register(email, password, parentPin);
        if (data.error) throw new Error(data.error);
        onAuthenticated(data.userId, data.email, data.pin);
      } else if (mode === 'login') {
        const data = await authService.login(email, password);
        if (data.error) throw new Error(data.error);
        onAuthenticated(data.userId, data.email, data.pin);
      } else if (mode === 'forgot') {
        const res = await authService.resetPassword(email, parentPin, password);
        if (!res.success) throw new Error(res.error || 'Error al resetear.');
        setSuccessMsg('Contraseña actualizada. Ya puedes iniciar sesión.');
        setMode('login');
      }
    } catch (err: any) {
      setError(err.message || 'Error de conexión.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#001220] to-[#003d5b] flex items-center justify-center p-6 relative overflow-hidden">
      {/* Decorative tech background */}
      <div className="absolute inset-0 opacity-10 pointer-events-none">
        <svg width="100%" height="100%" xmlns="http://www.w3.org/2000/svg">
          <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse">
            <path d="M 40 0 L 0 0 0 40" fill="none" stroke="#00E5FF" strokeWidth="0.5"/>
          </pattern>
          <rect width="100%" height="100%" fill="url(#grid)" />
        </svg>
      </div>

      <div className="max-w-md w-full bg-white/95 backdrop-blur-xl rounded-[2.5rem] p-10 shadow-2xl border border-white/20 animate-in zoom-in duration-500 relative">
        <div className="text-center mb-8">
          <div className="bg-[#001220] w-20 h-20 rounded-3xl shadow-xl flex flex-col items-center justify-center mx-auto mb-6 border-2 border-[#00E5FF] transform -rotate-3 transition-transform hover:rotate-0">
              <span className="text-[#00E5FF] font-black text-3xl">21</span>
              <span className="text-[#00E5FF] text-[6px] font-black">J21 TECH</span>
          </div>
          <h1 className="text-3xl font-black text-blue-900 tracking-tight">EduAmigo</h1>
          <p className="text-[#00E5FF] font-black text-[10px] tracking-widest uppercase mt-1">
            EWOLA J21 TECH EDITION
          </p>
        </div>

        {successMsg && (
          <div className="mb-6 p-4 bg-green-50 text-green-600 rounded-2xl text-xs font-bold border border-green-100 animate-in fade-in">
            ✅ {successMsg}
          </div>
        )}

        <form onSubmit={handleAuth} className="space-y-4">
          <div className="space-y-1">
            <label className="text-[10px] font-black text-blue-800 ml-1 uppercase">Email del Tutor</label>
            <input 
              type="email" required value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-blue-50/50 border-2 border-blue-100 rounded-2xl px-5 py-3.5 focus:border-[#00E5FF] outline-none text-blue-900 text-sm"
            />
          </div>

          {(mode === 'forgot' || mode === 'register') && (
            <div className="space-y-1">
              <label className="text-[10px] font-black text-indigo-800 uppercase ml-1">PIN Parental (4 dígitos)</label>
              <input 
                type="text" maxLength={4} required value={parentPin}
                onChange={(e) => setParentPin(e.target.value.replace(/\D/g, ''))}
                className="w-full bg-indigo-50/50 border-2 border-indigo-100 rounded-2xl px-5 py-3.5 focus:border-[#00E5FF] outline-none text-indigo-900 text-sm text-center font-black"
              />
            </div>
          )}

          <div className="space-y-1">
            <label className="text-[10px] font-black text-blue-800 uppercase ml-1">
              {mode === 'forgot' ? 'Nueva Contraseña' : 'Contraseña'}
            </label>
            <input 
              type="password" required value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-blue-50/50 border-2 border-blue-100 rounded-2xl px-5 py-3.5 focus:border-[#00E5FF] outline-none text-blue-900 text-sm"
            />
          </div>

          {error && (
            <div className="p-3 bg-red-50 text-red-600 text-[10px] font-bold rounded-xl border border-red-100 animate-in shake">
              ⚠️ {error}
            </div>
          )}

          <button
            type="submit" disabled={loading}
            className="w-full bg-[#001220] hover:bg-[#002a42] text-[#00E5FF] py-4 rounded-2xl font-black shadow-lg transition-all active:scale-95 disabled:opacity-50 border border-[#00E5FF]/30"
          >
            {loading ? 'Sincronizando...' : mode === 'register' ? 'Registrar Familia J21 ✨' : mode === 'forgot' ? 'Resetear 🔐' : 'Iniciar Sesión 🚀'}
          </button>
        </form>

        <div className="mt-6 flex flex-col gap-3 text-center">
          {mode === 'login' && (
            <button onClick={() => setMode('forgot')} className="text-xs text-blue-400 font-bold hover:underline">
