const CACHE_NAME = 'eduamigo-v1.0.1';
const ASSETS = [
  '/',
  '/index.html',
  '/manifest.json'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return cache.addAll(ASSETS);
    })
  );
});

self.addEventListener('fetch', (event) => {
  // Solo cacheamos peticiones GET de documentos y recursos locales
  if (event.request.method !== 'GET') return;

  event.respondWith(
    caches.match(event.request).then((response) => {
      return response || fetch(event.request).then((fetchRes) => {
        // No cacheamos llamadas a la API de Google o externas dinámicas
        if (event.request.url.includes('googleapis') || event.request.url.includes('genai')) {
            return fetchRes;
        }
        return fetchRes;
      });
    })
  );
});

