import React, { useState, useEffect, useRef } from 'react';
import { GradeLevel, Subject, ExplanationResponse, HistoryItem, ViewMode, UserRole, Region, ExamResult, Child, Reward, Country, CalendarEvent, Task, StudentRequest, EventType, SchoolCommunication, QuickNote, LocationState, Coordinate, RoutePoint, Insight } from './types';
